// The coach's questions (picture 69, Oct 15, 2026) and the chat they make. Picture 185 (Nov 4, 2026):
// "Do you have a car now?" comes right after the goal, the car is picked in a pop-up (year, make, model,
// miles), the kind of car starts like theirs, and a one-time check when they pick something smaller.
import type { Answers } from '@/state/answers';
import { BUDGETS, carForMine } from '@/data/cars';
import { carKindOf, kindFromName, kindWords, seatsOfKind, type CarKind } from '@/data/car-kind';

export type Step = {
  key: keyof Answers;
  ask: (a: Answers) => string;
  grid?: boolean; // the feature icon grid (picture 52 A)
  options?: string[] | ((a: Answers) => string[]);
  multi?: boolean;
  placeholder?: string;
  reply: (answer: string, a: Answers) => string;
  skipIf?: (a: Answers) => boolean;
  carNow?: boolean; // the "car you have now" pop-up (picture 185)
  tiles?: boolean; // the kind-of-car photo tiles (picture 68 B)
};
export const UPGRADE = 'Upgrade my car';
export const ALL_KINDS = 'Not sure, show me all';
export const BOTH = 'Show both';
const loan = (a: Answers) => a.pay !== 'Car loan';
export const hasCar = (a: Answers) => a.goal === UPGRADE || (a.current ?? '').startsWith('Yes');

/** "2019 Nissan Pathfinder · 92,000 mi" → the car and the miles. */
export function splitCarAnswer(v: string): { car: string; miles?: number } {
  const [car, rest] = v.split(' · ');
  const miles = Number((rest ?? '').replace(/[^\d]/g, '')) || undefined;
  return { car: car.trim(), miles };
}
export const carAnswer = (car: string, miles?: number) => (miles ? `${car} · ${miles.toLocaleString('en-US')} mi` : car);

/** Their car's model name only ("2019 Nissan Pathfinder" → "Pathfinder"), for short questions. */
export function modelOf(myCar?: string) {
  const w = (myCar ?? '').replace(/^\s*(19|20)\d\d\s+/, '').split(/\s+/);
  return w.length > 1 ? w.slice(1).join(' ') : w[0] || 'car';
}
const myKind = (a: Answers): CarKind | undefined => (a.myCarKind ? { kind: a.myCarKind as CarKind['kind'], seats: a.myCarSeats ?? seatsOfKind(a.myCarKind) ?? 5 } : undefined);
const plural = (k: string) => (k === 'SUV (3 rows)' ? 'SUVs with 3 rows' : k === 'Sports car' ? 'sports cars' : k === 'SUV' ? 'SUVs' : `${k.toLowerCase()}s`);
/** "SUVs like mine" in the smaller-pick check. */
export const likeMine = (a: Answers) => `${plural(a.myCarKind ?? 'SUV').replace(/^./, (c) => c.toUpperCase())} like mine`;
/** Picked a kind with fewer seats than their car? (A 7-seat Pathfinder and "Sedan".) */
export function pickedSmaller(a: Answers) {
  const mine = a.myCarSeats ?? seatsOfKind(a.myCarKind);
  const want = seatsOfKind(a.kind);
  return !!mine && !!want && want < mine && a.kind !== a.myCarKind;
}

export const STEPS: Step[] = [
  { key: 'goal', ask: () => 'First up: what’s the car mainly for?',
    options: ['Family', 'Save money', 'Upgrade my car', 'Side hustle', 'Drive for apps', 'Adventure', 'Luxury', 'Just browsing'],
    reply: (g) => ({ 'Save money': 'Smart move. Let’s keep your costs low.', Family: 'Love it. Safety and space come first.', 'Side hustle': 'Nice! Let’s find a car that pays for itself.', 'Drive for apps': 'Got it. Low gas cost and comfy back seats.', Adventure: 'Fun! 4x4 and room for gear.', 'Upgrade my car': 'Great. Let’s find something better than what you have.', Luxury: 'Treat yourself! Comfort and style first.' } as Record<string, string>)[g] ?? 'Got it.' },
  // Asked early now (picture 185): the kind of car, the seats and the step up all depend on it.
  { key: 'current', ask: () => 'Do you have a car now?',
    options: ['Yes, upgrade it', 'Yes, something similar', 'No, something new to me', 'No, this is my first car'],
    skipIf: (a) => a.goal === UPGRADE,
    reply: (c) => (c.startsWith('Yes') ? 'Great. Which car do you drive?' : c.includes('first car') ? 'Exciting! I’ll explain each step and keep things simple.' : 'Fun! A fresh start.') },
  { key: 'myCar', ask: (a) => (a.goal === UPGRADE ? 'Let’s start with the car you have now. Pick the year, brand and model.' : 'Pick the year, brand and model.'),
    carNow: true, skipIf: (a) => !hasCar(a), placeholder: 'Or type it, like: 2020 Chevy Trax',
    reply: (v, a) => {
      const { car } = splitCarAnswer(v);
      if (!car) return a.goal === UPGRADE ? 'No problem. I’ll show good upgrades for any car.' : 'No problem.';
      const k = myKind(a);
      const end = a.goal === UPGRADE ? 'I’ll only show cars that are a real step up.' : 'I’ll compare everything to it.';
      return k ? `Got it, a ${car}: ${kindWords(k)}. ${end}` : `Got it, a ${car}. ${end}`;
    } },
  { key: 'apps', ask: () => 'Which apps do you drive for? Pick all you use.', multi: true,
    options: ['Uber', 'Lyft', 'DoorDash', 'Instacart', 'Other'], skipIf: (a) => a.goal !== 'Drive for apps',
    reply: () => 'Good to know: Uber and Lyft have rules about how old a car can be, and they change by city. I’ll flag older cars. Check your city’s rules before you buy.' },
  { key: 'kind', ask: () => 'What kind of car are you picturing?', tiles: true, options: [ALL_KINDS],
    reply: (k) => (!k || k === ALL_KINDS ? 'No problem. I’ll show every kind.' : `${k}. Good choice.`) },
  // Picked smaller than their car: ask once. Their answer always wins.
  { key: 'kindCheck', ask: (a) => `Quick check: your ${modelOf(a.myCar)} seats ${a.myCarSeats ?? seatsOfKind(a.myCarKind)}. ${plural(a.kind ?? '').replace(/^./, (c) => c.toUpperCase())} seat ${seatsOfKind(a.kind)}. Still want ${plural(a.kind ?? '')}?`,
    options: (a) => [`Yes, ${plural(a.kind ?? '')}`, BOTH, likeMine(a)], skipIf: () => true, // Nov 6, 2026 (picture 204): both lists always show, so no more 'Still want sedans?'
    reply: (v, a) => (v === BOTH ? `Done. I’ll show ${plural(a.kind ?? '')} and ${plural(a.myCarKind ?? '')} side by side.` : v === likeMine(a) ? `Got it. ${plural(a.myCarKind ?? '').replace(/^./, (c) => c.toUpperCase())} it is.` : 'Got it. Your answer wins.') },
  { key: 'newUsed', ask: () => 'New, used, or either?', options: ['New only', 'Either', 'Used only'],
    reply: (v) => (v === 'New only' ? 'New it is. I’ll show this year’s models.' : v === 'Used only' ? 'Smart. Used cars cost much less.' : 'Great, that gives you the most choices.') },
  { key: 'pay', ask: () => 'How will you pay?', options: ['Cash', 'Car loan', 'Lease', 'Not sure yet'],
    reply: (v) => (v === 'Car loan' ? 'Got it. A few quick money questions.' : v === 'Lease' ? 'Leases are for new cars. I’ll keep that in mind.' : v === 'Cash' ? 'Nice. No monthly payment to worry about.' : 'No problem. We can figure it out together.') },
  { key: 'budget', ask: () => 'What budget feels comfortable?',
    options: [...BUDGETS, 'Not sure yet'], skipIf: (a) => a.pay === 'Car loan',
    reply: (b) => (b === 'Not sure yet' ? 'No problem. I’ll show a mix, and we can talk money later.' : b === BUDGETS[0] ? 'Great. I’ll look at newer used cars that last and cost little to run.' : 'Nice range. Lots of great options there.') },
  { key: 'monthly', ask: () => 'What monthly payment feels OK?', options: ['About $250', 'About $300', 'About $400', 'About $500', 'About $600+', 'Not sure'], skipIf: loan,
    reply: (v) => (v === 'Not sure' || !v ? 'No problem. I’ll show a payment estimate for each car.' : 'Got it. I’ll keep picks near that, with an estimate for each.') },
  { key: 'down', ask: () => 'Money down, about?', options: ['$0', 'Under $1,000', '$1,000 – $2,500', '$2,500 – $5,000', '$5,000+'], skipIf: loan,
    reply: () => 'Thanks. Money down lowers your payment.' },
  { key: 'credit', ask: () => 'And your credit, about? (We never check it.)', options: ['Rebuilding', 'Fair', 'Good', 'Great', 'Not sure'], skipIf: loan,
    reply: (v) => (v === 'Rebuilding' ? 'Thanks for telling me. I’ll show cars with payments that stay safe.' : 'Got it.') },
  { key: 'mustHaves', ask: (a) => (a.goal === UPGRADE && a.myCar
      ? `What do you want that your ${a.myCar} doesn’t have? Tap once to pick. Tap again for a gold star = must have.`
      : 'What do you want in your car? Tap once to pick. Tap again for a gold star = must have.'),
    grid: true,
    reply: (m) => (m ? 'Good picks. I’ll check every car for those.' : 'No problem. I’ll keep it open.') },
  { key: 'trade', ask: (a) => `Want to trade in your ${a.myCar || 'car'}? I’ll show what it’s worth (estimate).`, options: ['Yes, trade it in', 'No, I’ll keep or sell it'],
    skipIf: (a) => !hasCar(a) || !a.myCar,
    reply: (v) => (v.startsWith('Yes') ? 'Great. I’ll count it toward your next car.' : 'Got it.') },
  { key: 'riders', ask: () => 'How many people ride with you most days?',
    options: ['Just me', '2 – 3', '4 – 5', '6 or more'],
    reply: () => 'Perfect. I’ll make sure everyone fits.' },
  { key: 'when', ask: () => 'When are you buying?', options: ['Just looking', 'This month', 'In 1–3 months', 'Later'],
    reply: (v) => (v === 'Just looking' ? 'Perfect. Browse with no pressure.' : v === 'This month' ? 'Let’s get you ready: real cars near you and what to ask the dealer.' : 'Good. You’ll have time to plan and save.') },
  { key: 'zip', ask: () => 'Last one! What’s your ZIP code? I’ll look for cars near you.', placeholder: 'ZIP code',
    options: ['30311'], reply: (z) => (z ? `Thanks! Looking near ${z}.` : 'No problem. You can add it later.') },
];

export const optionsOf = (s: Step, a: Answers) => (typeof s.options === 'function' ? s.options(a) : s.options ?? []);

/** One chat answer into the answers. `info` = facts we looked up while they answered (their car's kind and miles). */
export function applyAnswer(a: Answers, key: keyof Answers, v: string, info?: Partial<Answers>): Answers {
  const out: Answers = { ...a, mustHaves: a.mustHaves };
  if (key === 'mustHaves') { out.mustHaves = info?.mustHaves ?? (v ? v.split(', ') : []); out.wants = info?.wants ?? out.wants; return out; }
  if (key === 'myCar') {
    const { car, miles } = splitCarAnswer(v);
    out.myCar = car || undefined;
    out.myCarMiles = miles;
    out.myCarKind = info?.myCarKind;
    out.myCarSeats = info?.myCarSeats;
    return out;
  }
  (out as Record<string, unknown>)[key] = v;
  if (key === 'goal') out.current = v === UPGRADE ? 'Yes, upgrade it' : undefined;
  if (key === 'current') {
    out.firstCar = v.includes('first car') ? 'Yes' : 'No';
    if (!v.startsWith('Yes')) { out.myCar = undefined; out.myCarMiles = undefined; out.myCarKind = undefined; out.myCarSeats = undefined; out.trade = undefined; }
  }
  if (key === 'kind') out.kindCheck = undefined;
  return out;
}

export type Msg = { from: 'coach' | 'me'; text: string; at?: number }; // at = which answer (tap to change it)
const HELLO = 'Hey! I’m your Carvessa coach. A few quick questions and I’ll find your perfect ride.';

/** Walk the steps with the answers given so far. `known` = the saved answers (for facts that aren't in the chat words, like their car's kind). */
export function walk(done: string[], known?: Answers): { msgs: Msg[]; step: Step | null; stepNo: number; total: number; a: Answers } {
  const m: Msg[] = [{ from: 'coach', text: HELLO }];
  let a: Answers = { mustHaves: [] };
  let n = 0;
  const count = () => STEPS.filter((x) => !x.skipIf?.(a)).length;
  for (const s of STEPS) {
    if (s.skipIf?.(a)) continue;
    if (n >= done.length) { m.push({ from: 'coach', text: s.ask(a) }); return { msgs: m, step: s, stepNo: n + 1, total: count(), a }; }
    const ans = done[n];
    m.push({ from: 'coach', text: s.ask(a) }, { from: 'me', text: ans || 'Skip', at: n });
    const info = s.key === 'myCar' && known && splitCarAnswer(ans).car === known.myCar ? { myCarKind: known.myCarKind, myCarSeats: known.myCarSeats } : undefined;
    a = applyAnswer(a, s.key, ans, s.key === 'mustHaves' ? { mustHaves: known?.mustHaves, wants: known?.wants } : info);
    m.push({ from: 'coach', text: s.reply(ans, a) });
    n++;
  }
  m.push({ from: 'coach', text: 'All set! I found your top 3 matches.' });
  return { msgs: m, step: null, stepNo: count(), total: count(), a };
}

/** Words for a chat in the History list: "Upgrade my car · 2019 Pathfinder" / "Family · SUV · About $400/mo". */
export function chatTitle(a: Answers): string {
  const money = a.pay === 'Car loan' && a.monthly && a.monthly !== 'Not sure' ? `${a.monthly}/mo` : a.budget && a.budget !== 'Not sure yet' ? a.budget : '';
  const car = a.myCar ? a.myCar.replace(/^\s*((?:19|20)\d\d)\s+\S+\s+/, '$1 ') : '';
  const kind = a.kind && a.kind !== ALL_KINDS ? a.kind : '';
  return [a.goal || 'Coach chat', a.goal === UPGRADE ? car : kind, a.goal === UPGRADE ? kind : money].filter(Boolean).join(' · ');
}

/** Their garage car as a coach answer + what kind it is (no internet: our list and car data). */
export function carNowOf(c: { year: number; make: string; model: string; miles?: number }): { text: string; info: Partial<Answers> } {
  const k = kindFromName(c.model) ?? (() => { const ours = carForMine(c.make, c.model); return ours ? carKindOf(ours.body, ours.seats) : undefined; })();
  return { text: carAnswer(`${c.year} ${c.make} ${c.model}`, c.miles), info: { myCarKind: k?.kind, myCarSeats: k?.seats } };
}
