// Login (picture 79 · 1 A, Oct 17, 2026): a slideshow of cars behind one big "Start looking" button.
// Guests get in with one tap; Log in / Sign up open the account sheet (Google sign-in lives there).
import { LinearGradient } from 'expo-linear-gradient';
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { Animated, Image, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { CarPhoto } from '@/components/car-photo';
import { ArrowIcon } from '@/components/icons';
import { Body, Btn, H, Logo, tap } from '@/components/ui';
import { SHOWROOM } from '@/data/cars';
import { useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';
import { Sky, useSky } from '@/components/sky';
import { C, F, PAD, skyLook, themed } from '@/theme';
import { LangChip } from '@/components/lang-picker';
import { Pressable, Text } from '@/components/t';

const SAGE = require('../../assets/car/drawn-sage.png');

export default function Login() {
  const { prefs, setPrefs } = useSaved();
  const { session } = useAuth();
  const enter = () => {
    if (!prefs.seenLogin) setPrefs({ ...prefs, seenLogin: true });
    router.replace('/home');
  };
  // Signed up or logged in from here? Go straight Home.
  useEffect(() => { if (session) enter(); }, [session]); // eslint-disable-line react-hooks/exhaustive-deps
  // Sunset Calm: the sky Welcome. Clean and the older looks: the dark car slideshow (picture 82 #4).
  return skyLook ? <Welcome enter={enter} /> : <Slideshow enter={enter} />;
}

// Design C · Sunset Calm Welcome (Oct 17, 2026): the sky with the glowing gold V as the sun (the only screen with
// the V sun), the skyline, our drawn green car on a road, and one big "Start looking" button.
function Welcome({ enter }: { enter: () => void }) {
  const { openSignIn } = useAuth();
  const sky = useSky();
  const { width, height } = useWindowDimensions();
  const skyH = Math.max(340, Math.round(height * 0.56));
  const carW = Math.min(width * 0.64, 380);
  const carH = (carW * 179) / 600;
  const night = sky.phase === 'night';
  return (
    <View style={{ flex: 1, backgroundColor: night ? '#0A100D' : '#1F4D3A' }}>
      <Sky height={skyH} phase={sky.phase} skyline={120} sun={{ top: skyH - 200, size: 84 }}>
        <SafeAreaView edges={['top']}>
          <View style={[s.top, { justifyContent: 'center' }]}>
            <Logo home={false} sky={sky.light ? 'light' : 'dark'} size={16} />
            <View style={{ position: 'absolute', right: PAD, top: 10 }}><LangChip /></View>
          </View>
          <View style={{ alignItems: 'center', paddingHorizontal: PAD, marginTop: 6 }}>
            <Text style={[s.hola, { color: sky.ink }]}>¡Hola!</Text>
            <Text style={[s.big, { color: sky.ink }]} accessibilityRole="header">Car shopping</Text>
            <Text style={[s.big, { color: sky.soft }]}>can be calm.</Text>
          </View>
        </SafeAreaView>
      </Sky>
      {/* The road: a dashed line, our car parked on it. */}
      <View style={[s.dash, { top: skyH + carH * 0.38 + 18 }]} pointerEvents="none">
        {Array.from({ length: Math.ceil(width / 44) }, (_, k) => <View key={k} style={s.dashBit} />)}
      </View>
      <Image source={SAGE} accessible accessibilityLabel="A green car" style={{ position: 'absolute', top: skyH - carH * 0.62, left: (width - carW) / 2, width: carW, height: carH }} resizeMode="contain" />
      <SafeAreaView edges={['bottom']} style={s.bottom}>
        <Text style={s.road}>Find a car you can really afford. No account needed. Free.</Text>
        <Pressable onPress={() => { tap(); enter(); }} accessibilityRole="button" style={({ pressed }) => [s.start, pressed && { opacity: 0.85 }]}>
          <Text style={s.startText}>Start looking</Text>
          <ArrowIcon color="#1F4D3A" size={18} />
        </Pressable>
        <View style={s.row}>
          <Text style={s.road}>Have an account? </Text>
          <Pressable onPress={() => { tap(); openSignIn(undefined, 'login'); }} accessibilityRole="button" hitSlop={8} style={s.link}><Text style={s.linkText}>Log in</Text></Pressable>
          <Text style={s.road}> · </Text>
          <Pressable onPress={() => { tap(); openSignIn(undefined, 'join'); }} accessibilityRole="button" hitSlop={8} style={s.link}><Text style={s.linkText}>Sign up</Text></Pressable>
        </View>
        <Text style={[s.road, { fontSize: 11, marginBottom: 6 }]}>By continuing you agree to our{' '}
          <Text style={s.legalCalm} onPress={() => router.push({ pathname: '/legal', params: { tab: 'terms' } })} accessibilityRole="link">Terms</Text> and{' '}
          <Text style={s.legalCalm} onPress={() => router.push({ pathname: '/legal', params: { tab: 'privacy' } })} accessibilityRole="link">Privacy Policy</Text>.</Text>
      </SafeAreaView>
    </View>
  );
}

// The older looks keep the car slideshow (picture 79 · 1 A).
function Slideshow({ enter }: { enter: () => void }) {
  const { openSignIn } = useAuth();
  const [i, setI] = useState(0);
  const [fades] = useState(() => SHOWROOM.map((_, k) => new Animated.Value(k === 0 ? 1 : 0)));

  // Background slideshow: a new car every 3.5 seconds, with a soft fade.
  useEffect(() => {
    const t = setInterval(() => setI((x) => (x + 1) % SHOWROOM.length), 3500);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    Animated.parallel(fades.map((v, k) => Animated.timing(v, { toValue: k === i ? 1 : 0, duration: 700, useNativeDriver: true }))).start();
  }, [i, fades]);

  return (
    <View style={{ flex: 1, backgroundColor: '#0E1014' }}>
      <View style={s.hero}>
        {SHOWROOM.map((c, k) => (
          <Animated.View key={c.id} style={[StyleSheet.absoluteFill, { opacity: fades[k] }]} pointerEvents="none">
            <CarPhoto id={c.id} label={c.name} style={{ flex: 1 }} />
          </Animated.View>
        ))}
        <LinearGradient colors={['rgba(14,16,20,0.85)', 'rgba(14,16,20,0)', 'rgba(14,16,20,0.25)', '#0E1014']} locations={[0, 0.3, 0.55, 1]} style={StyleSheet.absoluteFill} pointerEvents="none" />
        <SafeAreaView edges={['top']}>
          <View style={s.top}>
            <Logo home={false} onPhoto />
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 14 }}>
              <LangChip />
            </View>
          </View>
        </SafeAreaView>
        <View style={s.headline}>
          <H size={44} style={{ color: '#FFFFFF' }}>Find a car you can really afford</H>
          <Body style={{ color: '#D6D6D6', marginTop: 4 }}>No account needed. Free.</Body>
        </View>
      </View>

      <SafeAreaView edges={['bottom']} style={{ paddingTop: 14, paddingHorizontal: PAD, gap: 12, alignItems: 'stretch' }}>
        <Btn label="Start looking" kind="yellow" iconRight={<ArrowIcon color={C.onAccent} size={18} />} onPress={() => { tap(); enter(); }} />
        <View style={s.row}>
          <Body style={{ color: '#D6D6D6', fontSize: 14 }}>Have an account? </Body>
          <Pressable onPress={() => { tap(); openSignIn(undefined, 'login'); }} accessibilityRole="button" hitSlop={8} style={s.link}><Text style={s.linkText}>Log in</Text></Pressable>
          <Body style={{ color: '#8E97A5', fontSize: 14 }}> · </Body>
          <Pressable onPress={() => { tap(); openSignIn(undefined, 'join'); }} accessibilityRole="button" hitSlop={8} style={s.link}><Text style={s.linkText}>Sign up</Text></Pressable>
        </View>
        <Body style={{ fontSize: 11, color: '#8E97A5', textAlign: 'center', marginBottom: 6 }}>By continuing you agree to our{' '}
          <Text style={s.legal} onPress={() => router.push({ pathname: '/legal', params: { tab: 'terms' } })} accessibilityRole="link">Terms</Text> and{' '}
          <Text style={s.legal} onPress={() => router.push({ pathname: '/legal', params: { tab: 'privacy' } })} accessibilityRole="link">Privacy Policy</Text>.</Body>
      </SafeAreaView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  legal: { fontFamily: F.bodyBold, color: '#CDB38B', textDecorationLine: 'underline' },
  hero: { flex: 1, minHeight: 300, backgroundColor: '#0E1014', overflow: 'hidden' },
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10 },
  headline: { position: 'absolute', left: PAD, right: PAD, bottom: 12 },
  row: { flexDirection: 'row', justifyContent: 'center', alignItems: 'center', flexWrap: 'wrap' },
  link: { flexDirection: 'row', alignItems: 'center', gap: 6, minHeight: 44 },
  linkText: { fontFamily: F.bodyBold, fontSize: 14.5, color: '#FFFFFF' },
  hola: { fontFamily: F.bodySemi, fontSize: 15, opacity: 0.92 },
  big: { fontFamily: F.head, fontSize: 32, lineHeight: 36, letterSpacing: -0.6, textAlign: 'center' },
  dash: { position: 'absolute', left: 0, right: 0, top: 0, flexDirection: 'row', gap: 18, opacity: 0.6, overflow: 'hidden' },
  dashBit: { width: 26, height: 3, backgroundColor: '#FFE3B0' },
  bottom: { flex: 1, justifyContent: 'flex-end', paddingHorizontal: PAD + 2, gap: 10, alignItems: 'stretch' },
  road: { fontFamily: F.body, fontSize: 13.5, color: '#CFE6D8', textAlign: 'center' },
  start: { height: 56, borderRadius: 999, backgroundColor: '#FFC896', flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8, marginTop: 4 },
  startText: { fontFamily: F.head, fontSize: 17, color: '#1F4D3A' },
  legalCalm: { fontFamily: F.bodyBold, color: '#FFE3B0', textDecorationLine: 'underline' },
}));
