// Text, TextInput and Pressable that speak the person's language (see i18n/index.ts).
// Use these instead of the ones from react-native.
import { Children, createContext, createElement, forwardRef, useContext, useEffect, useImperativeHandle, useRef, type ReactNode, type RefObject } from 'react';
import {
  Pressable as RNPressable, Text as RNText, TextInput as RNTextInput,
  StyleSheet, type PressableProps, type StyleProp, type TextInputProps, type TextProps, type TextStyle, type View,
} from 'react-native';

import { tr, trLine } from '@/i18n';
import { calm, F } from '@/theme';

const piece = (c: ReactNode) => (typeof c === 'string' ? tr(c) : c);
const label = (l?: string) => (l ? tr(l) : l);

// Sunset Calm (design C) uses Manrope in normal case, not tall capital headings. Screens were made for
// the narrow capital font, so big capital headings switch to normal case and a bit smaller here, in one place.
// Small capital labels (under 15) stay capitals with less letter spacing.
function soften(style: StyleProp<TextStyle>): StyleProp<TextStyle> {
  const f = StyleSheet.flatten(style);
  if (!f || f.fontFamily !== F.head) return style;
  const size = f.fontSize ?? 14;
  if (f.textTransform === 'uppercase' && size < 15) return [style, { letterSpacing: Math.min(f.letterSpacing ?? 0, 1) }];
  const k = size >= 30 ? 0.74 : size >= 20 ? 0.82 : 0.88;
  return [style, {
    textTransform: 'none', fontSize: Math.round(size * k * 2) / 2,
    lineHeight: f.lineHeight ? Math.round(size * k * 1.2) : undefined, letterSpacing: size >= 20 ? -0.3 : 0,
  }];
}

export const Text = forwardRef<RNText, TextProps>(function Text({ children, accessibilityLabel, ...p }, ref) {
  let kids: ReactNode[];
  if (!Array.isArray(children)) kids = [piece(children)];
  else if (children.every((c) => typeof c === 'string' || typeof c === 'number')) kids = trLine(children as (string | number)[]);
  else kids = Children.toArray(children).map(piece);
  const style = calm ? soften(p.style) : p.style;
  return createElement(RNText, { ...p, style, ref, accessibilityLabel: label(accessibilityLabel) }, ...kids);
});

// A sheet that holds text boxes (components/keyboard-sheet.tsx) listens here, so it can move out of the
// keyboard's way when a box gets focus, even on phones where the keyboard events don't fire.
// Boxes also say when they appear and go away, so the sheet can ask "does any of my boxes have focus?"
// (a box focused from code right after it appears doesn't always fire onFocus).
export type BoxEvent = 'focus' | 'blur' | 'add' | 'remove';
export const InputFocus = createContext<null | ((e: BoxEvent, box: RefObject<RNTextInput | null>) => void)>(null);

export const TextInput = forwardRef<RNTextInput, TextInputProps>(function TextInput({ placeholder, accessibilityLabel, onFocus, onBlur, ...p }, ref) {
  const tell = useContext(InputFocus);
  const box = useRef<RNTextInput>(null);
  useImperativeHandle(ref, () => box.current as RNTextInput);
  useEffect(() => { tell?.('add', box); return () => tell?.('remove', box); }, [tell]);
  return <RNTextInput {...p} ref={box} placeholder={label(placeholder)} accessibilityLabel={label(accessibilityLabel)}
    onFocus={(e) => { tell?.('focus', box); onFocus?.(e); }} onBlur={(e) => { tell?.('blur', box); onBlur?.(e); }} />;
});

export const Pressable = forwardRef<View, PressableProps>(function Pressable({ accessibilityLabel, ...p }, ref) {
  return <RNPressable {...p} ref={ref} accessibilityLabel={label(accessibilityLabel)} />;
});
