// Privacy Policy and Terms of Use (picture 29, option B "short version first", picked Oct 12, 2026).
// Tabs for Privacy / Terms, the short version on top, a read-out-loud button, then the full text.
import * as Speech from 'expo-speech';
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { Linking, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon, PhoneIcon, PinIcon, SpeakerIcon, TagIcon } from '@/components/icons';
import { Body, H, Label, SquareBtn, tap } from '@/components/ui';
import { CONTACT_EMAIL, LEGAL_UPDATED, PRIVACY, TERMS, type Point } from '@/data/legal';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { lang } from '@/i18n';

const GLYPH: Record<string, string> = { $: '$', '@': '@', x: '✕', '~': '≈', star: '★', '!': '!' };

function Dot({ icon }: { icon: string }) {
  return (
    <View style={s.dot}>
      {icon === 'pin' ? <PinIcon size={15} color={C.onAccent} /> : icon === 'phone' ? <PhoneIcon size={15} color={C.onAccent} /> : icon === 'tag' ? <TagIcon size={15} color={C.onAccent} /> : <Text style={s.dotText}>{GLYPH[icon] ?? '•'}</Text>}
    </View>
  );
}

export default function Legal() {
  const params = useLocalSearchParams<{ tab?: string }>();
  const [picked, setPicked] = useState<'privacy' | 'terms' | null>(null);
  const tab = picked ?? (params.tab === 'terms' ? 'terms' : 'privacy');
  const doc = tab === 'terms' ? TERMS : PRIVACY;
  const [reading, setReading] = useState(false);
  const scroll = useRef<ScrollView>(null);

  useEffect(() => () => { Speech.stop(); }, []);

  const pick = (t: 'privacy' | 'terms') => { tap(); Speech.stop(); setReading(false); setPicked(t); scroll.current?.scrollTo({ y: 0, animated: false }); };
  const read = () => {
    tap();
    if (reading) { Speech.stop(); setReading(false); return; }
    const words = [`${doc.name}. The short version.`, ...doc.short.map((p: Point) => `${p.bold ? p.bold + ' ' : ''}${p.text}`),
      'The full text.', ...doc.sections.flatMap((x) => [x.title, ...x.body])].join(' ');
    setReading(true);
    Speech.speak(words, { language: 'en-US', // the text is in English for now
      onDone: () => setReading(false), onStopped: () => setReading(false), onError: () => setReading(false) });
  };

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title={tab === 'terms' ? 'Terms' : 'Privacy'} back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <Label>{tab === 'terms' ? 'Terms' : 'Privacy'}</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView ref={scroll} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40 }}>
        <View style={s.tabs} accessibilityRole="tablist">
          {(['privacy', 'terms'] as const).map((t) => (
            <Pressable key={t} onPress={() => pick(t)} style={[s.tab, tab === t && s.tabOn]} accessibilityRole="tab" accessibilityState={{ selected: tab === t }}>
              <Text style={[s.tabText, tab === t && s.tabTextOn]}>{t === 'privacy' ? 'Privacy' : 'Terms'}</Text>
            </Pressable>
          ))}
        </View>

        <View style={s.short}>
          <Label style={{ color: C.yellow, marginBottom: 10 }}>The short version</Label>
          {doc.short.map((p) => (
            <View key={p.text} style={s.point}>
              <Dot icon={p.icon} />
              <Body style={{ flex: 1, fontSize: 15.5, lineHeight: 21 }}>
                {p.bold ? <Text style={{ fontFamily: F.bodyBold }}>{p.bold} </Text> : null}{p.text}
              </Body>
            </View>
          ))}
        </View>

        <Pressable onPress={read} style={s.read} accessibilityRole="button" accessibilityLabel={reading ? 'Stop reading out loud' : 'Read it out loud'}>
          <SpeakerIcon size={18} color={C.yellow} on />
          <Text style={s.readText}>{reading ? 'Stop reading' : 'Read it out loud'}</Text>
        </Pressable>

        <H size={30} style={{ marginTop: 22 }}>{doc.name}</H>
        <Body style={{ color: C.muted, fontSize: 13, marginTop: 2 }}>Last updated {LEGAL_UPDATED}</Body>
        {lang === 'es' && <Body style={{ color: C.yellow, fontSize: 14, marginTop: 6 }}>Privacy and Terms are in English for now. A Spanish version is coming.</Body>}
        {doc.sections.map((x) => (
          <View key={x.title} style={{ marginTop: 16 }}>
            <Body bold style={{ fontSize: 17, marginBottom: 4 }}>{x.title}</Body>
            {x.body.map((b) => <Body key={b.slice(0, 40)} style={s.p}>{b}</Body>)}
          </View>
        ))}
        <Pressable onPress={() => { tap(); Linking.openURL(`mailto:${CONTACT_EMAIL}`); }} accessibilityRole="link" style={{ marginTop: 14 }}>
          <Body bold style={{ color: C.yellow, textDecorationLine: 'underline' }}>Email {CONTACT_EMAIL}</Body>
        </Pressable>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: PAD, paddingVertical: 10 },
  tabs: { flexDirection: 'row', backgroundColor: C.card, borderRadius: 14, padding: 4, borderWidth: 1, borderColor: C.line, marginBottom: 12 },
  tab: { flex: 1, alignItems: 'center', paddingVertical: 10, borderRadius: 10 },
  tabOn: { backgroundColor: C.fill },
  tabText: { fontFamily: F.bodyBold, fontSize: 15, color: C.muted },
  tabTextOn: { color: C.onAccent },
  short: { backgroundColor: C.hero, borderRadius: 18, padding: 14, paddingBottom: 4 },
  point: { flexDirection: 'row', gap: 10, alignItems: 'flex-start', marginBottom: 10 },
  dot: { width: 28, height: 28, borderRadius: 14, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  dotText: { color: C.onAccent, fontFamily: F.bodyBold, fontSize: 14 },
  read: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8, borderWidth: 1.5, borderColor: C.yellow, borderRadius: 14, height: 48, marginTop: 12 },
  readText: { fontFamily: F.bodyBold, fontSize: 15.5, color: C.yellow },
  p: { fontSize: 15, lineHeight: 22, color: C.ink, marginBottom: 6 },
}));
