// "See all" page for a Home row (picture 129 A, Oct 24, 2026, Loudjier: "Best for app drivers should show a lot of
// cars for app drivers. Best on gas should show all cars good on gas and hybrids"). Every car in the row, big cards,
// filters that fit the row, and a sort. Our picks, not ads.
import { router, useLocalSearchParams } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { FlatList, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { CompareBar } from '@/components/big-card';
import { VCard } from '@/components/v-card';
import { sheet, SkyHeader } from '@/components/sky';
import { Chip } from '@/components/ui';
import { SortButton } from '@/components/sort-button';
import { FilterBar } from '@/components/filters';
import { NO_FILTERS, passes, type Filters } from '@/data/filters';
import { savedFacts } from '@/data/gov';
import { fullRow, type Pick } from '@/data/home-rows';
import { priceFor } from '@/data/prices';
import { useAnswers } from '@/state/answers';
import { C, F, PAD, themed } from '@/theme';
import { Text } from '@/components/t';
import { usePullRefresh } from '@/components/pull-refresh';

type Filter = { label: string; test: (p: Pick) => boolean };
const SORTS = ['Our order', 'Lowest price', 'Best MPG'] as const;

const price = (p: Pick) => priceFor(p.car, p.year)?.amount ?? Infinity;
const mpg = (p: Pick) => savedFacts(p.car.id, p.year)?.mpg?.combined ?? 0;

export default function RowPage() {
  const pull = usePullRefresh();
  const { key } = useLocalSearchParams<{ key: string }>();
  const { answers } = useAnswers();
  const row = useMemo(() => fullRow(answers, key ?? ''), [answers, key]);
  const [filter, setFilter] = useState<string | null>(null);
  const [sort, setSort] = useState<(typeof SORTS)[number]>('Our order');
  const [fl, setFl] = useState<Filters>(NO_FILTERS);
  // Picture 234: the same V card as Home, two per line (one with big text).
  const { width: W, fontScale } = useWindowDimensions();
  const per = fontScale >= 1.3 ? 1 : 2;
  const cardW = Math.floor((W - PAD * 2 - 12 * (per - 1)) / per);

  // Only filters that leave some cars and drop some (no empty or useless chips).
  const filters = useMemo(() => {
    const all = row?.picks ?? [];
    // Picture 238 A: everything else moved into the Filters page; only 'Fits my plan' (it needs the coach) stays a chip.
    const list: Filter[] = [
      { label: 'Fits my plan', test: (p) => p.fits === true },
    ];
    return list.filter((f) => { const n = all.filter(f.test).length; return n > 0 && n < all.length; });
  }, [row]);

  const shown = useMemo(() => {
    const f = filters.find((x) => x.label === filter);
    const list = (row?.picks ?? []).filter((p) => (!f || f.test(p)) && passes(p.car, p.year, fl));
    if (sort === 'Lowest price') return [...list].sort((a, b) => price(a) - price(b));
    if (sort === 'Best MPG') return [...list].sort((a, b) => mpg(b) - mpg(a));
    return list;
  }, [row, filters, filter, sort, fl]);
  const countFor = useCallback((x: Filters) => (row?.picks ?? []).filter((p) => passes(p.car, p.year, x)).length, [row]);

  if (!row) {
    return (
      <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
        <SkyHeader title="See all" back={() => router.back()} />
        <View style={[sheet.page, { padding: PAD }]}><Text style={s.sub}>This list isn’t here any more. Go back to Home for today’s picks.</Text></View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title={row.title} back={() => router.back()} />
      <View style={sheet.page}>
        <FlatList refreshControl={pull}
          data={shown}
          key={`cols-${per}`}
          numColumns={per}
          columnWrapperStyle={per > 1 ? { gap: 12 } : undefined}
          keyExtractor={(p) => `${p.car.id}-${p.year}`}
          initialNumToRender={6}
          contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 110 }}
          ListHeaderComponent={
            <View style={{ marginBottom: 6 }}>
              <Text style={s.sub}>{`${row.picks.length} cars · ${row.sub}. Our picks, not ads.`}</Text>
              {filters.length > 0 && (
                <View style={s.chips}>
                  <Chip label={`All ${row.picks.length}`} on={!filter} onPress={() => setFilter(null)} />
                  {filters.map((f) => <Chip key={f.label} label={f.label} on={filter === f.label} onPress={() => setFilter(filter === f.label ? null : f.label)} />)}
                </View>
              )}
              <View style={s.sortRow}>
                <FilterBar value={fl} onChange={setFl} count={countFor} right={<SortButton options={SORTS} value={sort} onChange={setSort} />} />
              </View>
            </View>
          }
          renderItem={({ item }) => <View style={{ marginBottom: 12 }}><VCard p={item} width={cardW} /></View>}
          ListEmptyComponent={<Text style={s.sub}>No cars with that filter. Tap “All”.</Text>}
          ListFooterComponent={shown.length ? <Text style={[s.sub, { fontSize: 11.5, marginTop: 4 }]}>Used prices and payments are estimates (72 months, your credit and money down, or Good credit until you tell the coach). MPG from the EPA, recalls from NHTSA.</Text> : null}
        />
      </View>
      <CompareBar lift={70} />
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  sub: { fontFamily: F.body, fontSize: 13, lineHeight: 18, color: C.muted, marginTop: 10 },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 12 },
  sortRow: { marginTop: 12, marginBottom: 8 },
}));
