type Col = { car: Car; year: number; fit: number };

// One column of facts for one car. '' = we don't know it (no empty boxes: a row with no answers is hidden).
function columnOf(m: Col, facts: Facts | null, loading: boolean, mustHaves: string[]) {
  const p = priceFor(m.car, m.year);
  const ev = facts?.mpg?.fuel === 'EV';
  const t = TIERS[2]; // Good credit
  const monthly = p ? fiveYearCost({ price: p.amount, isNew: p.isNew, ageYears: ageOf(m.year), mpg: facts?.mpg?.combined, electric: ev,
    milesPerYear: 12000, gasPrice: 3.3, kwhPrice: 0.17, down: 2000, apr: aprOf(t, p.isNew), months: 60, taxPct: costsFor().tax }).perMonth : null;
  const wait = loading ? '…' : '';
  return [
    p ? `${money(p.amount)}${p.isNew ? '' : ' est.'}` : '',
    monthly ? `${money(round(monthly))}` : '',
    facts?.mpg ? `${facts.mpg.combined}${ev ? ' MPGe' : ''}` : wait,
    facts?.stars ? `${facts.stars}★` : loading ? '…' : facts ? 'Not rated' : '',
    facts?.recalls ? String(facts.recalls.length) : wait,
    String(m.car.seats),
    mustHaves.length ? `${mustHaves.filter((x) => featureAt(m.car, m.year, x) === 'inc').length} of ${mustHaves.length}` : '',
    m.fit >= 0 ? `${m.fit}%` : '',
  ];
}
const ROWS = ['Price', 'Cost to own / mo', 'MPG', 'Crash test', 'Recalls', 'Seats', 'Must-haves', 'Match'];
// Lower is better for price, cost and recalls; higher for the rest.
const LOW = [true, true, false, false, true, false, false, false];
const numOf = (v: string) => { const m = v.replace(/,/g, '').match(/\d+(\.\d+)?/); return m ? Number(m[0]) : null; };
/** Clean look (picture 103 A): which column wins each row. Only one clear winner; ties and unknowns get none. */
export function rowWinners(all: string[][]): (number | null)[] {
  return ROWS.map((_, r) => {
    const n = all.map((v) => numOf(v[r] ?? ''));
    if (n.some((x) => x === null)) return null;
    const best = LOW[r] ? Math.min(...(n as number[])) : Math.max(...(n as number[]));
    return n.filter((x) => x === best).length === 1 ? n.indexOf(best) : null;
  });
}

function Column({ m, vals, rows, best, wins }: { m: Col; vals: string[]; rows: number[]; best?: boolean; wins?: boolean[] }) {
  const name = carName(m.car, m.year);
  return (
    <Pressable onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: m.car.id, year: String(m.year), ...(m.fit >= 0 ? { fit: String(m.fit) } : {}) } }); }}
      accessibilityRole="button" accessibilityLabel={name} style={[s.col, best && { borderColor: C.yellow, backgroundColor: C.accentSoft }]}>
      <CarPhoto id={m.car.id} label={name} style={{ height: 64 }} />
      <H size={15} style={{ marginTop: 6, minHeight: 44 }} numberOfLines={3}>{name}</H>
      {rows.map((i) => (
        <View key={ROWS[i]} style={s.cell}>
          {/* "est." on its own small line so a price never breaks in the middle on small phones */}
          {wins?.[i] ? (
            <View style={s.win} accessibilityLabel={`${vals[i]}, best`}>
              <Text style={s.winT}>{`${vals[i].replace(/ est\.$/, '')} ✓`}</Text>
            </View>
          ) : <Body bold numberOfLines={1} style={{ fontSize: 13.5, textAlign: 'center', color: vals[i] ? C.ink : C.muted }}>{vals[i].replace(/ est\.$/, '') || 'Not known'}</Body>}
          {vals[i].endsWith(' est.') && <Body numberOfLines={1} style={{ fontSize: 10.5, textAlign: 'center', color: C.muted }}>est.</Body>}
        </View>
      ))}
    </Pressable>
  );
}

// Clean look (picture 98 A, Oct 18, 2026): one card per car with what it wins, then a short "our take".
// A win only shows when that car is best on that row and not every car ties.
type Num = { price?: number; pay?: number; own?: number; mpg?: number; stars?: number; recalls?: number; musts?: number; fit: number };
function numsOf(m: Col, facts: Facts | null, a: Answers): Num {
  const p = priceFor(m.car, m.year);
  const ev = facts?.mpg?.fuel === 'EV';
  const own = p ? fiveYearCost({ price: p.amount, isNew: p.isNew, ageYears: ageOf(m.year), mpg: facts?.mpg?.combined, electric: ev,
    milesPerYear: 12000, gasPrice: 3.3, kwhPrice: 0.17, down: 2000, apr: aprOf(TIERS[2], p.isNew), months: 60, taxPct: costsFor().tax }).perMonth : undefined;
  return {
    price: p?.amount, pay: p ? paymentFor(a, p.amount, p.isNew) : undefined, own,
    mpg: facts?.mpg?.combined, stars: facts?.stars ?? undefined, recalls: facts?.recalls?.length,
    musts: a.mustHaves.length ? a.mustHaves.filter((x) => featureAt(m.car, m.year, x) === 'inc').length : undefined, fit: m.fit,
  };
}
const WINS: { key: keyof Num; low: boolean; tag: (v: number) => string; take: (n: string, v: number) => string }[] = [
  { key: 'pay', low: true, tag: () => 'Lowest payment', take: (n) => `The ${n} costs least each month.` },
  { key: 'price', low: true, tag: () => 'Lowest price', take: (n) => `The ${n} has the lowest price.` },
  { key: 'own', low: true, tag: () => 'Cheapest to own', take: (n) => `The ${n} is cheapest to own over 5 years.` },
  { key: 'mpg', low: false, tag: () => 'Best MPG', take: (n) => `The ${n} gets the best gas mileage.` },
  { key: 'stars', low: false, tag: () => 'Safest', take: (n) => `The ${n} has the best crash test.` },
  { key: 'recalls', low: true, tag: (v) => (v === 0 ? 'No recalls' : 'Fewest recalls'), take: (n, v) => (v === 0 ? `The ${n} has no recalls.` : `The ${n} has the fewest recalls.`) },
  { key: 'musts', low: false, tag: () => 'Most must-haves', take: (n) => `The ${n} has the most of your must-haves.` },
];
function winsOf(nums: Num[]) {
  const tags: string[][] = nums.map(() => []);
  const takes: { i: number; text: (n: string) => string }[] = [];
  for (const w of WINS) {
    const vals = nums.map((n) => n[w.key]);
    if (vals.some((v) => v == null)) continue;
    const best = w.low ? Math.min(...(vals as number[])) : Math.max(...(vals as number[]));
    const who = vals.map((v, i) => (v === best ? i : -1)).filter((i) => i >= 0);
    if (who.length === nums.length) continue; // everyone ties
    who.forEach((i) => tags[i].push(w.tag(best)));
    if (who.length === 1 && !takes.some((t) => t.i === who[0])) takes.push({ i: who[0], text: (n) => w.take(n, best) });
  }
  return { tags, takes };
}
function WinCards({ top, facts, answers }: { top: Match[]; facts: (Facts | null)[]; answers: Answers }) {
  const nums = top.map((m, i) => numsOf(m, facts[i], answers));
  const { tags, takes } = winsOf(nums);
  return (
    <View style={{ marginTop: 6 }}>
      <Text style={s.lead}>Each car shows what it wins.</Text>
      {top.map((m, i) => {
        const name = carName(m.car, m.year);
        const n = nums[i];
        const line = [n.price ? `${money(n.price)}${priceFor(m.car, m.year)?.isNew ? '' : ' est.'}` : '', n.pay ? `≈ ${money(n.pay)}/mo` : '', n.mpg ? `${n.mpg} MPG` : '', n.recalls != null ? `${n.recalls} recall${n.recalls === 1 ? '' : 's'}` : ''].filter(Boolean).join(' · ');
        return (
          <Pressable key={m.car.id} onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: m.car.id, year: String(m.year), ...(m.fit >= 0 ? { fit: String(m.fit) } : {}) } }); }}
            accessibilityRole="button" accessibilityLabel={`${name}. ${tags[i].join(', ')}`} style={({ pressed }) => [s.winCard, pressed && { opacity: 0.88 }]}>
            <CarThumb id={m.car.id} label={name} width={96} height={66} />
            <View style={{ flex: 1 }}>
              <Text style={s.winName}>{name}</Text>
              <Text style={s.winLine}>{line}</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 5, marginTop: 6 }}>
                {tags[i].map((t) => <View key={t} style={s.winTag}><Text style={s.winTagText}>{`✓ ${t}`}</Text></View>)}
                {!tags[i].length && m.fit >= 0 && <Text style={s.winLine}>{`${m.fit}% match`}</Text>}
              </View>
            </View>
          </Pressable>
        );
      })}
      {takes.length > 0 && (
        <View style={s.take}>
          <Text style={s.takeTitle}>Our take</Text>
          {takes.map((t) => <Text key={t.i} style={s.takeText}>{t.text(top[t.i].car.model)}</Text>)}
        </View>
      )}
      <Text style={[s.lead, { marginTop: 18, color: C.ink, fontFamily: F.head, fontSize: 17 }]}>Every detail side by side</Text>
    </View>
  );
}

/** Cars from the link ("crv:2022,camry:2021"). Their match % comes from the coach when we have one, else none (-1). */
export function pickedCars(a: Answers, param?: string): Match[] {
  if (!param) return [];
  const known = [...topMatches(a, 3), ...moreMatches(a, 60)];
  return param.split(',').slice(0, 3).flatMap((x) => {
    const [id, y] = x.split(':');
    const car = CARS.find((c) => c.id === id);
    const year = Number(y) as Year;
    if (!car || !year) return [];
    const m = known.find((k) => k.car.id === id);
    return [{ car, year, fit: m ? m.fit : -1, used: !priceFor(car, year)?.isNew }];
  });
}

export default function Compare() {
  const { answers } = useAnswers();
  const { cars } = useLocalSearchParams<{ cars?: string }>();
  const picked = pickedCars(answers, cars);
  const top: Match[] = picked.length >= 2 ? picked : topMatches(answers, 3);
  // Cars people compare count toward Popular in your area (data/popular.ts).
  const ids = top.map((m) => m.car.id).join(',');
  useEffect(() => { ids.split(',').forEach((id) => id && countCar(id, 'compare')); }, [ids]);
  const title = picked.length >= 2 ? `Compare ${picked.length} cars` : 'Compare all 3';
  const f0 = useFacts(top[0]?.car.id, top[0]?.year);
  const f1 = useFacts(top[1]?.car.id, top[1]?.year);
  const f2 = useFacts(top[2]?.car.id, top[2]?.year);
  const all = top.map((m, i) => { const f = [f0, f1, f2][i]; return columnOf(m, f.facts, f.loading, answers.mustHaves); });
  // Only rows where at least one car has an answer.
  const rows = ROWS.map((_, i) => i).filter((i) => all.some((v) => v[i]));
  const winners = rowWinners(all);
  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title={title} back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <Label>{title}</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 30 }}>
        {calm && !skyLook ? <WinCards top={top} facts={[f0.facts, f1.facts, f2.facts]} answers={answers} /> : <H size={34} style={{ marginTop: 10 }}>Side by side</H>}
        <View style={{ flexDirection: 'row', gap: 6, marginTop: 12 }}>
          <View style={{ width: 84 }}>
            <View style={{ height: 64 + 6 + 44 }} />
            {rows.map((i) => <View key={ROWS[i]} style={s.cell}><Label style={{ fontSize: 10, letterSpacing: 0.6 }}>{ROWS[i]}</Label></View>)}
          </View>
          {top.map((m, i) => <Column key={m.car.id} m={m} vals={all[i]} rows={rows} best={picked.length < 2 && i === 0} wins={calm && !skyLook ? winners.map((w) => w === i) : undefined} />)}
        </View>
        <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 10 }}>
          Tap a car to see it. Cost to own is a 5-year average with 12,000 miles a year and Good credit (estimate). Used prices are estimates. Crash tests and recalls are from NHTSA; MPG from the EPA.
        </Body>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

