// Saved (Design 5 tab bar, picture 200, Nov 6, 2026): the cars you saved with ♡, newest first, as big cards
// (your monthly estimate, Looks fair, fits your plan) with Compare. Saved searches come next (picture 195).
import { router } from 'expo-router';
import { FlatList, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigCard, CompareBar } from '@/components/big-card';
import { SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { CARS } from '@/data/cars';
import { useSaved } from '@/state/saved';
import { C, F, PAD, themed } from '@/theme';

export default function Saved() {
  const { saved } = useSaved();
  const items = [...saved].sort((a, b) => b.at - a.at)
    .map((x) => ({ ...x, car: CARS.find((c) => c.id === x.id) }))
    .filter((x): x is typeof x & { car: NonNullable<typeof x.car> } => !!x.car);
  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Saved" />
      <FlatList
        data={items}
        keyExtractor={(x) => `${x.id}-${x.year}`}
        contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 110, gap: 12 }}
        ListHeaderComponent={items.length ? <Text style={s.count}>{items.length === 1 ? '1 car' : `${items.length} cars`} · newest first</Text> : null}
        renderItem={({ item }) => <BigCard car={item.car} year={item.year} />}
        ListEmptyComponent={
          <View style={s.empty}>
            <Text style={s.emptyT}>Nothing saved yet</Text>
            <Text style={s.emptyS}>Tap ♡ on any car to keep it here. We’ll tell you if its price changes.</Text>
            <Pressable onPress={() => { tap(); router.navigate('/search'); }} accessibilityRole="button" style={s.btn}>
              <Text style={s.btnT}>Find cars</Text>
            </Pressable>
          </View>
        }
      />
      <CompareBar lift={70} />
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  count: { fontFamily: F.bodyBold, fontSize: 13, color: C.muted, marginTop: 6 },
  empty: { alignItems: 'center', padding: 30, gap: 10, marginTop: 30 },
  emptyT: { fontFamily: F.bodyBold, fontSize: 20, color: C.ink },
  emptyS: { fontFamily: F.body, fontSize: 15, color: C.muted, textAlign: 'center', lineHeight: 21 },
  btn: { backgroundColor: C.yellow, borderRadius: 16, paddingHorizontal: 22, paddingVertical: 13, marginTop: 6 },
  btnT: { fontFamily: F.bodyBold, fontSize: 15, color: '#FFFFFF' },
}));
