// A bottom sheet with text boxes that never hides behind the phone keyboard (Oct 25, 2026, Loudjier:
// "the keyboard on the app is hiding the text box"). iPhone: the sheet rides up on the keyboard
// (KeyboardAvoidingView). Android and web: Android draws edge to edge and its keyboard events don't fire
// on every phone, so instead the sheet moves to the TOP of the screen while a box has focus (the keyboard
// only covers the bottom part), its content scrolls, and the box you tapped is scrolled into view.
import { useCallback, useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { AppState, Keyboard, KeyboardAvoidingView, Platform, ScrollView, StyleSheet, useWindowDimensions, View, type StyleProp, type TextInput as RNTextInput, type ViewStyle } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { InputFocus, Pressable, type BoxEvent } from '@/components/t';

const IOS = Platform.OS === 'ios';
const INNER = ['gap', 'padding', 'paddingTop', 'paddingBottom', 'paddingHorizontal', 'paddingVertical', 'paddingLeft', 'paddingRight'] as const;

export function KeyboardSheet({ onClose, backStyle, sheetStyle, children }: {
  onClose: () => void; backStyle: StyleProp<ViewStyle>; sheetStyle: StyleProp<ViewStyle>; children: ReactNode;
}) {
  const insets = useSafeAreaInsets();
  const { height } = useWindowDimensions();
  const [typing, setTyping] = useState(false);
  const scroll = useRef<ScrollView>(null);
  const content = useRef<View>(null);
  const off = useRef<ReturnType<typeof setTimeout> | null>(null);
  const boxes = useRef(new Set<RefObject<RNTextInput | null>>()); // every text box in this sheet
  const anyFocused = () => [...boxes.current].some((b) => !!b.current?.isFocused?.());

  // Moving from one box to the next fires blur then focus: wait a moment before moving the sheet back down.
  const onFocus = useCallback((e: BoxEvent, box: RefObject<RNTextInput | null>) => {
    if (e === 'add') { boxes.current.add(box); return; }
    if (e === 'remove') { boxes.current.delete(box); return; }
    if (off.current) clearTimeout(off.current);
    // A late blur from a box that is gone (the email box when the code step opens) must not pull the
    // sheet down while the new box has focus: only go down if no box has focus a moment later.
    if (e === 'blur') { off.current = setTimeout(() => { if (!anyFocused()) setTyping(false); }, 180); return; }
    setTyping(true);
    setTimeout(() => {
      const node = box.current as unknown as View | null;
      if (node && content.current) node.measureLayout(content.current, (_x, y) => scroll.current?.scrollTo({ y: Math.max(0, y - 70), animated: true }), () => {});
    }, 120);
  }, []);
  // A box can keep focus while the keyboard goes away and comes back without a new focus event, e.g. after
  // switching to Gmail to copy a code (Oct 25, 2026: the sheet stayed behind the keyboard). So whenever the
  // keyboard opens or the app comes back, move up if one of our boxes still has focus; move down only when
  // the keyboard closes AND no box has focus.
  useEffect(() => {
    const focused = anyFocused;
    const up = () => { if (focused()) setTyping(true); };
    const subs = [
      Keyboard.addListener('keyboardDidShow', up),
      Keyboard.addListener('keyboardDidHide', () => { if (!focused()) setTyping(false); }),
      AppState.addEventListener('change', (s) => { if (s === 'active') setTimeout(up, 250); }),
    ];
    // Safety net: some phones skip focus or keyboard events, so look twice a second whether a box has focus.
    const tick = IOS ? null : setInterval(() => { const f = focused(); setTyping((t) => (t === f ? t : f)); }, 500);
    return () => { subs.forEach((x) => x.remove()); if (off.current) clearTimeout(off.current); if (tick) clearInterval(tick); };
  }, []);

  const flat = StyleSheet.flatten(sheetStyle) ?? {};
  const inner: ViewStyle = {}; const outer: ViewStyle = { ...flat };
  for (const k of INNER) if (flat[k] !== undefined) { (inner as Record<string, unknown>)[k] = flat[k]; delete (outer as Record<string, unknown>)[k]; }
  const top = typing && !IOS;
  const r = Number(flat.borderTopLeftRadius ?? 22);

  return (
    <InputFocus.Provider value={onFocus}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={IOS ? 'padding' : undefined}>
        <Pressable style={[backStyle, top && StyleSheet.absoluteFill]} onPress={onClose} accessibilityLabel="Close" />
        <View style={[outer, top && { position: 'absolute', left: 8, right: 8, top: insets.top + 8, borderRadius: r, borderWidth: 1, maxHeight: Math.max(260, height * 0.5 - insets.top) },
          !top && { maxHeight: height - insets.top - 16 }]} accessibilityViewIsModal>
          <ScrollView ref={scroll} keyboardShouldPersistTaps="handled" bounces={false} showsVerticalScrollIndicator={top}>
            <View ref={content} style={inner}>{children}</View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>
    </InputFocus.Provider>
  );
}
