// Live now (Nov 19, 2026, picture 276 part 4): while a signed-in member has the app open,
// tell the server "I'm here" every 2 minutes. Only the HQ owner sees it (hq.live_now()).
// Guests are never counted. Privacy: 'Sign-in times' line in data/legal.ts.
import { useEffect } from 'react';
import { AppState, Platform } from 'react-native';
import { supabase } from '@/lib/supabase';

export function deviceKind(os = Platform.OS, width = 0) {
  if (os === 'android') return 'android';
  if (os === 'ios') return 'iphone';
  if (os === 'web') return width && width < 760 ? 'web-phone' : 'web-computer';
  return 'other';
}

async function ping() {
  try {
    const { data } = await supabase.auth.getSession();
    if (!data.session) return;
    const w = Platform.OS === 'web' && typeof window !== 'undefined' ? window.innerWidth : 0;
    await supabase.rpc('presence_ping', { p_kind: 'app', p_device: deviceKind(Platform.OS, w) });
  } catch { /* never bother the user about this */ }
}

export function Presence() {
  useEffect(() => {
    let active = AppState.currentState === 'active';
    if (active) ping();
    const t = setInterval(() => { if (active) ping(); }, 120000);
    const s = AppState.addEventListener('change', (st) => { active = st === 'active'; if (active) ping(); });
    const a = supabase.auth.onAuthStateChange((ev) => { if (ev === 'SIGNED_IN') ping(); });
    return () => { clearInterval(t); s.remove(); a.data.subscription.unsubscribe(); };
  }, []);
  return null;
}
