// Cars the coach can suggest, for every budget.
// Budget bands and features are EXAMPLE estimates so matching works. Real prices,
// features and listings will load from licensed data providers later. Never show
// these as facts. Safety stars, MPG and recalls are real (see gov.ts).
import { LATEST_MODEL_YEAR } from '@/data/year';

export type FeatureStatus = 'inc' | 'trim' | 'plan' | 'check';
export type Goal = 'Family' | 'Save money' | 'Side hustle' | 'Drive for apps' | 'Adventure' | 'Just browsing' | 'Upgrade my car' | 'Luxury';
export type Year = number;

// Budget bands, cheapest first. A car's band for a year comes from its price (see prices.ts).
export const BUDGETS = ['Under $15K', '$15K – $25K', '$25K – $40K', '$40K – $60K', '$60K – $100K', '$100K +'];

export type Car = {
  id: string;
  make: string;
  model: string;
  body: string; // SUV, Sedan, Truck, Minivan…
  green?: 'hybrid' | 'ev'; // has a hybrid or is electric
  tag: string;
  why: string;
  seats: number;
  goals: Goal[];
  features: Record<string, FeatureStatus>;
  from: number; // first model year we show (2015 or later)
  to?: number; // last model year, if it stopped (default 2026)
  skip?: number[]; // years the model was not sold
  popular?: boolean; // a best-seller
  likeTrax?: number; // how close it is to a Chevy Trax, for the upgrade example
};

export const MUST_HAVES = ['Apple CarPlay', 'Android Auto', 'Heated seats', 'Remote start', '4x4 / AWD', 'Towing', 'Third row', 'Adaptive cruise'];

type F = Partial<Record<string, FeatureStatus>>;
const basic: F = { 'Apple CarPlay': 'inc', 'Android Auto': 'inc', 'Heated seats': 'trim', 'Adaptive cruise': 'trim' };
const lux: F = { 'Apple CarPlay': 'inc', 'Android Auto': 'inc', 'Heated seats': 'inc', 'Remote start': 'inc', '4x4 / AWD': 'inc', 'Adaptive cruise': 'inc' };
const f = (...o: F[]) => Object.assign({}, ...o) as Record<string, FeatureStatus>;

// Oldest model year we show (Oct 14, 2026: added 2015–2019 so small budgets get more choices).
export const OLDEST_YEAR = 2015;

// Many 2015–2019 cars don't have these, or only on some trims. For those years we don't say
// "included": the app says "check this year" instead, so we never promise what a car lacks.
const NEWER_TECH = ['Apple CarPlay', 'Android Auto', 'Adaptive cruise', 'Remote start'];
export function featureAt(car: Car, year: number, m: string): FeatureStatus | undefined {
  const st = car.features[m];
  if (year < 2020 && NEWER_TECH.includes(m) && st && st !== 'check') return 'check';
  return st;
}

// Model years we show for a car, newest first.
export const yearsOf = (c: Car) => {
  const out: number[] = [];
  for (let y = c.to ?? LATEST_MODEL_YEAR; y >= c.from; y--) if (!c.skip?.includes(y)) out.push(y);
  return out;
};

// Kinds of car for the photo tiles (picture 68 B) and the coach (picture 69).
export type Kind = 'SUV' | 'Sedan' | 'Truck' | 'Minivan' | 'Hatchback' | 'Sports' | 'Electric' | 'Hybrid';
export function carIsKind(car: Car, k: Kind) {
  if (k === 'Electric') return car.green === 'ev';
  if (k === 'Hybrid') return car.green === 'hybrid';
  if (k === 'SUV') return car.body === 'SUV' || car.body === 'Wagon';
  if (k === 'Sports') return car.body === 'Sports car';
  return car.body === k;
}
export const carName = (c: Car, year?: number) => `${year ?? ''} ${c.make} ${c.model}`.trim();

