// The car someone typed as their own ("Chevrolet Trax", "toyota corolla") → our car, if we have it (Oct 19, 2026).
const MAKE_ALIAS: Record<string, string> = { chevrolet: 'chevy', vw: 'volkswagen', mercedes: 'mercedesbenz', benz: 'mercedesbenz', landrover: 'landrover' };
const squash = (x: string) => x.toLowerCase().replace(/[^a-z0-9]/g, '');
export function carForMine(make: string, model: string): Car | undefined {
  const mk = squash(make), m = squash(model);
  const want = MAKE_ALIAS[mk] ?? mk;
  const same = CARS.filter((c) => squash(c.make) === want);
  return same.find((c) => squash(c.model) === m) ?? same.find((c) => m.startsWith(squash(c.model)) || squash(c.model).startsWith(m));
}
