// Owner reviews, stored in Supabase (table "reviews"; rules in supabase/migrations/001_reviews.sql).
// Anyone can read. Members write one review per car, vote "helpful" once, and can report a review.
// A review is hidden by itself after 3 reports. The name shown always comes from the member's
// account (set by the database), and web links are not allowed.
import { supabase } from '@/lib/supabase';

export type Review = {
  id: number; car_id: string; user_id: string; display_name: string; stars: number;
  owned_year: number | null; tags: string[]; body: string; helpful: number; created_at: string;
};
export type Sort = 'helpful' | 'newest' | 'lowest';
export const REVIEW_TAGS = ['Good on gas', 'Comfy', 'Roomy', 'Reliable', 'Fun to drive', 'Great tech', 'Loud inside', 'Costly repairs'];

export async function getReviews(carId: string, sort: Sort): Promise<Review[]> {
  let q = supabase.from('reviews').select('id,car_id,user_id,display_name,stars,owned_year,tags,body,helpful,created_at').eq('car_id', carId).eq('hidden', false).limit(50);
  q = sort === 'helpful' ? q.order('helpful', { ascending: false }).order('created_at', { ascending: false })
    : sort === 'newest' ? q.order('created_at', { ascending: false }) : q.order('stars', { ascending: true }).order('created_at', { ascending: false });
  const { data, error } = await q;
  if (error) throw error;
  return (data ?? []) as Review[];
}

export async function postReview(r: { car_id: string; display_name: string; stars: number; owned_year: number | null; tags: string[]; body: string }): Promise<string | null> {
  if (/(https?:\/\/|www\.|\.com\/|\.net\/)/i.test(r.body)) return 'Please leave out web links. Reviews are for your own words.';
  const { error } = await supabase.from('reviews').insert(r);
  if (!error) return null;
  if (error.code === '23505') return 'You already reviewed this car. Thank you!';
  if (error.code === '23514') return 'Write at least 10 letters in your review.';
  return 'Couldn’t post your review. Check your internet and try again.';
}

export async function voteHelpful(id: number): Promise<boolean> {
  const { error } = await supabase.from('review_votes').insert({ review_id: id });
  return !error; // a second vote by the same member is ignored
}

export async function reportReview(id: number, reason = 'not helpful'): Promise<void> {
  await supabase.from('review_reports').insert({ review_id: id, reason });
}

export async function deleteMyReview(id: number): Promise<void> {
  await supabase.from('reviews').delete().eq('id', id);
}

export function summary(list: Review[]) {
  const n = list.length;
  const avg = n ? list.reduce((s, r) => s + r.stars, 0) / n : 0;
  const by = [5, 4, 3, 2, 1].map((k) => ({ k, pct: n ? Math.round((list.filter((r) => r.stars === k).length / n) * 100) : 0 }));
  return { n, avg, by };
}

export function ago(iso: string) {
  const d = (Date.now() - new Date(iso).getTime()) / 86400000;
  if (d < 1) return 'Today';
  if (d < 2) return 'Yesterday';
  if (d < 30) return `${Math.floor(d)} days ago`;
  if (d < 365) return `${Math.floor(d / 30)} month${Math.floor(d / 30) === 1 ? '' : 's'} ago`;
  return `${Math.floor(d / 365)} year${Math.floor(d / 365) === 1 ? '' : 's'} ago`;
}
