// My car plan, Phase 1 (picture 167, Loudjier said go Oct 30, 2026): the loan the driver types in,
// payment reminders, miles we estimate between check-ins, a simple service history, and what the car is worth.
// Pure helpers so the money and date rules are easy to test. The state lives on MyCar (state/saved.tsx).
// Everything here is the driver's own numbers or our ESTIMATE: never a bank's figure.
import { monthlyPayment } from '@/data/costs';
import { estimateRange } from '@/data/check';
import { aprOf, payFor, TIERS } from '@/data/afford';
import { CARS, type Car } from '@/data/cars';
import { priceFor } from '@/data/prices';
import { lang } from '@/i18n';
import { milesUntil } from '@/data/upkeep';
import { LATEST_MODEL_YEAR } from '@/data/year';

// lender: optional name. apr: % a year. payment: $ a month. dueDay: 1–31. left: payments left.
// paid: months marked paid ('2026-10'). We never ask for an account number or login.
// kind 'lease' (Loudjier, Oct 30, 2026: "finance, lease, own"): the same monthly payment tracking, plus the miles the
// lease allows a year and the miles when it started, so we can say early if they're heading over. apr is 0 for a lease.
export type Loan = { lender?: string; apr: number; payment: number; dueDay: number; left: number; total?: number; remind?: boolean; autopay?: boolean; paid?: string[];
  kind?: 'lease'; milesPerYear?: number; startMiles?: number };
export type HowPaid = 'finance' | 'lease' | 'own';
export const howPaid = (c: { loan?: Loan; owned?: boolean }): HowPaid | null => (c.loan ? (c.loan.kind === 'lease' ? 'lease' : 'finance') : c.owned ? 'own' : null);

// Lease miles: what the lease allows in total, and where they're heading at this pace (ESTIMATES, from the miles we know).
export function leaseMiles(c: { loan?: Loan; miles?: number; milesAt?: number; daily?: number; workdays?: boolean }, now: number): { allowed: number; projected: number; over: number } | null {
  const L = c.loan;
  if (!L || L.kind !== 'lease' || !L.milesPerYear || !L.total || L.startMiles === undefined) return null;
  const m = estMiles(c, now);
  if (m === null) return null;
  const done = Math.max(1, L.total - L.left); // months into the lease
  const allowed = Math.round((L.milesPerYear * L.total) / 12);
  const projected = Math.round(L.startMiles + ((m - L.startMiles) / done) * L.total);
  const over = Math.round((projected - L.startMiles - allowed) / 100) * 100;
  return { allowed, projected, over };
}
export type Service = { what: string; at: number; miles?: number; where?: string; cost?: number; receipt?: string }; // receipt: a photo file on this phone only

// Dates in the person's language ("Nov 15" / "15 nov").
const MON = { en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'], es: ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'] };
const MONTH = { en: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'], es: ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'] };
const DAY = { en: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'], es: ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'] };
export const monthName = (m: number) => MONTH[lang][m];
export const dayName = (d: Date) => DAY[lang][d.getDay()];
export const shortDate = (d: Date) => (lang === 'es' ? `${d.getDate()} ${MON.es[d.getMonth()]}` : `${MON.en[d.getMonth()]} ${d.getDate()}`);
export const monthYear = (d: Date) => `${MON[lang][d.getMonth()]} ${d.getFullYear()}`;
export const fullDate = (d: Date) => (lang === 'es' ? `${d.getDate()} ${MON.es[d.getMonth()]} ${d.getFullYear()}` : `${MON.en[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`);

export const monthKey = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
const dayIn = (y: number, m: number, day: number) => new Date(y, m, Math.min(day, new Date(y, m + 1, 0).getDate()));

// The next payment day: this month's due day (31 → the last day of a short month) unless it's past or already paid.
export function nextDue(loan: Loan, now: Date): Date {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  for (let i = 0; i < 3; i++) {
    const d = dayIn(now.getFullYear(), now.getMonth() + i, loan.dueDay);
    if (d >= today && !loan.paid?.includes(monthKey(d))) return d;
  }
  return dayIn(now.getFullYear(), now.getMonth() + 3, loan.dueDay);
}

export const daysUntil = (d: Date, now: Date) => Math.round((d.getTime() - new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()) / 86400000);

// What's left to pay back, from the payment and rate they typed (an ESTIMATE; their statement has the real number).
export function balanceLeft(loan: Loan): number {
  if (!loan.left || !loan.payment) return 0;
  const r = loan.apr / 1200;
  const v = r ? loan.payment * (1 - Math.pow(1 + r, -loan.left)) / r : loan.payment * loan.left;
  return Math.round(v / 10) * 10;
}

// The month of the last payment, if every payment is made on time.
export function payoffDate(loan: Loan, now: Date): Date {
  const first = nextDue(loan, now);
  return dayIn(first.getFullYear(), first.getMonth() + Math.max(0, loan.left - 1), loan.dueDay);
}

// "Mark paid": the next due month counts as paid and one fewer payment is left.
export function markPaid(loan: Loan, now: Date): Loan {
  const k = monthKey(nextDue(loan, now));
  return { ...loan, left: Math.max(0, loan.left - 1), paid: [...(loan.paid ?? []).filter((x) => x !== k), k].slice(-24) };
}
export const paidThisMonth = (loan: Loan, now: Date) => !!loan.paid?.includes(monthKey(now));

// When they change the rate or the payment: how much less (or more) a month, and over the rest of the loan.
export function loanChange(before: Loan, after: Loan): { month: number; total: number } | null {
  const month = Math.round(before.payment - after.payment);
  if (!month || !after.left) return null;
  return { month, total: month * after.left };
}

// The payment a new rate would give on what's left (to help them check what the lender told them).
export const paymentAtRate = (loan: Loan, apr: number) => Math.round(monthlyPayment(balanceLeft(loan), apr, loan.left));

// ---------- Miles ----------
// Coach "Tell me more" answers → a usual day; else about 37 miles a day (≈ 13,500 a year, the U.S. average).
export const DAILY = { 'Under 20 miles': 15, '20 to 50 miles': 35, 'Over 50 miles': 65 } as Record<string, number>;
export const DEFAULT_DAILY = 37;
export const DAILY_CHOICES = [10, 20, 35, 50, 75]; // miles a day (75 = "70+")
// Most people know their drive in minutes ("20 minutes to work and back"). We turn minutes into miles at
// about 30 mph, a normal mix of city streets and highway; the monthly check fixes any drift.
export const MINUTE_CHOICES = [10, 20, 30, 45, 60, 90];
export const MPH = 30;
export const milesFromMinutes = (min: number) => Math.max(1, Math.round((min * MPH) / 60));
// Miles a day for the estimate: their pick (or the fallback), less on days they don't drive (workdays = 5 of 7).
type Driving = { daily?: number; workdays?: boolean };
export const dailyOf = (c: Driving, fallback = DEFAULT_DAILY) => (c.daily ?? fallback) * (c.workdays ? 5 / 7 : 1);

// Miles now, counting up from the last time they typed them. Null when we have nothing to count from.
export function estMiles(car: { miles?: number; milesAt?: number; daily?: number; workdays?: boolean }, now: number, fallbackDaily = DEFAULT_DAILY): number | null {
  if (!car.miles) return null;
  if (!car.milesAt) return car.miles;
  const days = Math.max(0, (now - car.milesAt) / 86400000);
  return Math.round((car.miles + days * dailyOf(car, fallbackDaily)) / 10) * 10;
}
// Only call it an estimate once it has moved away from what they typed.
export const isEstimated = (car: { miles?: number; milesAt?: number }, now: number) => !!car.miles && !!car.milesAt && now - car.milesAt > 2 * 86400000;

// The monthly "Is your mileage about …?" check: the first Saturday of next month, 9:15 AM.
export function nextMilesCheck(now: Date): Date {
  const d = new Date(now.getFullYear(), now.getMonth() + 1, 1, 9, 15);
  while (d.getDay() !== 6) d.setDate(d.getDate() + 1);
  return d;
}

// Days until the miles reach a target (for "Oil change coming up"), or null.
export function daysToMiles(car: { miles?: number; milesAt?: number; daily?: number; workdays?: boolean }, target: number, now: number): number | null {
  const m = estMiles(car, now);
  if (m === null) return null;
  return Math.max(0, Math.ceil((target - m) / dailyOf(car)));
}

// ---------- Service history ----------
export const SERVICES = ['Oil change', 'Tire rotation', 'New tires', 'Brakes', 'Battery', 'Wiper blades', 'Air filter', 'Inspection', 'Other'];
export const addService = (list: Service[] | undefined, s: Service) => [s, ...(list ?? [])].sort((a, b) => b.at - a.at).slice(0, 100);
export const spentThisYear = (list: Service[] | undefined, year: number) =>
  (list ?? []).filter((s) => new Date(s.at).getFullYear() === year).reduce((t, s) => t + (s.cost ?? 0), 0);
// The last oil change in the history moves "what's due" (lastOil on MyCar).
export const lastOilMiles = (list: Service[] | undefined) => list?.find((s) => s.what === 'Oil change' && s.miles)?.miles;

// ---------- What the car is worth ----------
// Trade-in ESTIMATE: dealers often pay about 80% of our used price range for the car's year and miles.
export function tradeRange(car: Car, year: number, miles?: number): [number, number] | null {
  const r = estimateRange(car, year, miles);
  if (!r) return null;
  const x = (n: number) => Math.round((n * 0.8) / 500) * 500;
  return [x(r[0]), x(r[1])];
}

// Upgrade ideas: the same kind of car, 2–3 years newer than theirs (or new), with their trade-in as money down.
export type Idea = { car: Car; year: number; price: number; pay: number; same: boolean };
export function upgradeIdeas(mine: Car, myYear: number, equity: number, apr?: number, plan?: number): Idea[] {
  const good = TIERS.find((t) => t.tier === 'Good')!;
  const year = Math.min(LATEST_MODEL_YEAR, Math.max(myYear + 2, 2023));
  const out: Idea[] = [];
  for (const c of CARS) {
    if (c.body !== mine.body || (c.green === 'ev') !== (mine.green === 'ev')) continue;
    if (year < c.from || (c.to && year > c.to) || c.skip?.includes(year)) continue;
    const p = priceFor(c, year);
    if (!p) continue;
    const rate = apr ?? aprOf(good, p.isNew);
    out.push({ car: c, year, price: p.amount, pay: payFor(p.amount, rate, Math.max(0, equity)), same: c.id === mine.id });
  }
  // Their own model first (the newer one), then the closest to their plan or today's payment.
  const aim = plan ?? 0;
  return out.sort((a, b) => Number(b.same) - Number(a.same) || (aim ? Math.abs(a.pay - aim) - Math.abs(b.pay - aim) : a.pay - b.pay)).slice(0, 4);
}

