const num = (t: string) => Number(t.replace(/[^\d.]/g, '')) || 0;
const pad = (n: number) => String(n).padStart(2, '0');
const mdy = (t: number) => { const d = new Date(t); return `${pad(d.getMonth() + 1)}/${pad(d.getDate())}/${d.getFullYear()}`; };
const parseDay = (t: string) => {
  const m = t.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]), 12);
  return isNaN(d.getTime()) || d.getTime() > Date.now() + 86400000 ? null : d.getTime();
};
const usd = (n: number) => `$${(Math.round(n * 100) / 100).toLocaleString('en-US', { maximumFractionDigits: 2 })}`;
const title = (e: LogEntry) => [tr(logLabel(e.kind)), e.what && e.kind !== 'gas' ? tr(e.what) : '', e.place ?? ''].filter(Boolean).join(' · ');
const line = (e: LogEntry) => [fullDate(new Date(e.at)), e.gallons ? `${e.gallons} gal` : '', e.miles ? `${e.miles.toLocaleString('en-US')} mi` : ''].filter(Boolean).join(' · ');
const GATE: [string, string] = ['Keep your car log', 'A free account saves your gas, washes, service and repairs, and brings them back on a new phone. Receipt photos stay on this phone. No spam, never sold.'];

function Field({ label, value, onChange, placeholder, numeric, flex = 1 }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; numeric?: boolean; flex?: number }) {
  return (
    <View style={{ flex }}>
      <Label style={s.fl}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={C.muted} accessibilityLabel={label}
        keyboardType={numeric ? 'decimal-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

export function Editor({ start, miles, onSave, onCancel, onDelete }: { start: LogEntry; miles: number | null; onSave: (e: LogEntry) => void; onCancel: () => void; onDelete?: () => void }) {
  const [e, setE] = useState(start);
  const [cost, setCost] = useState(start.cost ? String(start.cost) : '');
  const [when, setWhen] = useState(onDelete ? mdy(start.at) : '');
  const [mi, setMi] = useState(start.miles ? String(start.miles) : miles ? String(Math.round(miles / 10) * 10) : '');
  const [gal, setGal] = useState(start.gallons ? String(start.gallons) : '');
  const [sure, setSure] = useState(false);
  const photo = async (from: 'camera' | 'library') => {
    tap();
    const p = await pickPhoto(from);
    if (p) setE({ ...e, receipt: saveReceipt(p, e.id) });
  };
  const save = () => {
    const at = when.trim() ? parseDay(when) : Date.now();
    if (!at) return notify('Check the date', 'Use month/day/year, like 11/08/2026. Leave it empty for today.');
    if (e.kind === 'service' && !e.what?.trim()) return notify('What was done?', 'Pick one, or write it, like “New headlight”.');
    onSave({ ...e, at, cost: num(cost) ? Math.round(num(cost) * 100) / 100 : undefined, miles: num(mi) ? Math.round(num(mi)) : undefined,
      gallons: e.kind === 'gas' && num(gal) ? Math.round(num(gal) * 1000) / 1000 : undefined });
  };
  if (sure) return (
    <Card style={{ paddingVertical: 16 }}>
      <Body bold>{`${tr('Delete')} “${title(e)}”?`}</Body>
      <Body style={s.small}>It leaves your log and your totals.</Body>
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Keep it" onPress={() => { tap(); onCancel(); }} />
        <BigBtn label="Edit instead" kind="soft" onPress={() => { tap(); setSure(false); }} />
        <BigBtn label="Delete" kind="danger" onPress={() => { tap(); onDelete?.(); }} />
      </View>
    </Card>
  );
  return (
    <Card style={{ paddingVertical: 14 }}>
      <Body bold>{onDelete ? 'Change this entry' : 'Add to your log'}</Body>
      <Label style={s.fl}>WHAT</Label>
      <View style={s.chips}>{LOG_KINDS.map((k) => <Chip key={k.kind} label={k.label} on={e.kind === k.kind} onPress={() => setE({ ...e, kind: k.kind as LogKind, what: k.kind === 'service' ? 'Oil change' : undefined })} />)}</View>
      {e.kind === 'service' && <View style={s.chips}>{SERVICES.filter((x) => x !== 'Other').map((x) => <Chip key={x} label={x} on={e.what === x} onPress={() => setE({ ...e, what: x })} />)}</View>}
      {(e.kind === 'service' || e.kind === 'repair' || e.kind === 'other') && (
        <Field label={e.kind === 'service' ? 'OR WRITE IT' : 'WHAT (OPTIONAL)'} value={e.kind === 'service' && SERVICES.includes(e.what ?? '') ? '' : e.what ?? ''}
          onChange={(t) => setE({ ...e, what: t })} placeholder={e.kind === 'repair' ? 'New brakes' : 'New headlight'} />
      )}
      <View style={s.two}>
        <Field label="COST $" value={cost} onChange={setCost} placeholder="18" numeric />
        <Field label="DATE (EMPTY = TODAY)" value={when} onChange={setWhen} placeholder="11/08/2026" flex={1.3} />
      </View>
      <View style={s.two}>
        <Field label={miles && !start.miles ? 'MILES (ESTIMATE)' : 'MILES'} value={mi} onChange={setMi} placeholder="48,340" numeric />
        {e.kind === 'gas'
          ? <Field label="GALLONS" value={gal} onChange={setGal} placeholder="11.2" numeric />
          : <Field label="WHERE (OPTIONAL)" value={e.place ?? ''} onChange={(t) => setE({ ...e, place: t || undefined })} placeholder="Express wash" flex={1.3} />}
      </View>
      {e.kind === 'gas' && <Field label="WHERE (OPTIONAL)" value={e.place ?? ''} onChange={(t) => setE({ ...e, place: t || undefined })} placeholder="QuikTrip" />}
      {e.kind === 'gas' && <Body style={s.small}>Add miles and gallons each time you fill up and we show your real MPG.</Body>}
      <Label style={s.fl}>RECEIPT (STAYS ON THIS PHONE)</Label>
      {e.receipt ? (
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
          <Image source={{ uri: e.receipt }} style={s.thumbBig} accessibilityLabel="Receipt photo" />
          <BigBtn label="Remove photo" kind="plain" onPress={() => { tap(); setE({ ...e, receipt: undefined }); }} />
        </View>
      ) : canPhoto ? (
        <View style={s.two}>
          <Pressable onPress={() => photo('camera')} accessibilityRole="button" style={s.photoBtn}><CameraIcon size={16} color={C.ink} /><Text style={s.photoT}>Take a photo</Text></Pressable>
          <Pressable onPress={() => photo('library')} accessibilityRole="button" style={s.photoBtn}><Text style={s.photoT}>Choose a photo</Text></Pressable>
        </View>
      ) : <Body style={s.small}>Photos need the newest test app.</Body>}
      <View style={{ gap: 8, marginTop: 14 }}>
        <BigBtn label="Save" onPress={save} />
        {onDelete && <BigBtn label="Delete" kind="plain" onPress={() => { tap(); setSure(true); }} />}
        <BigBtn label="Cancel" kind="plain" onPress={() => { tap(); onCancel(); }} />
      </View>
    </Card>
  );
}

/** Puts one entry back where it lives: service rows in the service history, the rest in the log. */
function store(car: MyCar, e: LogEntry, oldId?: string): MyCar {
  let log = (car.log ?? []).filter((x) => x.id !== oldId && x.id !== e.id);
  let services = (car.services ?? []).filter((x) => serviceIdOf(x) !== oldId);
  if (e.kind === 'service') {
    services = addService(services, { what: e.what!.trim(), at: e.at, miles: e.miles, where: e.place, cost: e.cost, receipt: e.receipt });
  } else log = [{ ...e, id: isService(e) ? newId() : e.id }, ...log].sort((a, b) => b.at - a.at).slice(0, 500);
  const newer = e.miles && e.miles > (car.miles ?? 0) && e.at > (car.milesAt ?? 0) - 86400000;
  const lastOil = e.kind === 'service' && e.what === 'Oil change' && e.miles && e.miles >= (car.lastOil ?? 0) ? e.miles : car.lastOil;
  return { ...car, log, services, lastOil, ...(newer ? { miles: e.miles } : {}) };
}

export default function CarLogScreen() {
  const { myCar, setMyCar } = useSaved();
  const { session, askAccount } = useAuth();
  const [now] = useState(() => Date.now());
  const [filter, setFilter] = useState<LogKind | 'all'>('all');
  const [editing, setEditing] = useState<{ e: LogEntry; isNew: boolean } | null>(null);
  const [view, setView] = useState<string | null>(null);
  const back = () => router.navigate('/garage');
  const all = myCar ? allEntries(myCar) : [];
  const list = filter === 'all' ? all : all.filter((e) => e.kind === filter);
  const t = monthTotals(all, now);
  const mpg = realMpg(all);
  const est = myCar ? estMiles(myCar, now) : null;

  const add = () => {
    tap();
    if (!session) return askAccount(...GATE);
    setEditing({ e: { id: newId(), kind: filter === 'all' ? 'gas' : filter, at: now, what: filter === 'service' ? 'Oil change' : undefined }, isNew: true });
  };
  const save = (e: LogEntry) => {
    if (!myCar) return;
    if (!session) return askAccount(...GATE);
    tap();
    setMyCar(store(myCar, e, editing?.isNew ? undefined : editing?.e.id));
    setEditing(null);
  };
  const remove = (e: LogEntry) => {
    if (!myCar) return;
    deleteReceipt(e.receipt);
    setMyCar({ ...myCar, log: (myCar.log ?? []).filter((x) => x.id !== e.id), services: (myCar.services ?? []).filter((x) => serviceIdOf(x) !== e.id) });
    setEditing(null);
  };
  const share = () => {
    if (!myCar) return;
    const rows = all.map((e) => `• ${line(e)} · ${title(e)}${e.cost ? ` · ${usd(e.cost)}` : ''}${e.receipt ? ` · ${tr('receipt')}` : ''}`);
    Share.share({ message: `${tr('Car log')} · ${carName(myCar)}\n${rows.join('\n')}\n\n${tr('From the Carvessa app. Typed in by the owner.')}` }).catch(() => {});
  };
  const shown = filter === 'all' ? LOG_KINDS.filter((k) => all.some((e) => e.kind === k.kind)) : LOG_KINDS;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Car log" sub={myCar ? carName(myCar) : undefined} back={back} />
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }} keyboardShouldPersistTaps="handled">
          {!myCar ? (
            <Card style={{ paddingVertical: 16 }}>
              <Body bold>Add your car first</Body>
              <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
            </Card>
          ) : editing ? (
            <Editor start={editing.e} miles={est} onSave={save} onCancel={() => setEditing(null)} onDelete={editing.isNew ? undefined : () => remove(editing.e)} />
          ) : (<>
            {all.length > 0 && (
              <View style={s.chipRow}>
                <Chip label="All" on={filter === 'all'} onPress={() => setFilter('all')} />
                {shown.map((k) => <Chip key={k.kind} label={k.label} on={filter === k.kind} onPress={() => setFilter(k.kind)} />)}
              </View>
            )}
            {t.total > 0 && (
              <View style={s.tots}>
                <View style={s.tot}><Text style={s.totB}>{usd(t.total)}</Text><Text style={s.totS}>this month</Text></View>
                <View style={s.tot}><Text style={s.totB}>{usd(t.gas)}</Text><Text style={s.totS}>{t.fills === 1 ? 'gas · 1 fill' : `gas · ${t.fills} fills`}</Text></View>
                <View style={s.tot}><Text style={s.totB}>{usd(t.rest)}</Text><Text style={s.totS}>everything else</Text></View>
              </View>
            )}
            {mpg && <Body style={[s.small, { marginTop: 8 }]}>{`Your real MPG: about ${mpg}, from your last fill-up.`}</Body>}
            {list.length ? (
              <Card style={{ marginTop: 12 }}>
                {list.map((e, i) => (
                  <Pressable key={e.id} onPress={() => { tap(); setEditing({ e, isNew: false }); }} accessibilityRole="button" accessibilityLabel={`${title(e)}, ${line(e)}${e.cost ? `, ${usd(e.cost)}` : ''}`}
                    style={[s.row, i < list.length - 1 && s.line]}>
                    <View style={s.ic}>{e.kind === 'gas' ? <GasIcon size={18} color={C.onAccent} /> : <WrenchIcon size={18} color={C.onAccent} />}</View>
                    <View style={{ flex: 1 }}>
                      <Text style={s.what} numberOfLines={1}>{title(e)}</Text>
                      <Text style={s.sub}>{line(e)}</Text>
                    </View>
                    {e.receipt ? <Pressable onPress={() => { tap(); setView(e.receipt!); }} accessibilityRole="button" accessibilityLabel="See receipt"><Image source={{ uri: e.receipt }} style={s.thumb} /></Pressable> : null}
                    {e.cost ? <Text style={s.cost}>{usd(e.cost)}</Text> : null}
                  </Pressable>
                ))}
              </Card>
            ) : (
              <Card style={{ marginTop: 12, paddingVertical: 14 }}>
                <Body bold>{all.length ? 'Nothing here yet' : 'Nothing logged yet'}</Body>
                <Body style={s.small}>Add gas, car washes, service and repairs. Snap the receipt so it’s never lost. Buyers like a car with records.</Body>
              </Card>
            )}
            <View style={{ marginTop: 12 }}><BigBtn label="+ Add to log" kind={all.length ? 'soft' : 'solid'} onPress={add} /></View>
            {all.length > 0 && <View style={{ marginTop: 8 }}><BigBtn label="Share my car log" kind="plain" onPress={share} /></View>}
            <Body style={[s.small, { marginTop: 12 }]}>Totals are only what you typed. Receipt photos stay on this phone.</Body>
          </>)}
        </ScrollView>
      </KeyboardAvoidingView>
      <Modal visible={!!view} transparent animationType="fade" onRequestClose={() => setView(null)}>
        <Pressable onPress={() => setView(null)} style={s.full} accessibilityRole="button" accessibilityLabel="Close receipt">
          {view ? <Image source={{ uri: view }} style={{ width: '92%', height: '80%' }} resizeMode="contain" /> : null}
          <Text style={s.close}>Tap to close</Text>
        </Pressable>
      </Modal>
    </SafeAreaView>
  );
}

