// Forgot password (picture 115 A, Loudjier Oct 19, 2026): email → 6-digit code by email → new password → logged in.
// Shown inside the Log in sheet. Never says whether an email has an account.
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';

import { notify } from '@/components/notify';
import { Pressable, Text, TextInput } from '@/components/t';
import { Body, Btn, H, tap } from '@/components/ui';
import { useAuth } from '@/state/auth';
import { C, F, themed } from '@/theme';

const LEN = 6;

export function ResetPassword({ startEmail, onDone, onBack }: { startEmail: string; onDone: () => void; onBack: () => void }) {
  const { sendResetCode, checkResetCode, changePassword } = useAuth();
  const [step, setStep] = useState<'email' | 'code' | 'password'>('email');
  const [email, setEmail] = useState(startEmail);
  const [code, setCode] = useState('');
  const [pw, setPw] = useState('');
  const [pw2, setPw2] = useState('');
  const [show, setShow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [wait, setWait] = useState(0); // seconds until "Send again" works
  const codeBox = useRef<React.ComponentRef<typeof TextInput>>(null);
  // Tapping the boxes always re-focuses (blur, then focus), so the sheet moves above the keyboard again even
  // if the box kept focus while the person was away copying the code.
  const refocus = () => { const b = codeBox.current; if (!b) return; if (b.isFocused()) { b.blur(); setTimeout(() => b.focus(), 60); } else b.focus(); };

  useEffect(() => {
    if (!wait) return;
    const t = setTimeout(() => setWait((w) => w - 1), 1000);
    return () => clearTimeout(t);
  }, [wait]);

  const send = async () => {
    setError(null);
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) return setError('Type your email.');
    setBusy(true);
    const err = await sendResetCode(email);
    setBusy(false);
    if (err) return setError(err);
    setCode('');
    setWait(60);
    setStep('code');
    setTimeout(() => codeBox.current?.focus(), 200);
  };
  const check = async () => {
    setError(null);
    if (code.length !== LEN) return setError('Type the 6 numbers from the email.');
    setBusy(true);
    const err = await checkResetCode(email, code);
    setBusy(false);
    if (err) return setError(err);
    setStep('password');
  };
  const save = async () => {
    setError(null);
    if (pw.length < 8) return setError('Use a password with at least 8 characters.');
    if (pw !== pw2) return setError('The two passwords don’t match.');
    setBusy(true);
    const err = await changePassword(pw);
    setBusy(false);
    if (err) return setError(err);
    notify('Password changed', 'You’re logged in. Your car, saved cars and alerts are all here.');
    onDone();
  };

  return (
    <View style={{ gap: 10 }}>
      {step === 'email' && (<>
        <H size={28}>Forgot your password?</H>
        <Body style={{ color: C.muted, fontSize: 14 }}>No problem. We’ll email you a 6-digit code.</Body>
        <TextInput value={email} onChangeText={setEmail} placeholder="Email" placeholderTextColor={C.muted} style={s.input} autoFocus={!startEmail}
          autoCapitalize="none" autoComplete="email" keyboardType="email-address" textContentType="emailAddress" accessibilityLabel="Email" onSubmitEditing={send} returnKeyType="send" />
        {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
        {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Send me a code" onPress={send} />}
        <Text style={s.small}>If there’s an account with this email, the code arrives in a minute. Check spam too.</Text>
      </>)}

      {step === 'code' && (<>
        <H size={28}>Check your email</H>
        <Body style={{ color: C.muted, fontSize: 14 }}>{`We sent a 6-digit code to ${email.trim()}.`}</Body>
        {/* Six boxes; one hidden box underneath takes the typing (and the phone's "fill code" suggestion). */}
        <Pressable onPress={refocus} accessibilityRole="none" style={s.boxes}>
          {Array.from({ length: LEN }, (_, i) => (
            <View key={i} style={[s.box, (i < code.length || i === code.length) && { borderColor: C.yellow }]}>
              <Text style={s.digit}>{code[i] ?? ''}</Text>
            </View>
          ))}
          <TextInput ref={codeBox} value={code} onChangeText={(v) => setCode(v.replace(/\D/g, '').slice(0, LEN))} keyboardType="number-pad"
            textContentType="oneTimeCode" autoComplete="one-time-code" maxLength={LEN} style={s.hidden} accessibilityLabel="6-digit code" onSubmitEditing={check} />
        </Pressable>
        <Text style={s.small}>The code works for a short time, one time only.</Text>
        {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
        {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Next" onPress={check} />}
        <View style={s.links}>
          <Pressable onPress={() => { if (!wait) { tap(); send(); } }} accessibilityRole="button" disabled={!!wait} hitSlop={8}>
            <Text style={[s.link, !!wait && { color: C.muted }]}>{wait ? `Send again in 0:${String(wait).padStart(2, '0')}` : 'Send again'}</Text>
          </Pressable>
          <Pressable onPress={() => { tap(); setStep('email'); setError(null); }} accessibilityRole="button" hitSlop={8}>
            <Text style={s.link}>Use a different email</Text>
          </Pressable>
        </View>
      </>)}

      {step === 'password' && (<>
        <H size={28}>Make a new password</H>
        <Body style={{ color: C.muted, fontSize: 14 }}>At least 8 characters.</Body>
        <View>
          <TextInput value={pw} onChangeText={setPw} secureTextEntry={!show} placeholder="New password" placeholderTextColor={C.muted} style={[s.input, { paddingRight: 70 }]}
            autoComplete="new-password" textContentType="newPassword" accessibilityLabel="New password" autoFocus />
          <Pressable onPress={() => setShow(!show)} accessibilityRole="button" style={s.show} hitSlop={8}><Text style={s.link}>{show ? 'Hide' : 'Show'}</Text></Pressable>
        </View>
        {pw.length > 0 && <Text style={[s.small, { color: pw.length >= 8 ? C.goodInk : C.muted }]}>{pw.length >= 8 ? `✓ ${pw.length} characters` : `${8 - pw.length} more to go`}</Text>}
        <TextInput value={pw2} onChangeText={setPw2} secureTextEntry={!show} placeholder="Type it again" placeholderTextColor={C.muted} style={s.input}
          autoComplete="new-password" textContentType="newPassword" accessibilityLabel="Type the new password again" onSubmitEditing={save} returnKeyType="done" />
        {pw2.length > 0 && <Text style={[s.small, { color: pw2 === pw ? C.goodInk : C.red }]}>{pw2 === pw ? '✓ They match' : 'They don’t match yet'}</Text>}
        {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
        {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Save new password" onPress={save} />}
      </>)}

      {step !== 'password' && (
        <Pressable onPress={() => { tap(); onBack(); }} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center' }}>
          <Text style={[s.link, { color: C.muted }]}>Back to log in</Text>
        </Pressable>
      )}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  input: { height: 52, borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.bg, paddingHorizontal: 14, fontFamily: F.body, fontSize: 16, color: C.ink },
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red },
  small: { fontFamily: F.body, fontSize: 12.5, color: C.muted },
  link: { fontFamily: F.bodyBold, fontSize: 14, color: C.yellow },
  links: { flexDirection: 'row', justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 },
  boxes: { flexDirection: 'row', gap: 8 },
  box: { flex: 1, height: 56, borderRadius: 12, borderWidth: 1.5, borderColor: C.line, backgroundColor: C.bg, alignItems: 'center', justifyContent: 'center' },
  digit: { fontFamily: F.bodyBold, fontSize: 24, color: C.ink },
  hidden: { position: 'absolute', left: 0, right: 0, top: 0, bottom: 0, opacity: 0.02, color: 'transparent' },
  show: { position: 'absolute', right: 14, top: 0, bottom: 0, justifyContent: 'center' },
}));
