// Scan the VIN. Look = picture 143 (Oct 25, 2026, Loudjier: "A3 + F2, build it"): A3 "Frosted" scanner
// (dark shade around the box, thin white corners, a sweeping light line, a "Looking for the VIN barcode…"
// bubble, 3 picture tips) and the F2 "Showroom" found card (dark card, gold spotlight, the car bounces up
// onto a turntable, gold "✓ VIN MATCHED"). Same reading as before (picture 51 C): the camera reads the
// VIN barcode, we check the VIN's check digit, look the car up with NHTSA, then "Use this car" fills it in
// on Check a car. The camera is only on while this screen is open, and no picture is saved or sent.
import { createAudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { router } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { AccessibilityInfo, ActivityIndicator, Animated, Easing, Keyboard, Linking, Platform, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import Svg, { Circle, Defs, Ellipse, LinearGradient, Path, RadialGradient, Rect, Stop } from 'react-native-svg';

import { Image } from 'expo-image';

import { BodyShape } from '@/components/body-shape';
import { CarCutout, ScanCutout } from '@/components/car-photo';
import { notify } from '@/components/notify';
import { CameraRow, PhotoSheet } from '@/components/scan-photo';
import { AlertIcon, CarIcon, ClockIcon, PinIcon } from '@/components/icons';
import { Btn, tap } from '@/components/ui';
import { carLine, decodeVin, vinFrom, vinFromText, type Body } from '@/data/check';
import { scanLook } from '@/data/scan-looks';
import type { Car } from '@/data/cars';
import { canReadText, canScan, readText } from '@/lib/scan';
import { lastMiles, milesWentDown, reportMiles, shortDate, type MilesReport } from '@/data/vin-miles';
import { carKey, sameCar, setCarPhoto, useCarPhoto, vinKey } from '@/state/car-photos';
import { useSaved } from '@/state/saved';
import { useAnswers } from '@/state/answers';
import { findByVin, type Listing } from '@/data/listings';
import { lastSpot } from '@/lib/location';
import { money } from '@/data/prices';
import { F } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';

// Loaded only when this phone's app has the camera built in (older test apps don't), so a plain
// import would crash those apps.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const Cam: typeof import('expo-camera') | null = canScan ? require('expo-camera') : null;
const DING = require('../../assets/sounds/ding.wav');

const GOLD = '#E0B640';
const GREEN = '#3FBF7F';
const NAVY = '#0F1A2A';
const SHADE = Platform.OS === 'ios' ? 'rgba(10,14,20,0.66)' : 'rgba(10,14,20,0.7)';
const typeIt = () => router.navigate('/check');
const close = () => (router.canGoBack() ? router.back() : typeIt());

export default function Scan() {
  return (
    <View style={{ flex: 1, backgroundColor: '#05070B' }}>
      {Cam ? <ScanCamera cam={Cam} /> : (
        <SafeAreaView style={s.center}>
          <Text style={s.title}>Scanning needs the newest app</Text>
          <Text style={s.text}>Update the Carvessa app to scan a VIN. You can still type it.</Text>
          <Btn kind="yellow" label="Type it instead" onPress={typeIt} style={{ alignSelf: 'stretch', marginTop: 18 }} />
        </SafeAreaView>
      )}
    </View>
  );
}

type Found = { vin: string; year?: number; make?: string; model?: string; body?: Body; name: string | null; car?: Car };

function ScanCamera({ cam }: { cam: typeof import('expo-camera') }) {
  const { CameraView, useCameraPermissions } = cam;
  const [perm, ask] = useCameraPermissions();
  const { prefs } = useSaved();
  const [torch, setTorch] = useState(false);
  const [found, setFound] = useState<Found | null>(null);
  const [busy, setBusy] = useState(false);
  // Some door labels (Honda) also carry a small square code that isn't the VIN. The camera reports one code
  // per look and the square wins every time, so after seeing one we read long barcodes only.
  const [longOnly, setLongOnly] = useState(false);
  const [pause, setPause] = useState(false); // a short pause makes Android restart the reader with the new list
  const still = useReduceMotion();
  // Picture 150: 'Read the letters' (the phone's text reader), help after 6 s without a read, and a zoom.
  const [mode, setMode] = useState<'code' | 'letters'>('code');
  const [round, setRound] = useState(0); // each new look (Scan again) starts its own 6-second wait
  const [stuckFor, setStuckFor] = useState('');
  const [zoomed, setZoomed] = useState(false);
  const [maybe, setMaybe] = useState<string | null>(null); // a VIN read from letters, waiting for 'Is this right?'
  const camRef = useRef<InstanceType<typeof CameraView>>(null);
  const looking = !found && !busy && !maybe;
  const tag = `${mode}:${round}`;
  const stuck = looking && stuckFor === tag;
  useEffect(() => {
    if (!looking) return;
    const t = setTimeout(() => setStuckFor(tag), 6000);
    return () => clearTimeout(t);
  }, [looking, tag]);
  useEffect(() => {
    if (mode !== 'letters' || !looking) return;
    let live = true, reading = false;
    const t = setInterval(async () => {
      if (reading || !camRef.current) return;
      reading = true;
      try {
        // A quick, small picture only for the text reader: never saved to the photos, never sent.
        const pic = await camRef.current.takePictureAsync({ quality: 0.35, skipProcessing: true, shutterSound: false });
        const vin = pic?.uri ? vinFromText(await readText(pic.uri)) : null;
        if (live && vin) { Haptics.selectionAsync().catch(() => {}); setMaybe(vin); }
      } catch { /* try again on the next look */ }
      reading = false;
    }, 1300);
    return () => { live = false; clearInterval(t); };
  }, [mode, looking]);

  const accept = async (vin: string) => {
    setBusy(true);
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
    if (prefs.sound !== false) ding();
    const car = await decodeVin(vin).catch(() => null);
    setFound(car
      ? { vin, year: car.year, make: car.make, model: car.model, body: car.body, car: car.car, name: carLine(car) }
      : { vin, name: null });
    setBusy(false);
  };

  const onCode = async ({ data, type }: { data: string; type: string }) => {
    if (found || busy || pause) return;
    const vin = vinFrom(data);
    if (!vin) {
      if (!longOnly && /qr|matrix|aztec/i.test(type)) {
        setLongOnly(true); setPause(true);
        setTimeout(() => setPause(false), 250);
      }
      return;
    }
    accept(vin);
  };
  const use = (miles?: number, price?: number) => {
    if (found) { tap(); router.navigate({ pathname: '/check', params: { vin: found.vin, at: String(Date.now()), ...(miles ? { miles: String(miles) } : {}), ...(price ? { price: String(price) } : {}) } }); }
  };
  const again = () => { tap(); setFound(null); setMaybe(null); setLongOnly(false); setRound((n) => n + 1); };

  if (!perm) return null;
  if (!perm.granted) {
    return (
      <SafeAreaView style={s.center}>
        <Text style={s.title}>Scan the VIN</Text>
        <Text style={s.text}>Carvessa uses the camera only to read the VIN barcode. No picture is saved or sent.</Text>
        {perm.canAskAgain ? (
          <Btn kind="yellow" label="Allow camera" onPress={() => { tap(); ask(); }} style={{ alignSelf: 'stretch', marginTop: 18 }} />
        ) : (
          <>
            <Text style={[s.text, { marginTop: 10 }]}>The camera is off for Carvessa. Turn it on in your phone’s settings.</Text>
            <Btn kind="yellow" label="Open settings" onPress={() => Linking.openSettings()} style={{ alignSelf: 'stretch', marginTop: 18 }} />
          </>
        )}
        <Pressable onPress={typeIt} accessibilityRole="button" style={{ padding: 14 }}><Text style={s.link}>Type it instead</Text></Pressable>
      </SafeAreaView>
    );
  }

  return (
    <View style={{ flex: 1 }}>
      <CameraView ref={camRef} style={StyleSheet.absoluteFill} facing="back" enableTorch={torch} zoom={zoomed ? 0.12 : 0}
        barcodeScannerSettings={{ barcodeTypes: longOnly ? ['code39', 'code128', 'pdf417'] : ['code39', 'code128', 'pdf417', 'datamatrix', 'qr'] }}
        onBarcodeScanned={found || busy || pause || maybe ? undefined : onCode} />
      <Viewfinder state={found ? 'found' : busy ? 'busy' : 'look'} still={still} torch={torch}
        onTorch={() => { tap(); setTorch(!torch); }} mode={mode} onMode={canReadText ? (m) => { tap(); setMode(m); } : undefined}
        stuck={stuck && !maybe} zoomed={zoomed} onZoom={() => { tap(); setZoomed(!zoomed); }} />
      {maybe && !found && !busy && (
        <View style={s.maybe} accessibilityViewIsModal>
          <Text style={s.maybeLabel}>Is this right?</Text>
          <Text style={s.maybeVin} selectable>{maybe}</Text>
          <Text style={s.maybeNote}>The VIN’s own check number matches, so it’s very likely right.</Text>
          <Pressable onPress={() => { tap(); const v = maybe; setMaybe(null); accept(v); }} accessibilityRole="button" style={s.goldBtn}><Text style={s.goldBtnText}>Use this VIN</Text></Pressable>
          <View style={s.links}>
            <Pressable onPress={() => { tap(); router.navigate({ pathname: '/check', params: { vin: maybe, at: String(Date.now()) } }); }} accessibilityRole="button" hitSlop={8}><Text style={s.goldLink}>Fix a letter</Text></Pressable>
            <Pressable onPress={() => { tap(); setMaybe(null); setRound((n) => n + 1); }} accessibilityRole="button" hitSlop={8}><Text style={s.goldLink}>Scan again</Text></Pressable>
          </View>
        </View>
      )}
      {found && <FoundCard found={found} still={still} onUse={use} onAgain={again} />}
    </View>
  );
}

function useReduceMotion() {
  const [still, setStill] = useState(false);
  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setStill).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setStill);
    return () => sub.remove();
  }, []);
  return still;
}

function ding() {
  try {
    const p = createAudioPlayer(DING);
    p.play();
    setTimeout(() => { try { p.remove(); } catch {} }, 2500);
  } catch {}
}

// The camera overlay: shade around the box, corners, the sweeping line, the status bubble and the tips.
function Viewfinder({ state, still, torch, onTorch, mode, onMode, stuck, zoomed, onZoom }: {
  state: 'look' | 'busy' | 'found'; still: boolean; torch: boolean; onTorch: () => void;
  mode: 'code' | 'letters'; onMode?: (m: 'code' | 'letters') => void; stuck: boolean; zoomed: boolean; onZoom: () => void;
}) {
  const { width, height } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const boxW = width - 44, boxH = 128, boxL = 22;
  const boxT = Math.max(insets.top + 96, height * 0.26);
  const [sweep] = useState(() => new Animated.Value(0));
  const [check] = useState(() => new Animated.Value(0));
  const [bubble] = useState(() => new Animated.Value(1));
  const [dots, setDots] = useState(3);
  const looking = state === 'look';

  useEffect(() => {
    if (!looking || still) { sweep.stopAnimation(); return; }
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(sweep, { toValue: 1, duration: 1400, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
      Animated.timing(sweep, { toValue: 0, duration: 1400, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, [looking, still, sweep]);
  useEffect(() => {
    if (!looking || still) return;
    const t = setInterval(() => setDots((d) => (d % 3) + 1), 420);
    return () => clearInterval(t);
  }, [looking, still]);
  useEffect(() => {
    if (state === 'found') {
      // The green check pops; the "VIN found" bubble shows for a moment, then floats away as the card comes up.
      if (still) { check.setValue(1); bubble.setValue(0); return; }
      check.setValue(0); bubble.setValue(1);
      Animated.spring(check, { toValue: 1, friction: 4, tension: 120, useNativeDriver: true }).start();
      Animated.sequence([Animated.delay(500), Animated.timing(bubble, { toValue: 0, duration: 350, useNativeDriver: true })]).start();
    } else { check.setValue(0); bubble.setValue(1); }
  }, [state, still, check, bubble]);

  const corner = state === 'found' ? GREEN : '#FFFFFF';
  const chipText = state === 'found' ? '✓ VIN found' : state === 'busy' ? 'Got it. Looking up the car…' : `${mode === 'letters' ? 'Reading the letters' : 'Looking for the VIN barcode'}${'.'.repeat(still ? 3 : dots)}`;
  const C4 = [
    { left: -2, top: -2, borderRightWidth: 0, borderBottomWidth: 0, borderTopLeftRadius: 16 },
    { right: -2, top: -2, borderLeftWidth: 0, borderBottomWidth: 0, borderTopRightRadius: 16 },
    { left: -2, bottom: -2, borderRightWidth: 0, borderTopWidth: 0, borderBottomLeftRadius: 16 },
    { right: -2, bottom: -2, borderLeftWidth: 0, borderTopWidth: 0, borderBottomRightRadius: 16 },
  ] as const;

  return (
    <View style={StyleSheet.absoluteFill} pointerEvents="box-none">
      {/* shade everywhere except the box */}
      <View pointerEvents="none" style={[s.shade, { left: 0, right: 0, top: 0, height: boxT }]} />
      <View pointerEvents="none" style={[s.shade, { left: 0, right: 0, top: boxT + boxH, bottom: 0 }]} />
      <View pointerEvents="none" style={[s.shade, { left: 0, width: boxL, top: boxT, height: boxH }]} />
      <View pointerEvents="none" style={[s.shade, { right: 0, width: boxL, top: boxT, height: boxH }]} />

      <View style={[s.top, { paddingTop: insets.top + 8 }]}>
        <Pressable onPress={close} accessibilityRole="button" accessibilityLabel="Close" style={s.round}><Text style={s.roundText}>✕</Text></Pressable>
        <Text style={s.label}>Scan the VIN</Text>
        <Pressable onPress={onTorch} accessibilityRole="switch" accessibilityState={{ checked: torch }} accessibilityLabel="Flashlight"
          style={[s.round, torch && { backgroundColor: GOLD }]}><TorchIcon on={torch} /></Pressable>
      </View>

      {onMode && state !== 'found' && (
        <View style={[s.modes, { top: boxT - 50 }]} accessibilityRole="tablist">
          {([['code', '▥ Barcode'], ['letters', 'Aa Read the letters']] as const).map(([m, label]) => (
            <Pressable key={m} onPress={() => onMode(m)} accessibilityRole="tab" accessibilityState={{ selected: mode === m }} style={[s.mode, mode === m && s.modeOn]}>
              <Text style={[s.modeText, mode === m && { color: NAVY }]}>{label}</Text>
            </Pressable>
          ))}
        </View>
      )}

      <View pointerEvents="none" style={{ position: 'absolute', left: boxL, top: boxT, width: boxW, height: boxH }}>
        {C4.map((c, i) => <View key={i} style={[s.corner, c, { borderColor: corner }]} />)}
        {looking && (
          <Animated.View style={[s.line, { transform: [{ translateY: sweep.interpolate({ inputRange: [0, 1], outputRange: [12, boxH - 14] }) }] }]} />
        )}
        {state === 'busy' && <ActivityIndicator color="#FFFFFF" size="large" style={{ marginTop: boxH / 2 - 18 }} />}
        <Animated.View style={[s.check, { left: boxW / 2 - 27, top: boxH / 2 - 27, transform: [{ scale: check }] }]}>
          <Text style={s.checkText}>✓</Text>
        </Animated.View>
      </View>

      <Animated.View pointerEvents="none" accessibilityLiveRegion="polite"
        style={[s.chip, { top: boxT + boxH + 16 }, state === 'found' && { backgroundColor: '#1C6B40' }, { opacity: bubble, transform: [{ translateY: bubble.interpolate({ inputRange: [0, 1], outputRange: [-10, 0] }) }] }]}>
        <Text style={s.chipText}>{chipText}</Text>
      </Animated.View>

      {state !== 'found' && (
        <>
          {stuck && state === 'look' ? (
            <View style={[s.stuck, { top: boxT + boxH + 74 }]} accessibilityLiveRegion="polite">
              <Text style={s.stuckTitle}>Having trouble?</Text>
              <Text style={s.stuckText}>{mode === 'letters' ? 'Hold steady with the VIN letters in the box, and no glare.' : 'Screens and shiny labels are hard. Tilt a little to stop the glare, or move closer.'}</Text>
              <View style={{ flexDirection: 'row', gap: 8, marginTop: 10 }}>
                <Pressable onPress={onZoom} accessibilityRole="button" style={s.stuckBtn}><Text style={s.stuckBtnText}>{zoomed ? 'Zoom out' : 'Zoom in'}</Text></Pressable>
                {onMode && mode === 'code' && (
                  <Pressable onPress={() => onMode('letters')} accessibilityRole="button" style={[s.stuckBtn, s.stuckGold]}><Text style={[s.stuckBtnText, { color: NAVY }]}>Aa Read the letters</Text></Pressable>
                )}
              </View>
            </View>
          ) : (
          <View pointerEvents="none" style={[s.tips, { top: boxT + boxH + 74 }]}>
            <Tip on label="Door frame"><DoorPic /></Tip>
            <Tip label="Windshield"><WindPic /></Tip>
            <Tip label="Insurance card"><CardPic /></Tip>
          </View>
          )}
          <Pressable onPress={typeIt} accessibilityRole="button" style={[s.typeBtn, { bottom: insets.bottom + 16 }]}><Text style={s.link}>Type it instead</Text></Pressable>
        </>
      )}
    </View>
  );
}

function Tip({ on, label, children }: { on?: boolean; label: string; children: React.ReactNode }) {
  return (
    <View style={[s.tip, on && { borderColor: GOLD, backgroundColor: 'rgba(224,182,64,0.18)' }]}>
      {children}
      <Text style={s.tipText}>{label}</Text>
    </View>
  );
}

// The found card (F2 Showroom): dark card, gold spotlight, the car bounces up onto a turntable.
function FoundCard({ found, still, onUse, onAgain }: { found: Found; still: boolean; onUse: (miles?: number, price?: number) => void; onAgain: () => void }) {
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const [up] = useState(() => new Animated.Value(still ? 1 : 0));
  const [carY] = useState(() => new Animated.Value(still ? 0 : 180));
  const [carS] = useState(() => new Animated.Value(1));
  const [glow] = useState(() => new Animated.Value(still ? 1 : 0));
  // Your own photo of this car (picture 145): kept on the phone by VIN; can also become your car's photo in My Garage.
  const own = useCarPhoto(vinKey(found.vin));
  const { myCars, setCarMiles } = useSaved();
  const mineAt = found.year && found.make && found.model ? myCars.findIndex((c) => sameCar(c, { year: found.year!, make: found.make!, model: found.model! })) : -1;
  const mine = mineAt >= 0 ? myCars[mineAt] : undefined;
  // Miles (picture 146): the VIN can't tell them. Optional; your own car's miles come from My Garage, and changing them here updates it.
  const [miles, setMiles] = useState(mine?.miles ? String(mine.miles) : '');
  const [typing, setTyping] = useState(false);
  const milesN = Number(miles) || undefined;
  const saveMiles = () => { if (mine && milesN) setCarMiles(mineAt, milesN); };
  // Last mileage reported (picture 150 · 3): the last miles others typed for this VIN, and ours shared with no name.
  const [report, setReport] = useState<MilesReport | null>(null);
  const [share, setShare] = useState(true);
  useEffect(() => {
    let on = true;
    lastMiles(found.vin).then((x) => on && setReport(x)).catch(() => {});
    return () => { on = false; };
  }, [found.vin]);
  // Picture 151 · 6: is this exact car for sale online? Then show the dealer's photo (the real color) and where it is.
  // Tester-only until Auto.dev says yes; everyone else keeps our cut-out.
  const { answers } = useAnswers();
  const [forSale, setForSale] = useState<Listing | null>(null);
  useEffect(() => {
    const spot = lastSpot();
    const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
    if (!spot && !zip) return;
    let on = true;
    findByVin(found.vin, spot ? { lat: spot.lat, lon: spot.lon } : { zip }).then((r) => {
      if (on && r.kind === 'car') setForSale(r.car);
    }).catch(() => {});
    return () => { on = false; };
  }, [found.vin]); // eslint-disable-line react-hooks/exhaustive-deps
  const wentDown = milesWentDown(milesN, report);
  const doneTyping = () => { setTyping(false); saveMiles(); };
  useEffect(() => {
    if (!typing) return;
    const sub = Keyboard.addListener('keyboardDidHide', () => setTyping(false));
    return () => sub.remove();
  }, [typing]);
  // Popular cars that aren't among our 35 get a picture-only cut-out, only for the years that look like it.
  const look = !found.car && found.year && found.make && found.model ? scanLook(found.make, found.model, found.year) : undefined;
  const [toGarage, setToGarage] = useState(true);
  const [sheet, setSheet] = useState(false);
  const keep = (uri: string) => {
    const keys = [vinKey(found.vin), ...(mine && toGarage ? [carKey(mine)] : [])];
    if (!setCarPhoto(keys, uri)) notify('That photo is too big', 'Try again a little farther away, or pick a smaller photo.');
    setSheet(false);
  };
  const flipGarage = () => {
    if (!mine || !own) return;
    tap();
    const next = !toGarage;
    setToGarage(next);
    setCarPhoto([carKey(mine)], next ? own : null);
  };

  useEffect(() => {
    if (still) return;
    const ease = (toValue: number, duration: number, e = Easing.out(Easing.cubic)) => ({ toValue, duration, easing: e, useNativeDriver: true });
    Animated.sequence([
      Animated.delay(250),
      Animated.spring(up, { toValue: 1, friction: 9, tension: 70, useNativeDriver: true }),
    ]).start();
    Animated.sequence([
      Animated.delay(450),
      Animated.parallel([Animated.timing(carY, ease(-30, 360)), Animated.timing(glow, ease(1, 500))]),
      Animated.parallel([Animated.timing(carY, ease(0, 200, Easing.in(Easing.quad))), Animated.timing(carS, ease(0.92, 200, Easing.in(Easing.quad)))]),
      Animated.parallel([Animated.timing(carY, ease(-10, 170)), Animated.timing(carS, ease(1.02, 170))]),
      Animated.parallel([Animated.timing(carY, ease(0, 160, Easing.in(Easing.quad))), Animated.timing(carS, ease(1, 160))]),
    ]).start();
  }, [still, up, carY, carS, glow]);

  const pills = [found.year && String(found.year), found.make, found.car?.body ?? found.body].filter(Boolean) as string[];
  const carW = Math.min(240, width * 0.6);
  return (
    <Animated.View style={[s.card, { paddingBottom: insets.bottom + 14, transform: [{ translateY: up.interpolate({ inputRange: [0, 1], outputRange: [520, 0] }) }] },
      typing ? { top: insets.top + 8, left: 8, right: 8, paddingTop: 18, paddingBottom: 18, borderRadius: 24 } : { bottom: 0 }]}
      accessibilityViewIsModal accessibilityLabel={`VIN matched. ${found.name ?? ''}`}>
      {!typing && <View style={[s.stage, { width: carW + 80 }]} pointerEvents="box-none">
        <Animated.View style={[StyleSheet.absoluteFill, { opacity: glow }]} pointerEvents="none">
          <Svg width="100%" height="100%" viewBox="0 0 320 170">
            <Defs>
              <RadialGradient id="spot" cx="50%" cy="55%" r="50%"><Stop offset="0" stopColor={GOLD} stopOpacity="0.55" /><Stop offset="1" stopColor={GOLD} stopOpacity="0" /></RadialGradient>
              <LinearGradient id="turn" x1="0" y1="0" x2="0" y2="1"><Stop offset="0" stopColor="#1F2E52" /><Stop offset="1" stopColor="#14213D" /></LinearGradient>
            </Defs>
            <Ellipse cx="160" cy="88" rx="160" ry="88" fill="url(#spot)" />
            <Ellipse cx="160" cy="150" rx="122" ry="15" fill="url(#turn)" stroke={GOLD} strokeOpacity="0.5" strokeWidth="1.2" />
          </Svg>
        </Animated.View>
        <Animated.View style={{ position: 'absolute', left: 40, bottom: 18, width: carW, transformOrigin: 'bottom', transform: [{ translateY: carY }, { scaleY: carS }] }}>
          {/* The picture comes up right away: your photo, else our cut-out, else a gold drawing of the body type (never another car). */}
          {own ? (
            <Pressable onPress={() => { tap(); setSheet(true); }} accessibilityRole="button" accessibilityLabel="Your photo. Retake" style={[s.frame, { height: carW * 0.55 }]}>
              <Image source={{ uri: own }} style={StyleSheet.absoluteFill} contentFit="cover" />
              <View style={s.frameTag}><Text style={s.frameTagText}>Your photo · Retake</Text></View>
            </Pressable>
          ) : forSale?.photo ? (
            <View style={[s.frame, { height: carW * 0.6 }]} accessibilityLabel={`Dealer photo of this car${forSale.color ? `, ${forSale.color}` : ''}`}>
              <Image source={{ uri: forSale.photo }} style={StyleSheet.absoluteFill} contentFit="cover" />
              {forSale.color ? <View style={s.frameTag}><Text style={s.frameTagText}>{`${forSale.color} · from the dealer`}</Text></View> : null}
            </View>
          ) : found.car ? <CarCutout id={found.car.id} year={found.year} height={carW * 0.55} label={found.name ?? undefined} />
            : look ? <ScanCutout look={look.key} height={carW * 0.55} label={found.name ?? undefined} />
            : found.body ? (
              <View style={[s.noPhoto, { height: carW * 0.55 }]} pointerEvents="none">
                <View>
                  <BodyShape body={found.body} width={carW * 0.82} />
                  <View style={s.bodyTag}><Text style={s.bodyTagText}>{found.body}</Text></View>
                </View>
              </View>
            ) : <View style={s.noPhoto} pointerEvents="none"><CarIcon size={54} color={GOLD} /></View>}
        </Animated.View>
      </View>}

      <Text style={s.matched}>✓ VIN MATCHED</Text>
      <Text style={s.name}>{found.name ?? 'VIN read'}</Text>
      {!found.name && <Text style={s.small}>We couldn’t look up this car right now. You can still check it.</Text>}
      {pills.length > 0 && (
        <View style={s.pills}>{pills.map((p) => <View key={p} style={s.pill}><Text style={s.pillText}>{p}</Text></View>)}</View>
      )}
      <Text style={s.vin} selectable>{found.vin}</Text>
      {forSale && !typing && (
        <View style={s.last}>
          <PinIcon size={18} color="#FFFFFF" />
          <View style={{ flex: 1 }}>
            <Text style={s.lastTitle}>{`For sale at ${forSale.dealer} · ${money(forSale.price)}`}</Text>
            <Text style={s.lastSub}>{[forSale.city, forSale.miles != null ? `${forSale.miles.toLocaleString('en-US')} mi` : null, 'from the dealer’s listing'].filter(Boolean).join(' · ')}</Text>
          </View>
        </View>
      )}
      {look && !own && !forSale?.photo && <Text style={s.credit} numberOfLines={1}>{`Photo: ${look.credit.artist}, ${look.credit.license} (background removed)`}</Text>}
      {wentDown && report ? (
        <View style={[s.last, s.lastWarn]} accessibilityLiveRegion="polite">
          <AlertIcon size={18} color="#FFFFFF" />
          <View style={{ flex: 1 }}>
            <Text style={s.lastTitle}>Heads up: miles went down</Text>
            <Text style={s.lastSub}>{`${report.maxMiles.toLocaleString('en-US')} mi was reported on ${shortDate(report.maxAt)}. Ask about it, and check the history report.`}</Text>
          </View>
        </View>
      ) : report && !typing ? (
        <View style={s.last}>
          <ClockIcon size={18} color="#FFFFFF" />
          <View style={{ flex: 1 }}>
            <Text style={s.lastTitle}>{`Last mileage reported: ${report.lastMiles.toLocaleString('en-US')} mi`}</Text>
            <Text style={s.lastSub}>{`${shortDate(report.lastAt)} · by a Carvessa user · not checked by us`}</Text>
          </View>
        </View>
      ) : null}
      <View style={[s.miles, typing && { borderColor: GOLD }]}>
        <Odometer />
        <View style={{ flex: 1, minWidth: 0 }}>
          <Text style={s.milesQ}>How many miles?</Text>
          <Text style={[s.milesNote, milesN ? { color: GOLD } : null]}>
            {mine?.miles && milesN === mine.miles ? 'From your car in My Garage · tap to update' : milesN ? 'Fair price check uses this' : 'Optional · for a fairer price check'}
          </Text>
        </View>
        <TextInput value={milesN ? milesN.toLocaleString('en-US') : ''} onChangeText={(t) => setMiles(t.replace(/[^\d]/g, '').slice(0, 7))}
          placeholder="0" placeholderTextColor="#5E6B80" keyboardType="number-pad" returnKeyType="done" maxLength={9}
          onFocus={() => setTyping(true)} onBlur={doneTyping} onSubmitEditing={() => Keyboard.dismiss()}
          accessibilityLabel="Miles on the car" style={s.milesIn} />
        <Text style={s.milesUnit}>mi</Text>
      </View>
      {!!milesN && (
        <Pressable onPress={() => { tap(); setShare(!share); }} accessibilityRole="checkbox" accessibilityState={{ checked: share }} style={s.chk}>
          <View style={[s.box2, share && { backgroundColor: GOLD, borderColor: GOLD }]}>{share && <Text style={s.box2Text}>✓</Text>}</View>
          <Text style={s.chkText}>Share these miles (no name) so others see the latest</Text>
        </Pressable>
      )}
      {own && mine && !typing && (
        <Pressable onPress={flipGarage} accessibilityRole="checkbox" accessibilityState={{ checked: toGarage }} style={s.chk}>
          <View style={[s.box2, toGarage && { backgroundColor: GOLD, borderColor: GOLD }]}>{toGarage && <Text style={s.box2Text}>✓</Text>}</View>
          <Text style={s.chkText}>Use this photo for my car in My Garage</Text>
        </Pressable>
      )}
      <Pressable onPress={() => { Keyboard.dismiss(); saveMiles(); if (share && milesN) reportMiles(found.vin, milesN); onUse(milesN, forSale?.price); }} accessibilityRole="button" style={s.goldBtn}><Text style={s.goldBtnText}>Use this car</Text></Pressable>
      {!typing && <>
      <CameraRow still={still} onPress={() => setSheet(true)}
        title={own ? 'Change my photo' : found.car || look ? 'Use my own photo' : 'Snap a photo of this car'}
        sub={own || !(found.car || look) ? 'Stays on your phone' : 'Optional · stays on your phone'} />
      <View style={s.links}>
        <Pressable onPress={onAgain} accessibilityRole="button" hitSlop={8}><Text style={s.goldLink}>Scan again</Text></Pressable>
        <Pressable onPress={typeIt} accessibilityRole="button" hitSlop={8}><Text style={s.goldLink}>Type it instead</Text></Pressable>
      </View>
      </>}
      {sheet && <PhotoSheet onClose={() => setSheet(false)} onPhoto={keep} />}
    </Animated.View>
  );
}

