// "Check your email" after sign-up (picture 184 A, Nov 5, 2026): the 6-digit code that proves the email is
// really theirs. Same boxes as Forgot password. Also shown when someone logs in before typing the code.
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';

import { Pressable, Text, TextInput } from '@/components/t';
import { Body, Btn, H, tap } from '@/components/ui';
import { useAuth } from '@/state/auth';
import { C, F, themed } from '@/theme';

const LEN = 6;

export function ConfirmCode({ email, fromLogin, onDone, onBack }: { email: string; fromLogin?: boolean; onDone: () => void; onBack: () => void }) {
  const { confirmCode, resendSignupCode } = useAuth();
  const [code, setCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [wait, setWait] = useState(60); // the first code was just sent
  const box = useRef<React.ComponentRef<typeof TextInput>>(null);
  const refocus = () => { const b = box.current; if (!b) return; if (b.isFocused()) { b.blur(); setTimeout(() => b.focus(), 60); } else b.focus(); };

  useEffect(() => { const t = setTimeout(() => box.current?.focus(), 250); return () => clearTimeout(t); }, []);
  useEffect(() => {
    if (!wait) return;
    const t = setTimeout(() => setWait((w) => w - 1), 1000);
    return () => clearTimeout(t);
  }, [wait]);

  const check = async (v = code) => {
    setError(null);
    if (v.length !== LEN) return setError('Type the 6 numbers from the email.');
    setBusy(true);
    const err = await confirmCode(email, v);
    setBusy(false);
    if (err) return setError(err);
    onDone();
  };
  const again = async () => {
    if (wait) return;
    tap(); setError(null);
    const err = await resendSignupCode(email);
    if (err) return setError(err);
    setCode(''); setWait(60);
  };

  return (
    <View style={{ gap: 10 }}>
      <H size={28}>Check your email</H>
      <Body style={{ color: C.muted, fontSize: 14 }}>
        {fromLogin ? `Your email isn’t confirmed yet. We just sent a new 6-digit code to ${email.trim()}.` : `We sent a 6-digit code to ${email.trim()}. It checks that this email is really yours.`}
      </Body>
      <Pressable onPress={refocus} accessibilityRole="none" style={s.boxes}>
        {Array.from({ length: LEN }, (_, i) => (
          <View key={i} style={[s.box, (i < code.length || i === code.length) && { borderColor: C.yellow }]}>
            <Text style={s.digit}>{code[i] ?? ''}</Text>
          </View>
        ))}
        <TextInput ref={box} value={code} keyboardType="number-pad" textContentType="oneTimeCode" autoComplete="one-time-code" maxLength={LEN}
          style={s.hidden} accessibilityLabel="6-digit code" onSubmitEditing={() => check()}
          onChangeText={(v) => { const c = v.replace(/\D/g, '').slice(0, LEN); setCode(c); if (c.length === LEN) check(c); }} />
      </Pressable>
      <Text style={s.small}>Not there? Check Spam or Promotions. The code works for a short time.</Text>
      {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
      {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Confirm" onPress={() => check()} />}
      <View style={s.links}>
        <Pressable onPress={again} accessibilityRole="button" disabled={!!wait} hitSlop={8}>
          <Text style={[s.link, !!wait && { color: C.muted }]}>{wait ? `Send again in 0:${String(wait).padStart(2, '0')}` : 'Send again'}</Text>
        </Pressable>
        <Pressable onPress={() => { tap(); onBack(); }} accessibilityRole="button" hitSlop={8}>
          <Text style={s.link}>Wrong email?</Text>
        </Pressable>
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red },
  small: { fontFamily: F.body, fontSize: 12.5, color: C.muted },
  link: { fontFamily: F.bodyBold, fontSize: 14, color: C.yellow },
  links: { flexDirection: 'row', justifyContent: 'space-between', flexWrap: 'wrap', gap: 10 },
  boxes: { flexDirection: 'row', gap: 8 },
  box: { flex: 1, height: 56, borderRadius: 12, borderWidth: 1.5, borderColor: C.line, backgroundColor: C.bg, alignItems: 'center', justifyContent: 'center' },
  digit: { fontFamily: F.bodyBold, fontSize: 24, color: C.ink },
  hidden: { position: 'absolute', left: 0, right: 0, top: 0, bottom: 0, opacity: 0.02, color: 'transparent' },
}));
