// "Check a car you found" (picture 45 A, picked Oct 14, 2026).
// Someone brings us a used car they found anywhere (we never copy other sites): a VIN, or the
// year, brand and model, plus the asking price and miles. We read the VIN with NHTSA vPIC (free,
// U.S. government), pull recalls, safety and gas mileage, and compare the price to OUR ESTIMATE.
import { CARS, type Car } from '@/data/cars';
import { GOV_NAMES, getFacts, recallsForMyCar, type Recall } from '@/data/gov';
import { priceFor } from '@/data/prices';
import { thisYear } from '@/data/year';

export type Found = { year: number; make: string; model: string; trim?: string; car?: Car; body?: Body; power?: Power };
// How it's powered, from the VIN (picture 151 panel 5): electric, plug-in hybrid or hybrid. Gas cars have none.
export type Power = 'electric' | 'plugin' | 'hybrid';
export function powerFrom(x: { ElectrificationLevel?: string; FuelTypePrimary?: string; FuelTypeSecondary?: string }): Power | undefined {
  const e = (x.ElectrificationLevel ?? '').toLowerCase();
  if (/^bev|battery electric/.test(e)) return 'electric';
  if (/phev|plug-in|erev|extended range/.test(e)) return 'plugin';
  if (/hev|hybrid/.test(e) && !/mild/.test(e)) return 'hybrid';
  const f = `${x.FuelTypePrimary ?? ''} ${x.FuelTypeSecondary ?? ''}`.toLowerCase();
  if (/electric/.test(f) && /gasoline/.test(f)) return 'plugin';
  if (/electric/.test(f)) return 'electric';
  return undefined;
}
export type Body = 'Sedan' | 'SUV' | 'Truck' | 'Minivan' | 'Van' | 'Hatchback' | 'Coupe' | 'Wagon' | 'Convertible';
export type Verdict = 'low' | 'fair' | 'high';
export type Report = {
  found: Found;
  asking?: number;
  miles?: number;
  range?: [number, number]; // our estimate for this car, year and miles
  verdict?: Verdict;
  recalls: Recall[] | null; // null = couldn't check
  stars?: number | null;
  mpg?: number | null;
};

const VPIC = 'https://vpic.nhtsa.dot.gov/api/vehicles';
const nice = (s: string) => s.toLowerCase().replace(/(^|[\s-])\S/g, (x) => x.toUpperCase());
const MAKE_NAMES: Record<string, string> = { chevy: 'chevrolet', vw: 'volkswagen', mercedes: 'mercedes-benz', benz: 'mercedes-benz', landrover: 'land rover' };

// 17 letters and numbers, never I, O or Q.
export const isVin = (v: string) => /^[A-HJ-NPR-Z0-9]{17}$/i.test(v.trim());

// The 9th character of every U.S. VIN is a check digit worked out from the other 16, so a
// misread barcode almost never passes this test.
const VAL: Record<string, number> = { A: 1, B: 2, C: 3, D: 4, E: 5, F: 6, G: 7, H: 8, J: 1, K: 2, L: 3, M: 4, N: 5, P: 7, R: 9, S: 2, T: 3, U: 4, V: 5, W: 6, X: 7, Y: 8, Z: 9 };
const WEIGHT = [8, 7, 6, 5, 4, 3, 2, 10, 0, 9, 8, 7, 6, 5, 4, 3, 2];
export function vinCheckOk(vin: string) {
  const v = vin.toUpperCase();
  if (!isVin(v)) return false;
  let sum = 0;
  for (let i = 0; i < 17; i++) sum += (/\d/.test(v[i]) ? Number(v[i]) : VAL[v[i]]) * WEIGHT[i];
  const want = sum % 11 === 10 ? 'X' : String(sum % 11);
  return v[8] === want;
}

// Finds the VIN in what the camera read: the door sticker barcode (sometimes with an extra "I"
// in front) or a registration card barcode with lots of other text around it.
export function vinFrom(data: string): string | null {
  const runs = data.toUpperCase().match(/[A-Z0-9]+/g) ?? [];
  for (const run of runs) {
    for (let i = 0; i + 17 <= run.length; i++) {
      const v = run.slice(i, i + 17);
      if (vinCheckOk(v)) return v;
    }
  }
  return null;
}

// A VIN read from printed letters (picture 150 · 2). VINs never use I, O or Q, so a reader's O/I/Q become 0/1/0.
// Only a whole word of 17 (or two or three words that make 17, for VINs printed with spaces) counts, and it must
// pass the check digit, so random text on a label never turns into a VIN.
export function vinFromText(lines: string[]): string | null {
  for (const line of lines.flatMap((l) => l.split(/\n/))) {
    const words = line.toUpperCase().replace(/O/g, '0').replace(/I/g, '1').replace(/Q/g, '0')
      .split(/[^A-Z0-9]+/).filter(Boolean);
    for (let i = 0; i < words.length; i++) {
      let joined = '';
      for (let k = i; k < Math.min(words.length, i + 3); k++) {
        joined += words[k];
        if (joined.length === 17 && vinCheckOk(joined)) return joined;
        if (joined.length >= 17) break;
      }
    }
  }
  return null;
}

// One of our cars, if we know it (for price estimates, safety and gas mileage).
export function matchCar(make: string, model: string): Car | undefined {
  const mk = (MAKE_NAMES[make.trim().toLowerCase()] ?? make.trim().toLowerCase()).toUpperCase();
  const md = model.trim().toUpperCase();
  return CARS.find((c) => {
    const n = GOV_NAMES[c.id];
    if (!n || n.make !== mk) return false;
    return n.recall.some((r) => md === r || md.startsWith(r + ' ') || r.startsWith(md));
  });
}

// "2022 Mazda Mazda3 Preferred" reads twice; when the model already starts with the brand, say it once.
export function carLine(c: { year: number; make: string; model: string; trim?: string }): string {
  const model = c.model.toLowerCase().startsWith(c.make.toLowerCase()) ? c.model : `${c.make} ${c.model}`;
  return `${c.year} ${model}${c.trim ? ` ${c.trim}` : ''}`;
}

// NHTSA's BodyClass ("Sedan/Saloon", "Sport Utility Vehicle (SUV)/Multi-Purpose Vehicle (MPV)", "Pickup",
// "Hatchback/Liftback/Notchback", "Crossover Utility Vehicle (CUV)"…) in plain words, for the scanner's
// picture of a car we don't have yet (picture 145).
export function bodyFrom(bodyClass?: string | null): Body | undefined {
  const b = (bodyClass ?? '').toLowerCase();
  if (!b) return undefined;
  if (b.includes('pickup')) return 'Truck';
  if (b.includes('minivan')) return 'Minivan';
  if (b.includes('sport utility') || b.includes('crossover') || b.includes('suv') || b.includes('cuv')) return 'SUV';
  if (b.includes('van')) return 'Van';
  if (b.includes('hatchback') || b.includes('liftback')) return 'Hatchback';
  if (b.includes('convertible') || b.includes('cabriolet') || b.includes('roadster')) return 'Convertible';
  if (b.includes('coupe')) return 'Coupe';
  if (b.includes('wagon')) return 'Wagon';
  if (b.includes('sedan') || b.includes('saloon')) return 'Sedan';
  return undefined;
}

export async function decodeVin(vin: string): Promise<Found | null> {
  const r = await fetch(`${VPIC}/DecodeVinValues/${encodeURIComponent(vin.trim())}?format=json`);
  const j = await r.json();
  const x = j?.Results?.[0];
  const year = Number(x?.ModelYear);
  if (!x?.Make || !x?.Model || !year) return null;
  return { year, make: nice(x.Make), model: x.Model, trim: x.Trim || undefined, car: matchCar(x.Make, x.Model), body: bodyFrom(x.BodyClass), power: powerFrom(x) };
}

// "2018 Honda CR-V EX" -> year, brand, model (trim words are fine to leave in).
export function parseTyped(s: string): Found | null {
  const m = s.trim().match(/^((?:19|20)\d\d)\s+(\S+(?:\s+rover|-benz)?)\s+(.+)$/i);
  if (!m) return null;
  const year = Number(m[1]);
  const make = m[2];
  const words = m[3].split(/\s+/);
  // Try the longest model name we know first ("CR-V EX" -> "CR-V").
  for (let k = words.length; k >= 1; k--) {
    const car = matchCar(make, words.slice(0, k).join(' '));
    if (car) return { year, make: car.make, model: car.model, trim: words.slice(k).join(' ') || undefined, car };
  }
  return { year, make: nice(MAKE_NAMES[make.toLowerCase()] ?? make), model: m[3] };
}

// Our ESTIMATE for this car, year and miles. People drive about 12,000 miles a year; each
// 10,000 miles more (or less) than that moves the price about 4%, up to 25% either way.
export function estimateRange(car: Car, year: number, miles?: number): [number, number] | undefined {
  const p = priceFor(car, year);
  if (!p) return undefined;
  const age = Math.max(1, thisYear() - year);
  let v = p.amount;
  if (miles && miles > 0) {
    const adj = Math.max(-0.25, Math.min(0.25, ((age * 12000 - miles) / 10000) * 0.04));
    v *= 1 + adj;
  }
  const r = (n: number) => Math.round(n / 500) * 500;
  // A wide range on purpose: trims, condition and where you live change used prices a lot.
  return [r(v * 0.88), r(v * 1.12)];
}

export function verdictFor(asking: number, [lo, hi]: [number, number]): Verdict {
  return asking < lo * 0.95 ? 'low' : asking > hi * 1.05 ? 'high' : 'fair';
}

export async function checkCar(found: Found, asking?: number, miles?: number): Promise<Report> {
  const range = found.car ? estimateRange(found.car, found.year, miles) : undefined;
  const report: Report = { found, asking, miles, range, verdict: asking && range ? verdictFor(asking, range) : undefined, recalls: null };
  if (found.car) {
    const f = await getFacts(found.car.id, found.year).catch(() => null);
    report.recalls = f?.recalls ?? null;
    report.stars = f?.stars;
    report.mpg = f?.mpg?.combined ?? null;
  } else {
    // A car we don't know: the government needs the plain model name, so try "Altima SV", then
    // "Altima" (trim words dropped) until NHTSA knows it.
    const words = found.model.split(/\s+/);
    for (let k = words.length; k >= 1; k--) {
      const got = await recallsForMyCar(found.make, words.slice(0, k).join(' '), found.year).catch(() => null);
      if (got === null) { report.recalls = null; break; }
      report.recalls = got;
      if (got.length || k === 1) {
        report.found = { ...found, model: words.slice(0, k).join(' '), trim: words.slice(k).join(' ') || found.trim };
        break;
      }
    }
  }
  return report;
}

export const SELLER_QUESTIONS = [
  'Were all the recalls fixed? Can I see the paperwork?',
  'Do you have the service records (oil changes, brakes, tires)?',
  'Has it been in an accident or had flood damage?',
  'Is the title clean? (Not salvage, rebuilt or flood.)',
  'Can my own mechanic look at it before I buy?',
  'Is the price before or after tax and fees?',
];
