// Picture 127 A "City sky" (Loudjier, Oct 22, 2026: "A"): a quiet animated top behind the Home greeting for
// Clean, Clean night, Sunset Calm and Sunset Calm night. A soft Atlanta skyline at the bottom; in the day looks
// clouds drift slowly (Sunset Calm adds a warm sun by the buttons); in the night looks stars twinkle and windows
// light up. Slow moves only, nothing behind the words is bright, and "Reduce motion" shows a still picture.
// Picture 133 (Oct 24, 2026): the sky shows the real weather (National Weather Service): sun, a few clouds, gray
// clouds, rain, storms (a still bolt, never flashing), snow or fog.
// Picture 135 B (Oct 24, 2026, Loudjier: "Can we make the city look more real?" → "B"): Atlanta's real skyline
// (Bank of America Plaza, One Atlantic Center, the round Westin, 191 Peachtree, Truist Plaza, Georgia-Pacific) in two
// layers, plus trees, a road with one small car driving across, and the SkyView wheel. The sun and moon sit in a
// clear spot right of the title, and clouds stay low, away from the buttons.
import { LinearGradient } from 'expo-linear-gradient';
import { useEffect, useMemo, useState } from 'react';
import { AccessibilityInfo, Animated, AppState, Easing, StyleSheet, View } from 'react-native';
import Svg, { Circle, G, Line, Path, Rect } from 'react-native-svg';

import { useSunDark, useSunPlace } from '@/components/sky';
import { getWeather, type Weather } from '@/data/weather';
import { useSaved } from '@/state/saved';

import { C, look, type ThemeName } from '@/theme';
import { useRefreshTick } from '@/lib/refresh';

type Scene = { top: string; back: string; front: string; trees: string; road: string; win: string; car: string; night: boolean; sun?: boolean };
const SCENES: Partial<Record<ThemeName, Scene>> = {
  clean: { top: '#BFDDF5', back: '#C9D6E6', front: '#A9BBD2', trees: '#8FB59B', road: '#C3CCD8', win: '#FFFFFF', car: '#1F5FBF', night: false },
  cleanNight: { top: '#060B16', back: '#26385C', front: '#1A2846', trees: '#121C30', road: '#1B2740', win: '#F2D28A', car: '#3D5A8A', night: true },
  calm: { top: '#F9C99B', back: '#D2B3B8', front: '#9A7A8C', trees: '#7E9479', road: '#C8B0B4', win: '#FFE9D2', car: '#1F6E4E', night: false, sun: true },
  calmNight: { top: '#0A1310', back: '#24392F', front: '#182B22', trees: '#0F1D16', road: '#1B2B23', win: '#F2D28A', car: '#2F6B52', night: true },
};
/** Looks that get the animated top. */
export const hasSkyTop = () => !!SCENES[look];

// The city, drawn in units: towers stand on y = GROUND, the road runs under them. Atlanta's landmarks sit in the
// middle (330 units wide, picture 135); plain towers fill the sides on wider phones.
const GROUND = 110;
const TOP_Y = 26;
const VIEW_H = 112; // tall enough for a two-lane road (Oct 26, 2026)
export const CITY_H = 54; // picture 154 B (Oct 26, 2026): shorter Home top
type Tower = { x: number; w: number; h: number; top?: 'boa' | 'oac' | 'round' | 'twin' | 'step' | 'fin' | 'pyr' };
const BACK: Tower[] = [{ x: 0, w: 22, h: 22 }, { x: 20, w: 14, h: 32, top: 'pyr' }, { x: 36, w: 18, h: 27 }, { x: 56, w: 12, h: 37, top: 'fin' }, { x: 70, w: 20, h: 24 }, { x: 182, w: 16, h: 29 }, { x: 236, w: 14, h: 42, top: 'pyr' }, { x: 252, w: 20, h: 33 }, { x: 274, w: 16, h: 45, top: 'oac' }, { x: 292, w: 22, h: 29 }, { x: 314, w: 16, h: 22 }];
const FRONT: Tower[] = [{ x: 6, w: 26, h: 16 }, { x: 34, w: 20, h: 33, top: 'step' }, { x: 58, w: 18, h: 40, top: 'round' }, { x: 80, w: 24, h: 20 }, { x: 104, w: 20, h: 45, top: 'twin' }, { x: 128, w: 22, h: 48, top: 'step' }, { x: 152, w: 12, h: 22 }, { x: 166, w: 20, h: 60, top: 'boa' }, { x: 190, w: 24, h: 26 }, { x: 218, w: 18, h: 50, top: 'oac' }, { x: 240, w: 26, h: 19 }, { x: 270, w: 16, h: 30 }, { x: 290, w: 30, h: 17 }];
const BOA = 7; // Bank of America Plaza in FRONT: its top glows gold at night, like the real one.

function towerPath({ x, w, h, top }: Tower) {
  const y = GROUND - h, r = x + w, H = GROUND, m = x + w / 2;
  switch (top) {
    case 'boa': return `M${x} ${H}V${y + 18}H${x + 2}V${y + 12}H${x + 4}V${y + 8}L${m} ${y - 6}L${r - 4} ${y + 8}V${y + 12}H${r - 2}V${y + 18}H${r}V${H}Z M${m - 0.6} ${y - 6}V${y - 20}h1.2V${y - 6}Z`;
    case 'oac': return `M${x} ${H}V${y + 10}H${x + 1.5}V${y + 6}L${m} ${y - 8}L${r - 1.5} ${y + 6}V${y + 10}H${r}V${H}Z M${m - 0.5} ${y - 8}V${y - 13}h1V${y - 8}Z`;
    case 'round': return `M${x} ${H}V${y + 3}Q${x} ${y} ${x + 3} ${y}H${r - 3}Q${r} ${y} ${r} ${y + 3}V${H}Z`;
    case 'twin': return `M${x} ${H}V${y + 8}H${x + 3}V${y + 3}Q${x + 5} ${y - 2} ${x + 7} ${y + 3}V${y + 8}H${r - 7}V${y + 3}Q${r - 5} ${y - 2} ${r - 3} ${y + 3}V${y + 8}H${r}V${H}Z`;
    case 'step': return `M${x} ${H}V${y + 10}H${x + 3}V${y + 5}H${x + 6}V${y}H${r - 6}V${y + 5}H${r - 3}V${y + 10}H${r}V${H}Z`;
    case 'fin': return `M${x} ${H}V${y + 6}H${r - 5}L${r} ${y - 6}V${H}Z`;
    case 'pyr': return `M${x} ${H}V${y + 8}H${x + 2}V${y + 5}L${m} ${y - 3}L${r - 2} ${y + 5}V${y + 8}H${r}V${H}Z`;
    default: return `M${x} ${H}V${y}H${r}V${H}Z`;
  }
}

// The same numbers every time, so the city never jumps around.
function seeded(seed: number) {
  let s = seed;
  return () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
}

/** Every tower, window and tree for a city `wide` units across. */
function buildCity(wide: number, night: boolean) {
  const x0 = Math.max(0, (wide - 330) / 2);
  const shift = (list: Tower[]) => list.map((t) => ({ ...t, x: t.x + x0 }));
  const back = shift(BACK), front = shift(FRONT);
  const rnd = seeded(11);
  for (let x = x0 - 4; x > -24; ) { const w = 14 + Math.round(rnd() * 10); x -= w + 2; back.push({ x, w, h: 20 + Math.round(rnd() * 16) }); front.push({ x: x + 4, w: w - 2, h: 12 + Math.round(rnd() * 12) }); }
  for (let x = x0 + 334; x < wide + 4; ) { const w = 14 + Math.round(rnd() * 10); back.push({ x, w, h: 20 + Math.round(rnd() * 16) }); front.push({ x: x + 4, w: w - 2, h: 12 + Math.round(rnd() * 12) }); x += w + 2; }
  const wr = seeded(7);
  const windows: { x: number; y: number }[] = [];
  for (const t of front) {
    for (let y = GROUND - t.h + 10; y < GROUND - 6; y += 5) {
      for (let x = t.x + 3; x < t.x + t.w - 3; x += 4) if (wr() < (night ? 0.22 : 0.5)) windows.push({ x, y });
    }
  }
  const trees = Array.from({ length: Math.ceil(wide / 15) + 1 }, (_, i) => ({ x: i * 15 + 4, r: 5 + (i % 3) }));
  return { back: back.map(towerPath).join(' '), front: front.map(towerPath).join(' '), windows, trees, boa: front[BOA], wheel: x0 + 150 };
}

const STARS = Array.from({ length: 22 }, (_, i) => ({ x: ((i * 53) % 100) / 100, y: ((i * 37) % 60) + 6, g: i % 3 }));

function useLoop(ms: number, enabled: boolean, from = 0) {
  const [v] = useState(() => new Animated.Value(from));
  useEffect(() => {
    if (!enabled) return;
    const a = Animated.loop(Animated.timing(v, { toValue: 1, duration: ms, easing: Easing.linear, useNativeDriver: true }));
    a.start();
    return () => a.stop();
  }, [enabled, ms, v]);
  return v;
}

/** The weather where they are (same spot as sunrise and sunset), checked about every 30 minutes. Off → null. */
export function useSkyWeather(): Weather | null {
  const { prefs } = useSaved();
  const { spot } = useSunPlace();
  const on = prefs.skyWeather !== false && hasSkyTop();
  const [w, setW] = useState<{ key: string; w: Weather } | null>(null);
  const key = `${spot.lat.toFixed(2)},${spot.lon.toFixed(2)}`;
  const tick = useRefreshTick();
  useEffect(() => {
    if (!on) return;
    let live = true;
    const load = (maxAge?: number) => getWeather(spot.lat, spot.lon, maxAge).then((x) => { if (live) setW({ key, w: x }); }).catch(() => {});
    load();
    const t = setInterval(() => load(), 15 * 60 * 1000);
    // Coming back to the app (e.g. in the morning) gets fresh weather when ours is over 10 minutes old.
    const sub = AppState.addEventListener('change', (st) => { if (st === 'active') load(10); });
    return () => { live = false; clearInterval(t); sub.remove(); };
  }, [on, key, tick]); // eslint-disable-line react-hooks/exhaustive-deps
  return on && w?.key === key ? w.w : null;
}

// Rain and snow: one layer twice the sky's height scrolls down and repeats, so it looks like it keeps falling.
const DROPS = Array.from({ length: 26 }, (_, i) => ({ x: ((i * 47) % 100) / 100, y: ((i * 29) % 100) / 100 }));
function Fall({ width, height, snow, still, night }: { width: number; height: number; snow: boolean; still: boolean; night: boolean }) {
  const v = useLoop(snow ? 7000 : 1100, !still);
  const y = v.interpolate({ inputRange: [0, 1], outputRange: [-height, 0] });
  const one = (half: number) => DROPS.map((d, i) => (
    <View key={`${half}-${i}`} style={snow
      ? [st.flake, { left: d.x * width, top: half * height + d.y * height }]
      : [st.drop, { left: d.x * width, top: half * height + d.y * height, backgroundColor: night ? 'rgba(170,200,240,0.7)' : 'rgba(80,115,160,0.55)' }]} />
  ));
  return <Animated.View style={{ position: 'absolute', left: 0, top: 0, width, height: height * 2, transform: [{ translateY: still ? -height / 2 : y }] }}>{one(0)}{one(1)}</Animated.View>;
}

/** inset: the phone's top safe area, so the sun and moon sit beside the greeting, clear of the buttons. */
export function SkyTop({ height, width, inset = 0, weather }: { height: number; width: number; inset?: number; weather?: Weather | null }) {
  const scene = SCENES[look];
  // A day look kept on after dark (Follow the day off) never draws a sun before sunrise or after sunset.
  const dark = useSunDark();
  const [still, setStill] = useState(false);
  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then(setStill).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setStill);
    return () => sub.remove();
  }, []);
  const move = !still && !!scene;
  const c1 = useLoop(38000, move && !scene?.night, 0.3);
  const c2 = useLoop(52000, move && !scene?.night, 0.7);
  const tw = useLoop(3200, move && !!scene?.night);
  const glow = useLoop(9000, move && !!scene?.sun);
  const c3 = useLoop(64000, move, 0.1);
  const s = CITY_H / VIEW_H;
  const wide = Math.round(width / s);
  const city = useMemo(() => buildCity(wide, !!scene?.night), [wide, scene?.night]);
  const drive = useLoop(20000, move, 0.35);
  const back = useLoop(26000, move, 0.75); // the car in the far lane, driving the other way
  if (!scene || !height) return null;
  const wx = weather?.sky ?? 'clear';
  const gray = wx === 'cloudy' || wx === 'rain' || wx === 'storm' || wx === 'snow';
  const clearSky = wx === 'clear' || wx === 'partly';
  const clouds = scene.night ? (wx === 'partly' || gray ? [c1, c2, c3] : []) : wx === 'clear' ? [c1, c2] : [c1, c2, c3];
  // Twinkle: three groups that brighten at different moments.
  const twinkle = (g: number) => tw.interpolate({ inputRange: [0, 0.5, 1], outputRange: g === 0 ? [0.15, 1, 0.15] : g === 1 ? [1, 0.15, 1] : [0.5, 0.9, 0.5] });
  const cloudX = (v: Animated.Value) => v.interpolate({ inputRange: [0, 1], outputRange: [-100, width + 20] });
  // Sun and moon: right of the greeting and the title, below the buttons, never behind a cloud.
  const orbTop = inset + 96;
  // Clouds float low between the towers, so they never pass behind the buttons, the words or the sun.
  const cloudTops = [height - CITY_H + 22, height - CITY_H + 36, height - CITY_H + 12];
  // Two lanes (Loudjier, Oct 26, 2026: 'have cars from both lane'): far lane drives left, near lane drives right.
  const carW = 22, carH = (22 * 16) / 34;
  const laneTop = (y: number) => height - CITY_H + (y - TOP_Y) * s - carH * 0.81; // wheels on the lane's middle
  const boaTop = GROUND - city.boa.h;
  return (
    <View pointerEvents="none" style={[StyleSheet.absoluteFill, { height, overflow: 'hidden' }]} importantForAccessibility="no-hide-descendants">
      <LinearGradient colors={[scene.top, C.bg]} style={StyleSheet.absoluteFill} />
      {gray && <View style={[StyleSheet.absoluteFill, { backgroundColor: scene.night ? 'rgba(40,52,70,0.45)' : 'rgba(120,140,165,0.32)' }]} />}
      {scene.night && clearSky && STARS.map((p, i) => (
        <Animated.View key={i} style={[st.star, { left: p.x * width, top: p.y, opacity: still ? 0.7 : twinkle(p.g) }]} />
      ))}
      {scene.night && clearSky && <View style={[st.moon, { right: 34, top: orbTop + 6, backgroundColor: scene.win, shadowColor: scene.win }]} />}
      {!scene.night && !scene.sun && clearSky && !dark && <View style={[st.sunDay, { right: 28, top: orbTop }]} />}
      {scene.sun && clearSky && !dark && (
        <Animated.View style={[st.sun, { right: 22, top: orbTop - 4, transform: [{ translateY: still ? 0 : glow.interpolate({ inputRange: [0, 0.5, 1], outputRange: [4, -2, 4] }) }] }]} />
      )}
      {clouds.map((v, i) => {
        const tint = scene.night ? 'rgba(70,84,108,0.85)' : gray ? 'rgba(236,240,245,0.92)' : 'rgba(255,255,255,0.8)';
        return (
          <Animated.View key={i} style={[st.cloud, { backgroundColor: tint, top: cloudTops[i], transform: [{ translateX: still ? width * [0.15, 0.55, 0.05][i] : cloudX(v) }, { scale: (gray ? 1.35 : 1) * [1, 0.7, 0.85][i] }] }]}>
            <View style={[st.puff, { backgroundColor: tint }]} />
          </Animated.View>
        );
      })}
      <Svg width={width} height={CITY_H} viewBox={`0 ${TOP_Y} ${wide} ${VIEW_H}`} style={st.city}>
        <G stroke={scene.back} strokeWidth={1.4} fill="none">
          <Circle cx={city.wheel} cy={GROUND - 18} r={15} />
          {[0, 30, 60, 90, 120, 150].map((a) => {
            const r = (a * Math.PI) / 180, dx = 15 * Math.cos(r), dy = 15 * Math.sin(r);
            return <Line key={a} x1={city.wheel - dx} y1={GROUND - 18 - dy} x2={city.wheel + dx} y2={GROUND - 18 + dy} />;
          })}
          <Line x1={city.wheel} y1={GROUND - 18} x2={city.wheel - 10} y2={GROUND} />
          <Line x1={city.wheel} y1={GROUND - 18} x2={city.wheel + 10} y2={GROUND} />
        </G>
        {scene.night && [0, 60, 120, 180, 240, 300].map((a) => (
          <Circle key={a} cx={city.wheel + 15 * Math.cos((a * Math.PI) / 180)} cy={GROUND - 18 + 15 * Math.sin((a * Math.PI) / 180)} r={1.4} fill="#FFB0D8" />
        ))}
        <Path d={city.back} fill={scene.back} opacity={scene.night ? 1 : 0.85} />
        <Path d={city.front} fill={scene.front} />
        {city.windows.map((w, i) => <Rect key={i} x={w.x} y={w.y} width={1.6} height={2} fill={scene.win} opacity={scene.night ? 0.9 : 0.35} />)}
        {scene.night && (
          <Path d={`M${city.boa.x + 4} ${boaTop + 8}L${city.boa.x + city.boa.w / 2} ${boaTop - 6}L${city.boa.x + city.boa.w - 4} ${boaTop + 8}Z`} fill="#E7B54A" />
        )}
        {city.trees.map((p, i) => <Circle key={i} cx={p.x} cy={GROUND + 1} r={p.r} fill={scene.trees} />)}
        <Rect x={0} y={GROUND + 4} width={wide} height={22} fill={scene.road} />
        <Line x1={0} y1={GROUND + 15} x2={wide} y2={GROUND + 15} stroke={scene.night ? '#5A6B8C' : '#FFFFFF'} strokeWidth={1.2} strokeDasharray="6 6" opacity={0.8} />
      </Svg>
      {[
        { y: GROUND + 9.5, left: true, v: back, at: 0.7, color: scene.night ? '#7A8BA8' : '#E8ECF2' },
        { y: GROUND + 20.5, left: false, v: drive, at: 0.28, color: scene.car },
      ].map((c, i) => (
        <Animated.View key={i} style={[st.car, { top: laneTop(c.y), transform: [
          { translateX: still ? width * c.at : c.v.interpolate({ inputRange: [0, 1], outputRange: c.left ? [width + 10, -carW - 10] : [-carW - 10, width + 10] }) },
          { scaleX: c.left ? -1 : 1 }] }]}>
          <Svg width={carW} height={carH} viewBox="0 0 34 16">
            {scene.night && <Path d="M26 6 L34 3 L34 11 Z" fill="#FFF3C4" opacity={0.4} />}
            <Path d="M2 13h22a2 2 0 0 0 2-2V9l-4-1-3-4H9L5 8H2v3a2 2 0 0 0 2 2z" fill={c.color} />
            <Circle cx={7} cy={13} r={2} fill="#222" />
            <Circle cx={20} cy={13} r={2} fill="#222" />
            {scene.night && <Circle cx={26} cy={9} r={1.2} fill="#FFF7D6" />}
          </Svg>
        </Animated.View>
      ))}
      {(wx === 'rain' || wx === 'storm' || wx === 'snow') && <Fall width={width} height={height} snow={wx === 'snow'} still={still} night={scene.night} />}
      {wx === 'storm' && (
        <Svg width={26} height={40} viewBox="0 0 26 40" style={{ position: 'absolute', left: width * 0.55, top: inset + 40 }}>
          <Path d="M16 0 L4 22 h8 l-4 18 L22 14 h-8 l6 -14z" fill="#FFD45A" />
        </Svg>
      )}
      {wx === 'fog' && [0, 1, 2].map((i) => (
        <View key={i} style={[st.fog, { top: height * (0.35 + i * 0.16), left: 16 + i * 24, width: width * (0.8 - i * 0.08), backgroundColor: scene.night ? 'rgba(180,190,205,0.25)' : 'rgba(255,255,255,0.6)' }]} />
      ))}
    </View>
  );
}

const st = StyleSheet.create({
  star: { position: 'absolute', width: 2, height: 2, borderRadius: 1, backgroundColor: '#FFFFFF' },
  moon: { position: 'absolute', width: 16, height: 16, borderRadius: 8, opacity: 0.85, shadowOpacity: 0.6, shadowRadius: 10, shadowOffset: { width: 0, height: 0 } },
  sun: { position: 'absolute', width: 46, height: 46, borderRadius: 23, backgroundColor: '#FFC48A', opacity: 0.9, shadowColor: '#FFB979', shadowOpacity: 0.8, shadowRadius: 16, shadowOffset: { width: 0, height: 0 } },
  cloud: { position: 'absolute', left: 0, width: 80, height: 20, borderRadius: 10, backgroundColor: 'rgba(255,255,255,0.8)' },
  puff: { position: 'absolute', left: 18, top: -10, width: 36, height: 24, borderRadius: 12, backgroundColor: 'rgba(255,255,255,0.8)' },
  sunDay: { position: 'absolute', width: 34, height: 34, borderRadius: 17, backgroundColor: '#FFD45A', opacity: 0.95, shadowColor: '#FFD45A', shadowOpacity: 0.9, shadowRadius: 18, shadowOffset: { width: 0, height: 0 } },
  drop: { position: 'absolute', width: 1.6, height: 10, borderRadius: 1, transform: [{ rotate: '12deg' }] },
  flake: { position: 'absolute', width: 4, height: 4, borderRadius: 2, backgroundColor: 'rgba(255,255,255,0.9)' },
  fog: { position: 'absolute', height: 6, borderRadius: 3 },
  city: { position: 'absolute', left: 0, bottom: 0 },
  car: { position: 'absolute', left: 0 },
});
