// Brand page (Brand B, picked Oct 10, 2026): type a brand and see every model it sells.
// The full model list is free from NHTSA. Models we don't have details for yet say so.
import { useEffect, useState } from 'react';
import { StyleSheet, View } from 'react-native';

import { BRANDS } from '@/components/car-picker';
import { Body, Label } from '@/components/ui';
import { CARS } from '@/data/cars';
import { modelsFor } from '@/data/gov';
import { C, themed } from '@/theme';
import { LATEST_MODEL_YEAR } from '@/data/year';

const ALIAS: Record<string, string> = { chevy: 'Chevrolet', vw: 'Volkswagen', mercedes: 'Mercedes-Benz', benz: 'Mercedes-Benz', 'mercedes-benz': 'Mercedes-Benz', caddy: 'Cadillac' };
export function brandOf(q: string): string | null {
  for (const w of q.toLowerCase().split(/\s+/).filter(Boolean)) {
    if (ALIAS[w]) return ALIAS[w];
    const b = BRANDS.find((x) => x.toLowerCase() === w);
    if (b) return b;
  }
  return null;
}
// Our data says "Chevy".
export const dataMake = (brand: string) => (brand === 'Chevrolet' ? 'Chevy' : brand);
const same = (a: string, b: string) => a.toLowerCase().replace(/[^a-z0-9]/g, '') === b.toLowerCase().replace(/[^a-z0-9]/g, '');

// Every model the brand sells this year (or last year if this year's list is empty).
export function useBrandModels(brand: string | null) {
  const [got, setGot] = useState<{ brand: string; list: string[] } | null>(null);
  useEffect(() => {
    if (!brand) return;
    let on = true;
    modelsFor(brand, LATEST_MODEL_YEAR).then((m) => (m.length ? m : modelsFor(brand, LATEST_MODEL_YEAR - 1))).catch(() => [] as string[])
      .then((list) => { if (on) setGot({ brand, list }); });
    return () => { on = false; };
  }, [brand]);
  return brand && got?.brand === brand ? got.list : null;
}

export function BrandMore({ brand, models }: { brand: string; models: string[] | null }) {
  const ours = CARS.filter((c) => c.make === dataMake(brand)).map((c) => c.model);
  const more = (models ?? []).filter((m) => !ours.some((o) => same(o, m) || same(o.split(' ')[0], m)));
  if (!more.length) return null;
  return (
    <View style={{ marginTop: 18 }}>
      <Label>More {brand} models · {more.length}</Label>
      <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 2, marginBottom: 8 }}>Full details and prices for these are coming. A dealer can tell you what’s on the lot.</Body>
      {more.map((m) => (
        <View key={m} style={s.row}>
          <Body bold>{brand} {m}</Body>
          <Body style={{ fontSize: 12, color: C.muted }}>Coming soon</Body>
        </View>
      ))}
      <Body style={{ fontSize: 11, color: C.muted, marginTop: 6 }}>Model list from NHTSA.gov.</Body>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  row: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', borderRadius: 14, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 14, paddingVertical: 12, marginBottom: 8 },
}));
