// The "📍 Use my location" button (picture 125 panel 1). Tapping it makes the phone ask (panel 3), then hands
// back the spot and ZIP. Hidden on phone apps without the location part (built before Oct 21, 2026).
import { useState } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';

import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { canLocate, locate, type Spot } from '@/lib/location';
import { C, F, themed } from '@/theme';
import { PinIcon } from '@/components/icons';

const WHY = {
  denied: 'Location is off for Carvessa. You can turn it on in your phone’s settings, or type a ZIP code.',
  off: 'Your phone’s location is turned off. Turn it on, or type a ZIP code.',
  fail: 'We couldn’t find you right now. Type a ZIP code instead.',
  nozip: 'We couldn’t find your ZIP code there. Type it instead.',
};

/** needZip: only hand back a spot when we found its ZIP code (places that search by ZIP). */
export function UseMyLocation({ onSpot, needZip, style }: { onSpot: (s: Spot) => void; needZip?: boolean; style?: object }) {
  const [busy, setBusy] = useState(false);
  const [why, setWhy] = useState<keyof typeof WHY | null>(null);
  if (!canLocate) return null;
  const go = async () => {
    tap();
    setBusy(true);
    setWhy(null);
    const r = await locate();
    setBusy(false);
    if (!r.ok) return setWhy(r.why);
    if (needZip && !r.spot.zip) return setWhy('nozip');
    onSpot(r.spot);
  };
  return (
    <View style={style}>
      <Pressable onPress={go} disabled={busy} accessibilityRole="button" accessibilityLabel="Use my location" accessibilityState={{ busy }}
        style={({ pressed }) => [s.btn, pressed && { opacity: 0.85 }]}>
        {busy ? <ActivityIndicator size="small" color={C.onAccent} /> : <PinIcon size={16} color={C.onAccent} />}
        <Text style={s.label}>{busy ? 'Finding you…' : 'Use my location'}</Text>
      </Pressable>
      {why ? <Text style={s.why} accessibilityLiveRegion="polite">{WHY[why]}</Text> : null}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  btn: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 8, backgroundColor: C.fill, borderRadius: 13, minHeight: 46, paddingHorizontal: 14 },
  pin: { fontSize: 16 },
  label: { fontFamily: F.bodyBold, fontSize: 15, color: C.onAccent },
  why: { fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 6, lineHeight: 17 },
}));
