// Receipt photos for the car log (picture 221, option 1): kept on this phone only, never uploaded.
// A picked photo lives in a temporary folder, so we copy it into the app's own documents folder.
import { Platform } from 'react-native';

import type { Photo } from '@/lib/photo';

export function saveReceipt(p: Photo, id: string): string {
  if (Platform.OS === 'web') return p.base64 ? `data:${p.mime ?? 'image/jpeg'};base64,${p.base64}` : p.uri;
  try {
    const FS = require('expo-file-system') as typeof import('expo-file-system'); // eslint-disable-line @typescript-eslint/no-require-imports
    const dir = new FS.Directory(FS.Paths.document, 'receipts');
    if (!dir.exists) dir.create();
    const to = new FS.File(dir, `${id}.jpg`);
    if (to.exists) to.delete();
    new FS.File(p.uri).copy(to);
    return to.uri;
  } catch {
    return p.uri; // an older test app: keep the picker's copy
  }
}

export function deleteReceipt(uri?: string) {
  if (!uri || Platform.OS === 'web' || !uri.includes('/receipts/')) return;
  try {
    const FS = require('expo-file-system') as typeof import('expo-file-system'); // eslint-disable-line @typescript-eslint/no-require-imports
    const f = new FS.File(uri);
    if (f.exists) f.delete();
  } catch { /* nothing to clean */ }
}
