// About & legal (moved here from Me with the free account, Oct 18, 2026): your coach answers, where our info
// comes from, Privacy, Terms and contact.
import * as Updates from 'expo-updates';
import { router } from 'expo-router';
import { Linking, ScrollView, StyleSheet, View } from 'react-native';

import { AccountTop, Card, Row, Sec } from '@/components/account-ui';
import { InfoIcon, MailIcon } from '@/components/icons';
import { Body, Btn, tap } from '@/components/ui';
import { CONTACT_EMAIL } from '@/data/legal';
import { useAnswers } from '@/state/answers';
import { C, PAD, themed } from '@/theme';
import { Pressable } from '@/components/t';

function Line({ label, value }: { label: string; value?: string }) {
  return (
    <View style={s.row}>
      <Body bold>{label}</Body>
      <Body style={{ color: value ? C.ink : C.muted, flexShrink: 1, textAlign: 'right' }}>{value || 'Not set'}</Body>
    </View>
  );
}
function Src({ label, url }: { label: string; url: string }) {
  return (
    <Pressable onPress={() => { tap(); Linking.openURL(url); }} accessibilityRole="link" style={s.row}>
      <Body bold style={{ textDecorationLine: 'underline', flex: 1 }}>{label}</Body>
      <Body style={{ color: C.muted }}>Open</Body>
    </Pressable>
  );
}

export default function About() {
  const { answers, startChat, history, openChat } = useAnswers();
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="About & legal" />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }}>
        <Sec>Your coach answers</Sec>
        <Card>
          <Line label="Goal" value={answers.goal} />
          <Line label="Budget" value={answers.budget} />
          <Line label="Must-haves" value={answers.mustHaves.join(', ')} />
          <Line label="Nice to have" value={answers.wants?.join(', ')} />
          <Line label="Color" value={answers.color} />
          <Line label="Your car" value={answers.myCar} />
          <Line label="ZIP code" value={answers.zip} />
        </Card>
        <Btn small label="Change answers" style={{ marginTop: 10 }} onPress={() => { if (history[0]) openChat(history[0].id); else startChat(); router.navigate('/coach'); }} />
        <Sec>Where our info comes from</Sec>
        <Card>
          <Src label="Crash tests and recalls: NHTSA" url="https://www.nhtsa.gov/" />
          <Src label="Gas mileage: FuelEconomy.gov (EPA)" url="https://www.fueleconomy.gov/" />
          <Src label="Dealer map: OpenStreetMap" url="https://www.openstreetmap.org/copyright" />
          <Src label="Car photos: Wikimedia Commons" url="https://commons.wikimedia.org/" />
        </Card>
        <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 6, marginHorizontal: 4 }}>
          New prices are carmakers’ starting prices from public price guides. Used prices are estimates until we connect real dealer prices. Pros and cons are Carvessa’s notes.
        </Body>
        <Sec>Legal</Sec>
        <Card>
          <Row icon={(c) => <InfoIcon size={18} color={c} />} label="Privacy Policy" onPress={() => router.push({ pathname: '/legal', params: { tab: 'privacy' } })} />
          <Row icon={(c) => <InfoIcon size={18} color={c} />} label="Terms of Use" onPress={() => router.push({ pathname: '/legal', params: { tab: 'terms' } })} />
          <Row last t="green" icon={(c) => <MailIcon size={18} color={c} />} label="Contact us" value={CONTACT_EMAIL} onPress={() => Linking.openURL(`mailto:${CONTACT_EMAIL}`)} />
        </Card>
        <Body style={{ marginTop: 14, marginHorizontal: 4 }}>Carvessa helps everybody find the car that fits their life, at any budget.</Body>
        <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 4, marginHorizontal: 4 }}>carvessa.app · Early test version</Body>
        {/* Which update this phone is running, so we can tell if the newest one arrived. */}
        <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 2, marginHorizontal: 4 }}>{`App update: ${Updates.createdAt ? Updates.createdAt.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : 'built in'}`}</Body>
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  row: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: 12, paddingVertical: 11, borderBottomWidth: 1, borderBottomColor: C.line },
}));
