// Edit profile (picture 106, set 2): first name and ZIP only. The ZIP also sets prices, tax and dealers near you.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';

import { AccountTop, BigBtn, Sec } from '@/components/account-ui';
import { PicturePicker, ProfilePic } from '@/components/profile-pic';
import { tap } from '@/components/ui';
import { LangPicker } from '@/components/lang-picker';
import { notify } from '@/components/notify';
import { useAnswers } from '@/state/answers';
import { useAuth } from '@/state/auth';
import { C, F, PAD, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';
import { UseMyLocation } from '@/components/use-location';

export default function Profile() {
  const { session, profile, updateProfile } = useAuth();
  const { answers, setAnswers } = useAnswers();
  const [name, setName] = useState(profile.name);
  const [zip, setZip] = useState(profile.zip || answers.zip || '');
  const [busy, setBusy] = useState(false);
  const [picking, setPicking] = useState(false);
  const save = async () => {
    if (!name.trim()) return notify('Edit profile', 'Type your first name.');
    if (zip && !/^\d{5}$/.test(zip)) return notify('Edit profile', 'A ZIP code has 5 numbers.');
    setBusy(true);
    const err = await updateProfile({ name, zip });
    setBusy(false);
    if (err) return notify('Edit profile', err);
    if (zip && zip !== answers.zip) setAnswers({ ...answers, zip });
    notify('Saved', 'Your profile is up to date.');
    router.navigate('/me');
  };
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Edit profile" />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }} keyboardShouldPersistTaps="handled">
        {/* Picture 131: tap your picture to change it (your own photo, Normal or Fun pictures, or your letter). */}
        <Pressable onPress={() => { tap(); setPicking(true); }} accessibilityRole="button" accessibilityLabel="Change picture" style={{ alignItems: 'center', marginTop: 6 }}>
          <ProfilePic name={name || '?'} size={96} />
          <Text style={s.change}>Change picture</Text>
        </Pressable>
        <Text style={s.lab}>First name</Text>
        <TextInput value={name} onChangeText={setName} maxLength={40} style={s.in} accessibilityLabel="First name" autoComplete="given-name" />
        <Text style={s.lab}>ZIP code · for prices, tax and dealers near you</Text>
        <TextInput value={zip} onChangeText={setZip} maxLength={5} keyboardType="number-pad" style={s.in} accessibilityLabel="ZIP code" />
        <UseMyLocation needZip style={{ marginTop: 8 }} onSpot={(sp) => setZip(sp.zip!)} />
        <Text style={s.lab}>Email · can’t change here</Text>
        <Text style={[s.in, s.ro]}>{session?.user.email ?? ''}</Text>
        <Sec>Language</Sec>
        <LangPicker />
        <BigBtn label={busy ? 'Saving…' : 'Save'} onPress={save} />
        <Text style={[s.note, { marginTop: 12 }]}>That’s all we ask. We never sell your info.</Text>
      </ScrollView>
      {picking && <PicturePicker name={name} onClose={() => setPicking(false)} />}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  change: { fontFamily: F.bodyBold, fontSize: 14, color: C.yellow, marginTop: 8 },
  note: { fontFamily: F.body, fontSize: 12.5, color: C.muted, textAlign: 'center', marginTop: 6 },
  lab: { fontFamily: F.bodyBold, fontSize: 12.5, color: C.muted, marginTop: 16, marginBottom: 6, marginLeft: 4 },
  in: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  ro: { backgroundColor: C.bg, borderStyle: 'dashed', color: C.muted },
}));
