// "About this car" on the car-for-sale page (picture 149 A, Oct 26, 2026, Loudjier: 'Build A. We can do B when we
// launch or after we start making money'). The facts come from THAT car's own VIN (NHTSA vPIC: trim, engine, drive,
// where it was built), its listing (accidents, owners, miles) and its model year (recalls, crash stars, EPA gas).
// "Our take" is written by these rules from those facts only, so it never makes anything up (no AI).
import { powerFrom, type Power, type Verdict } from '@/data/check';
import { thisYear } from '@/data/year';

const VPIC = 'https://vpic.nhtsa.dot.gov/api/vehicles';
const title = (s: string) => s.toLowerCase().replace(/(^|[\s-])\S/g, (x) => x.toUpperCase());

export type VinFacts = { trim?: string; engine?: string; drive?: string; builtIn?: string; power?: Power };

// vPIC words → plain words.
export function driveFrom(d?: string): string | undefined {
  const s = (d ?? '').toLowerCase();
  if (!s) return undefined;
  if (s.includes('awd') || s.includes('all-wheel') || s.includes('all wheel')) return 'All-wheel';
  if (s.includes('4wd') || s.includes('4x4') || s.includes('four')) return '4-wheel';
  if (s.includes('fwd') || s.includes('front')) return 'Front-wheel';
  if (s.includes('rwd') || s.includes('rear')) return 'Rear-wheel';
  return undefined;
}
export function engineFrom(x: Record<string, string | undefined>): string | undefined {
  if (/electric/i.test(x.FuelTypePrimary ?? '') && !x.DisplacementL) return 'Electric';
  const l = Number(x.DisplacementL);
  const cyl = Number(x.EngineCylinders);
  if (!l && !cyl) return undefined;
  const hybrid = /hybrid|hev/i.test(x.ElectrificationLevel ?? '') ? ' hybrid' : '';
  return [l ? `${l.toFixed(1)}L` : null, cyl ? `${cyl}-cyl` : null].filter(Boolean).join(' ') + hybrid;
}
export function builtFrom(x: Record<string, string | undefined>): string | undefined {
  const country = (x.PlantCountry ?? '').trim();
  const usa = /united states/i.test(country);
  const place = [x.PlantState ? title(x.PlantState) : null, country ? (usa ? 'USA' : title(country)) : null].filter(Boolean);
  return place.length ? place.join(', ') : undefined;
}

export async function vinFacts(vin: string): Promise<VinFacts | null> {
  const r = await fetch(`${VPIC}/DecodeVinValues/${encodeURIComponent(vin.trim())}?format=json`);
  const x = (await r.json())?.Results?.[0] as Record<string, string | undefined> | undefined;
  if (!x?.Make) return null;
  return { trim: x.Trim || undefined, engine: engineFrom(x), drive: driveFrom(x.DriveType), builtIn: builtFrom(x), power: powerFrom(x) };
}

// People drive about 12,000 miles a year (the same rule as our price check).
export type MilesFeel = 'low' | 'normal' | 'high';
export const normalMiles = (year: number) => Math.max(1, thisYear() - year) * 12000;
export function milesFeel(miles: number, year: number): MilesFeel {
  const n = normalMiles(year);
  return miles < n * 0.8 ? 'low' : miles > n * 1.25 ? 'high' : 'normal';
}

// Our take: short sentences, each one fixed words (or a simple number pattern) so it can be said in Spanish too.
export function ourTake(t: { tag?: Verdict; miles?: number | null; year: number; accidents?: number | null; recalls?: number | null }): string[] {
  const out: string[] = [];
  if (t.tag) out.push(t.tag === 'fair' ? 'A fair price.' : t.tag === 'low' ? 'Priced lower than most like it, so ask why.' : 'Priced above most like it, so ask for a lower price.');
  if (t.miles != null) {
    const f = milesFeel(t.miles, t.year);
    out.push(f === 'low' ? 'Fewer miles than usual for its age.' : f === 'high' ? 'More miles than usual for its age.' : 'About normal miles for its age.');
  }
  if (t.accidents) out.push(t.accidents === 1 ? 'Ask about the reported accident, and get a mechanic’s check.' : `Ask about the ${t.accidents} reported accidents, and get a mechanic’s check.`);
  if (t.recalls) out.push(t.recalls === 1 ? 'Ask the dealer to show the recall was fixed.' : `Ask the dealer to show the ${t.recalls} recalls were fixed.`);
  if (!t.accidents && !t.recalls && t.accidents === 0 && t.recalls === 0) out.push('No accidents or recalls reported. A mechanic’s check is still smart.');
  return out;
}
