// My car recall page (picture 103 B, Oct 18, 2026): "My dealer" saved with a star, plus the closest
// dealer of the car's brand. Recall repairs are free at any dealer of that brand.
import { useEffect, useState } from 'react';
import { ActivityIndicator, Linking, Platform, StyleSheet, View } from 'react-native';

import { PinIcon } from '@/components/icons';
import { Body, Label, tap } from '@/components/ui';
import { type Dealer, type DealerResult, findDealers } from '@/data/dealers';
import { useAnswers } from '@/state/answers';
import { type MyCar } from '@/state/saved';
import { C, F, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';
import { UseMyLocation } from '@/components/use-location';

// The brand as dealers write it on their sign ("chevy" → "Chevrolet").
const NICK: Record<string, string> = { chevy: 'Chevrolet', vw: 'Volkswagen', mercedes: 'Mercedes-Benz', benz: 'Mercedes-Benz', landrover: 'Land Rover' };
export const brandOf = (make: string) => {
  const m = make.trim();
  return NICK[m.toLowerCase().replace(/[\s-]/g, '')] ?? m.replace(/\b\w/g, (x) => x.toUpperCase());
};

const mapsUrl = (d: Dealer) =>
  Platform.OS === 'ios'
    ? `http://maps.apple.com/?daddr=${d.lat},${d.lon}&q=${encodeURIComponent(d.name)}`
    : `https://www.google.com/maps/dir/?api=1&destination=${d.lat},${d.lon}`;

function DealerCard({ d, title, mine, onStar }: { d: Dealer; title: string; mine: boolean; onStar: () => void }) {
  return (
    <View style={s.card}>
      <View style={{ flexDirection: 'row', gap: 10 }}>
        <View style={s.pin}><PinIcon size={18} color={C.onAccent} /></View>
        <View style={{ flex: 1 }}>
          <Text style={s.kick}>{title}</Text>
          <Body bold style={{ fontSize: 16 }}>{d.name}</Body>
          <Body style={{ fontSize: 13, color: C.muted }}>{[`About ${d.miles} mi`, d.address].filter(Boolean).join(' · ')}</Body>
        </View>
        <Pressable onPress={() => { tap(); onStar(); }} accessibilityRole="button" hitSlop={10}
          accessibilityLabel={mine ? 'Remove as my dealer' : 'Make this my dealer'} accessibilityState={{ selected: mine }}>
          <Text style={[s.star, mine && { color: C.yellow }]}>{mine ? '★' : '☆'}</Text>
        </Pressable>
      </View>
      <View style={s.acts}>
        {!!d.phone && (
          <Pressable onPress={() => { tap(); Linking.openURL(`tel:${d.phone!.replace(/[^\d+]/g, '')}`); }} accessibilityRole="button" style={s.act}>
            <Text style={s.actT}>Call</Text>
          </Pressable>
        )}
        <Pressable onPress={() => { tap(); Linking.openURL(mapsUrl(d)); }} accessibilityRole="button" style={s.act}>
          <Text style={s.actT}>Directions</Text>
        </Pressable>
      </View>
    </View>
  );
}

export function RecallDealer({ myCar, setMyCar }: { myCar: MyCar; setMyCar: (c: MyCar) => void }) {
  const { answers, setAnswers } = useAnswers();
  const brand = brandOf(myCar.make);
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const [typed, setTyped] = useState('');
  const key = zip && brand ? `${brand}-${zip}` : '';
  const [found, setFound] = useState<{ key: string; res: DealerResult | null; error: boolean }>({ key: '', res: null, error: false });
  useEffect(() => {
    if (!key) return;
    let live = true;
    findDealers(brand, zip)
      .then((r) => live && setFound({ key, res: r, error: false }))
      .catch(() => live && setFound({ key, res: null, error: true }));
    return () => { live = false; };
  }, [key, brand, zip]);
  const res = found.key === key ? found.res : null;
  const loading = !!key && found.key !== key;
  const mine = myCar.dealer;
  const star = (d: Dealer) => setMyCar({ ...myCar, dealer: mine?.id === d.id ? undefined : d });
  const closest = res?.dealers[0];
  const others = (res?.dealers ?? []).filter((d) => d.id !== mine?.id && d.id !== closest?.id).slice(0, 2);

  return (
    <View>
      <Label style={s.sec}>{mine ? 'My dealer' : `${brand} dealers near you`}</Label>
      <Body style={{ fontSize: 13, color: C.muted, marginBottom: 4 }}>{`Recall repairs are free at any ${brand} dealer. Call first to book.`}</Body>
      {mine && <DealerCard d={mine} title="My dealer" mine onStar={() => star(mine)} />}
      {!zip && (
        <View style={s.zipRow}>
          <TextInput value={typed} onChangeText={setTyped} keyboardType="number-pad" maxLength={5} placeholder="Your ZIP code" placeholderTextColor={C.muted}
            accessibilityLabel="ZIP code" style={s.zip} returnKeyType="search" onSubmitEditing={() => /^\d{5}$/.test(typed) && setAnswers({ ...answers, zip: typed })} />
          <Pressable onPress={() => { if (/^\d{5}$/.test(typed)) { tap(); setAnswers({ ...answers, zip: typed }); } }} accessibilityRole="button" style={s.zipBtn}>
            <Text style={s.actT}>Find dealers</Text>
          </Pressable>
        </View>
      )}
      {!zip && <UseMyLocation needZip style={{ marginTop: 8 }} onSpot={(sp) => setAnswers({ ...answers, zip: sp.zip! })} />}
      {loading && <View style={s.wait}><ActivityIndicator color={C.ink} /><Body>{`Finding ${brand} dealers…`}</Body></View>}
      {found.key === key && found.error && <Body style={{ marginTop: 8 }}>We couldn’t load dealers right now. Check your internet and try again.</Body>}
      {res && !res.dealers.length && <Body style={{ marginTop: 8 }}>{`No ${brand} dealers found within 30 miles of ${res.place}.`}</Body>}
      {closest && (mine ? closest.id !== mine.id && closest.miles < mine.miles && (
        <Pressable onPress={() => { tap(); star(closest); }} accessibilityRole="button" style={s.closer}>
          <Body style={{ fontSize: 14, flex: 1 }}><Body bold style={{ fontSize: 14 }}>Closer: </Body>{`${closest.name} · ${closest.miles} mi`}</Body>
          <Text style={s.actT}>Switch ›</Text>
        </Pressable>
      ) : <DealerCard d={closest} title={`Closest ${brand} dealer`} mine={false} onStar={() => star(closest)} />)}
      {!mine && others.map((d) => <DealerCard key={d.id} d={d} title={`${brand} dealer`} mine={false} onStar={() => star(d)} />)}
      {!mine && closest && <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 8 }}>Tap ☆ on a dealer to make it yours.</Body>}
      {res && <Body style={{ fontSize: 11, color: C.muted, marginTop: 6 }}>Dealer map data © OpenStreetMap contributors.</Body>}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  sec: { marginTop: 20, marginBottom: 4 },
  card: { backgroundColor: C.card, borderRadius: 18, padding: 14, marginTop: 8, borderWidth: 1, borderColor: C.line },
  pin: { width: 38, height: 38, borderRadius: 12, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  kick: { fontFamily: F.bodyBold, fontSize: 11.5, letterSpacing: 1, color: C.onAccent, textTransform: 'uppercase' },
  star: { fontSize: 26, color: C.muted, lineHeight: 30 },
  acts: { flexDirection: 'row', gap: 8, marginTop: 10 },
  act: { flex: 1, backgroundColor: C.fill, borderRadius: 999, paddingVertical: 9, alignItems: 'center' },
  actT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  closer: { flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: C.card, borderRadius: 14, padding: 12, marginTop: 8, borderWidth: 1, borderColor: C.line },
  zipRow: { flexDirection: 'row', gap: 6, marginTop: 6 },
  zip: { flex: 1, height: 48, borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, backgroundColor: C.card },
  zipBtn: { paddingHorizontal: 14, height: 48, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center', borderRadius: 12 },
  wait: { flexDirection: 'row', gap: 10, alignItems: 'center', marginTop: 10 },
}));
