/** Wikimedia's own thumbnail of a Commons file (standard 960 px width). */
export function shotUrl(s: Shot, w = 960): string {
  const n = encodeURIComponent(s.file.replace(/ /g, '_'));
  return `https://upload.wikimedia.org/wikipedia/commons/thumb/${s.path}/${n}/${w}px-${n}`;
}
export const shotPage = (s: Shot) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(s.file.replace(/ /g, '_'))}`;

export type Slide = { kind: 'cut'; key: string } | { kind: 'shot'; shot: Shot };
export type CarGallery = { slides: Slide[]; badge: string | null };

/** What the car page shows for this car and year: which photos, and a 'which years look like this' badge. */
export function galleryFor(id: string, year: number | undefined, cutKey: string): CarGallery {
  const looks = OLD_LOOKS[id] ?? [];
  const old = year != null ? looks.find((l) => year >= l.from && year <= l.to) : undefined;
  if (old) {
    const slides: Slide[] = old.cut ? [{ kind: 'cut', key: old.cut }] : [];
    old.shots.forEach((shot) => slides.push({ kind: 'shot', shot }));
    return { slides, badge: `${old.from}–${old.to} look` };
  }
  const slides: Slide[] = [{ kind: 'cut', key: cutKey }, ...(NOW_SHOTS[id] ?? []).map((shot) => ({ kind: 'shot' as const, shot }))];
  const newestOld = looks.reduce((m, l) => Math.max(m, l.to), 0);
  return { slides, badge: newestOld ? `${newestOld + 1} and newer look` : null };
}
