// More on Home under "Popular right now" (pictures 110 A + 111, Loudjier: "A it is… best safety, best for family",
// "if it's too long show 6 then more", "if we know their budget… show the matches", Oct 19, 2026).
// Swipe rows of small cut-out cards. Our own picks from our data, not ads.
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

import { VRow } from '@/components/v-card';
import { ArrowIcon, MapIcon } from '@/components/icons';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { tr } from '@/i18n';
import { homeRows, planRow, recentRow, topBrands, type Row } from '@/data/home-rows';
import type { Answers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { C, F, PAD, themed } from '@/theme';

const FIRST = 6; // sections shown before "Show more ideas"

function Head({ title, sub, link, onLink }: { title: string; sub?: string; link?: string; onLink?: () => void }) {
  return (
    <View style={{ marginTop: 22, marginBottom: 10, paddingHorizontal: PAD }}>
      <View style={s.head}>
        <Text style={s.title} accessibilityRole="header">{title}</Text>
        {link && onLink && <Pressable onPress={() => { tap(); onLink(); }} accessibilityRole="button" hitSlop={8}><Text style={s.link}>{link}</Text></Pressable>}
      </View>
      {!!sub && <Text style={s.sub}>{sub}</Text>}
    </View>
  );
}

// Picture 129 A (Oct 24, 2026): "See all N ›" at the top and a last card at the end of the swipe open the row's own page.
function Swipe({ row, link, onLink, end }: { row: Row; link?: string; onLink?: () => void; end?: boolean }) {
  return (
    <View>
      <Head title={row.title} sub={row.sub} link={link} onLink={onLink} />
      {/* Picture 234 (Nov 13, 2026): the V card, two per screen. */}
      <VRow picks={row.picks} end={end && onLink ? (
        <Pressable onPress={() => { tap(); onLink(); }} accessibilityRole="button" accessibilityLabel={`${tr('See all')} ${tr(row.title)}`} style={[s.end, { flex: 1 }]}>
          <View style={s.endIcon}><ArrowIcon size={20} color={C.onAccent} /></View>
          <Text style={s.endT}>{row.total ? `See all ${row.total} cars` : 'See all'}</Text>
        </Pressable>
      ) : undefined} />
    </View>
  );
}

export function HomeRows({ answers }: { answers: Answers }) {
  const { recent, clearRecent } = useSaved();
  const [all, setAll] = useState(false);
  const rows = useMemo(() => homeRows(answers), [answers]);
  const plan = useMemo(() => planRow(answers), [answers]);
  const seen = useMemo(() => recentRow(answers, recent), [answers, recent]);
  const brands = useMemo(() => topBrands().slice(0, 10), []);

  const near = (
    <View key="near">
      <Head title="For sale near you" />
      <Pressable onPress={() => { tap(); router.push('/shop'); }} accessibilityRole="button" style={[s.near, { marginHorizontal: PAD }]}>
        <View style={s.nearIcon}><MapIcon size={22} color={C.onAccent} /></View>
        <View style={{ flex: 1 }}>
          <Text style={s.nearTitle}>Real cars at dealers around you</Text>
          <Text style={s.sub}>On a map, closest drive first, with a fair-price check.</Text>
        </View>
        <ArrowIcon />
      </Pressable>
    </View>
  );
  const brandRow = (
    <View key="brands">
      <Head title="Shop by brand" />
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.scroll}>
        {brands.map((b) => (
          <Pressable key={b} onPress={() => { tap(); router.push({ pathname: '/search', params: { q: b } }); }} accessibilityRole="button" style={s.brand}>
            <Text style={s.brandText} numberOfLines={1}>{b}</Text>
          </Pressable>
        ))}
      </ScrollView>
    </View>
  );

  // Order (picture 111): near you, fits your plan, brands, the Best for… rows (coach goal first), you looked at.
  const parts: React.ReactNode[] = [near];
  if (plan) parts.push(<Swipe key="plan" row={plan} link="See all" onLink={() => router.push({ pathname: '/results', params: { upgrade: '0' } })} />);
  parts.push(brandRow);
  for (const r of rows) parts.push(<Swipe key={r.key} row={r} end link={`See all ${r.total ?? r.picks.length} ›`} onLink={() => router.push({ pathname: '/row/[key]', params: { key: r.key } })} />);
  if (seen) parts.push(<Swipe key="recent" row={seen} link="Clear" onLink={clearRecent} />);
  const shown = all ? parts : parts.slice(0, FIRST);

  return (
    <View style={{ marginHorizontal: -PAD }}>
      {shown}
      {/* Picture 112 A (Oct 19, 2026): a light link with a count, and a small "not ads" badge. */}
      {!all && parts.length > FIRST && (
        <Pressable onPress={() => { tap(); setAll(true); }} accessibilityRole="button" hitSlop={8} style={s.more}>
          <Text style={s.moreText}>{`See ${parts.length - FIRST} more ideas`}</Text>
          <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke={C.yellow} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round"><Path d="M6 9l6 6 6-6" /></Svg>
        </Pressable>
      )}
      <View style={s.badge} accessible accessibilityLabel={tr('Our own picks from NHTSA safety, EPA mileage and our price estimates. Not ads.')}>
        <Svg width={13} height={13} viewBox="0 0 24 24" fill="none" stroke={C.goodInk} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round"><Path d="M5 12.5l4.5 4.5L19 7.5" /></Svg>
        <Text style={s.badgeText}>Our picks · not ads</Text>
      </View>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  head: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline', gap: 10 },
  title: { flex: 1, fontFamily: F.head, fontSize: 18, color: C.ink, letterSpacing: -0.2 },
  link: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.yellow },
  sub: { fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 2 },
  scroll: { gap: 10, paddingHorizontal: PAD, paddingBottom: 6 },
  card: { width: 150, backgroundColor: C.card, borderRadius: 18, padding: 8, shadowColor: '#0F1A2A', shadowOpacity: 0.07, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 2 },
  name: { fontFamily: F.bodyBold, fontSize: 13, lineHeight: 16, color: C.ink, marginTop: 7 },
  line: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 2 },
  tag: { alignSelf: 'flex-start', borderRadius: 999, paddingHorizontal: 8, paddingVertical: 2, marginTop: 5, maxWidth: '100%' },
  tagText: { fontFamily: F.bodyBold, fontSize: 11 },
  end: { width: 112, backgroundColor: C.fill, borderRadius: 18, alignItems: 'center', justifyContent: 'center', gap: 8, padding: 10 },
  endIcon: { width: 40, height: 40, borderRadius: 20, backgroundColor: C.card, alignItems: 'center', justifyContent: 'center' },
  endT: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.onAccent, textAlign: 'center' },
  near: { flexDirection: 'row', alignItems: 'center', gap: 12, backgroundColor: C.card, borderRadius: 18, padding: 14, shadowColor: '#0F1A2A', shadowOpacity: 0.07, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 2 },
  nearIcon: { width: 42, height: 42, borderRadius: 13, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
  nearTitle: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  brand: { minWidth: 84, height: 64, paddingHorizontal: 12, borderRadius: 18, backgroundColor: C.card, alignItems: 'center', justifyContent: 'center', shadowColor: '#0F1A2A', shadowOpacity: 0.07, shadowRadius: 10, shadowOffset: { width: 0, height: 4 }, elevation: 2 },
  brandText: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
  more: { flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, alignSelf: 'center', paddingVertical: 10, paddingHorizontal: 16, marginTop: 14 },
  moreText: { fontFamily: F.bodyBold, fontSize: 16, color: C.yellow },
  badge: { flexDirection: 'row', alignItems: 'center', gap: 5, alignSelf: 'center', backgroundColor: C.card, borderRadius: 999, paddingHorizontal: 12, paddingVertical: 6, marginTop: 8, shadowColor: '#0F1A2A', shadowOpacity: 0.07, shadowRadius: 8, shadowOffset: { width: 0, height: 3 }, elevation: 1 },
  badgeText: { fontFamily: F.bodyBold, fontSize: 12, color: C.muted },
}));
