// Colors of real cars for sale (picture 75 A + D, Oct 16, 2026).
// ColorDots: round swatches with counts on the car page (tap one to see only that color).
// ColorChips: small color buttons on the cars-for-sale map (tap several; "Any" clears).
import { ScrollView, StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import { colorCounts, hexOf, type ColorFamily } from '@/data/colors';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

export function ColorDots({ colors, value, onChange }: { colors: (string | null | undefined)[]; value: ColorFamily | null; onChange: (f: ColorFamily | null) => void }) {
  const counts = colorCounts(colors);
  return (
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6, paddingVertical: 4 }}>
      {counts.map(({ name, count }) => {
        const on = value === name;
        return (
          <Pressable key={name} onPress={() => { tap(); onChange(on ? null : name); }} accessibilityRole="button" accessibilityState={{ selected: on }}
            accessibilityLabel={`${name}, ${count} car${count === 1 ? '' : 's'}`} style={s.dotWrap}>
            <View style={[s.ring, on && { borderColor: C.yellow }]}><View style={[s.dot, { backgroundColor: hexOf(name) }]} /></View>
            <Text style={s.dotName}>{name}</Text>
            <Text style={s.dotCount}>{`${count} car${count === 1 ? '' : 's'}`}</Text>
          </Pressable>
        );
      })}
    </ScrollView>
  );
}

export function ColorChips({ colors, value, onChange }: { colors: (string | null | undefined)[]; value: ColorFamily[]; onChange: (v: ColorFamily[]) => void }) {
  const counts = colorCounts(colors);
  if (counts.length < 2) return null;
  return (
    <View style={s.chips}>
      <Pressable onPress={() => { tap(); onChange([]); }} accessibilityRole="button" accessibilityState={{ selected: !value.length }} style={[s.chip, !value.length && s.chipOn]}>
        <Text style={s.chipText}>Any color</Text>
      </Pressable>
      {counts.map(({ name, count }) => {
        const on = value.includes(name);
        return (
          <Pressable key={name} onPress={() => { tap(); onChange(on ? value.filter((x) => x !== name) : [...value, name]); }} accessibilityRole="button"
            accessibilityState={{ selected: on }} accessibilityLabel={`${name}, ${count} car${count === 1 ? '' : 's'}`} style={[s.chip, on && s.chipOn]}>
            <View style={[s.mini, { backgroundColor: hexOf(name) }]} />
            <Text style={s.chipText}>{name}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  dotWrap: { alignItems: 'center', width: 58 },
  ring: { width: 40, height: 40, borderRadius: 20, borderWidth: 2, borderColor: 'transparent', alignItems: 'center', justifyContent: 'center' },
  dot: { width: 30, height: 30, borderRadius: 15, borderWidth: 1, borderColor: 'rgba(128,128,128,0.45)' },
  dotName: { fontFamily: F.bodyBold, fontSize: 12, color: C.ink, marginTop: 2 },
  dotCount: { fontFamily: F.body, fontSize: 11, color: C.muted },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 8 },
  chip: { flexDirection: 'row', alignItems: 'center', gap: 5, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 6 },
  chipOn: { borderColor: C.yellow, backgroundColor: C.accentSoft },
  mini: { width: 12, height: 12, borderRadius: 6, borderWidth: 1, borderColor: 'rgba(128,128,128,0.45)' },
  chipText: { fontFamily: F.bodyBold, fontSize: 13, color: C.ink },
}));
