// Picture 237 · 3B (Nov 13, 2026): the road to your car. Each step is a stop; tapping one opens it and turns it
// green. Progress is kept on the phone per car + version. Steps open screens the app already has.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { money } from '@/components/versions';
import { CARS } from '@/data/cars';
import { otdLines } from '@/data/fair-price';
import { COMMON_ASK, GUIDE } from '@/data/guide';
import { priceFor } from '@/data/prices';
import { loanOf } from '@/data/search-budget';
import { tr } from '@/i18n';
import { paymentFor, useAnswers } from '@/state/answers';
import { C, F, isDarkLook, look, PAD, themed } from '@/theme';

const KEY = 'carvessa:road:v1';
export type StepId = 'shop' | 'otd' | 'check' | 'ask';
export const STEPS: StepId[] = ['shop', 'otd', 'check', 'ask'];
export const roadKey = (id: string, year: number, trim: string) => `${id}|${year}|${trim}`;

async function load(): Promise<Record<string, StepId[]>> {
  try { return JSON.parse((await AsyncStorage.getItem(KEY)) ?? '{}') ?? {}; } catch { return {}; }
}

export default function BuyRoad() {
  const q = useLocalSearchParams<{ id: string; year?: string; trim?: string }>();
  const { answers } = useAnswers();
  const car = CARS.find((c) => c.id === q.id);
  const year = Number(q.year) || new Date().getFullYear();
  const trim = q.trim ?? '';
  const k = car ? roadKey(car.id, year, trim) : '';
  const [done, setDone] = useState<StepId[]>([]);
  const [open, setOpen] = useState<StepId | null>(null);
  useEffect(() => { let on = true; load().then((all) => { if (on) setDone(all[k] ?? []); }); return () => { on = false; }; }, [k]);
  const mark = (id: StepId) => {
    setDone((d) => {
      const next = d.includes(id) ? d : [...d, id];
      load().then((all) => AsyncStorage.setItem(KEY, JSON.stringify({ ...all, [k]: next })).catch(() => {}));
      return next;
    });
  };
  const restart = () => { tap(); setDone([]); setOpen(null); load().then((all) => { delete all[k]; AsyncStorage.setItem(KEY, JSON.stringify(all)).catch(() => {}); }); };

  if (!car) {
    return (
      <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
        <SkyHeader title="Buy this version" back={() => router.back()} />
        <View style={[sheet.page, { padding: PAD }]}><Text style={s.body}>This car isn’t here any more.</Text></View>
      </SafeAreaView>
    );
  }
  const p = priceFor(car, year);
  const pay = p ? paymentFor(loanOf(answers), p.amount, p.isNew) : undefined;
  const o = p ? otdLines(p.amount) : undefined;
  const g = GUIDE[car.id];
  const ask = [...(g?.ask ?? []), ...COMMON_ASK];
  const label = `${car.make} ${car.model}${trim ? ` ${trim}` : ''}`;
  const n = done.length;
  const next = STEPS.find((x) => !done.includes(x));

  const go = (id: StepId) => {
    tap(); mark(id);
    if (id === 'shop') router.push({ pathname: '/shop', params: { ids: car.id, ...(trim ? { trim } : {}) } });
    else if (id === 'check') router.push('/check');
    else setOpen(open === id ? null : id);
  };

  const row = (key: string, v: string, bold?: boolean) => (
    <View style={s.row}>
      <Text style={[s.body, { flex: 1 }, bold && { fontFamily: F.bodyBold }]}>{key}</Text>
      <Text style={[s.body, bold && { fontFamily: F.bodyBold }]}>{v}</Text>
    </View>
  );
  const stop = (id: StepId, title: string, sub: string, link: string, children?: React.ReactNode) => {
    const ok = done.includes(id);
    const i = STEPS.indexOf(id) + 2;
    return (
      <View style={s.stopWrap}>
        <View style={[s.pin, ok && s.pinDone]}><Text style={s.pinT}>{ok ? '✓' : String(i)}</Text></View>
        <Pressable onPress={() => go(id)} accessibilityRole="button" accessibilityState={{ checked: ok }}
          accessibilityLabel={`${tr(title)}. ${ok ? tr('Done') : ''}`} style={[s.stop, next === id && s.stopNow]}>
          <Text style={s.stopT}>{title}</Text>
          <Text style={s.small}>{sub}</Text>
          <Text style={s.link}>{link}</Text>
          {children}
        </Pressable>
      </View>
    );
  };

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Buy this version" back={() => router.back()} />
      <ScrollView style={sheet.page} contentContainerStyle={{ padding: PAD, paddingBottom: 110 }}>
        <Text style={s.title}>{`Your road to the ${label}`}</Text>
        <Text style={s.small}>{[String(year), pay != null ? `≈ ${money(pay)}/mo est.` : null, o?.state].filter(Boolean).join(' · ')}</Text>
        <View style={s.prog}><View style={[s.progIn, { width: `${((n + 1) / (STEPS.length + 1)) * 100}%` }]} /></View>
        <Text style={[s.small, { marginTop: 4 }]}>{`${n + 1} of ${STEPS.length + 1} done`}</Text>

        <View style={s.road}>
          <View style={s.line} />
          <View style={s.stopWrap}>
            <View style={[s.pin, s.pinDone]}><Text style={s.pinT}>✓</Text></View>
            <View style={s.stop}><Text style={s.stopT}>Picked your version</Text><Text style={s.small}>{label}</Text></View>
          </View>
          {stop('shop', `See ${trim || car.model} cars for sale near you`, 'Map, closest first, fair-price tag on each', 'Open the map ›')}
          {stop('otd', 'Know your out-the-door price', o ? `${money(o.price)} + ${o.state ?? 'state'} tax + fees ≈ ${money(o.total)} est.` : 'Price + tax + fees', open === 'otd' ? 'Hide the math ⌃' : 'See the math ›', (<>
            {open === 'otd' && o && (
              <View style={s.math}>
                {row(p?.isNew ? 'Price (new, starting)' : 'Price (used, est.)', money(o.price))}
                {row(`${o.taxName}${o.state ? ` · ${o.state}` : ''}`, money(o.tax))}
                {row('Dealer and title fees, about', money(o.fees))}
                {row('Out the door, est.', money(o.total), true)}
              </View>
            )}
          </>))}
          {stop('check', 'Check the car at the lot', 'Scan or type the VIN: recalls and a fair price', 'Check a car ›')}
          {stop('ask', 'Ask the dealer these questions', `For the ${label}, ready on your phone`, open === 'ask' ? 'Hide the questions ⌃' : 'Show the questions ›', (<>
            {open === 'ask' && (
              <View style={s.math}>
                {ask.map((x, i) => <Text key={x[0]} style={[s.body, { marginTop: i ? 6 : 0 }]}>{`${i + 1}. `}<Text style={s.body}>{x[0]}</Text></Text>)}
              </View>
            )}
          </>))}
          <View style={[s.stopWrap, { opacity: 0.5 }]}>
            <View style={[s.pin, { backgroundColor: '#9AA3AF' }]}><Text style={s.pinT}>$</Text></View>
            <View style={s.stop}><Text style={s.stopT}>Credit union loan</Text><Text style={s.small}>Coming after our partners sign up</Text></View>
          </View>
        </View>
        {n > 0 && (
          <Pressable onPress={restart} accessibilityRole="button" hitSlop={8} style={{ alignSelf: 'center', marginTop: 6 }}>
            <Text style={[s.link, { color: C.muted }]}>Start this road over</Text>
          </Pressable>
        )}
        <Text style={[s.small, { marginTop: 12 }]}>Prices and payments are estimates, not an offer. Nothing is bought in the app.</Text>
      </ScrollView>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  title: { fontFamily: F.head, fontSize: 21, color: C.ink },
  body: { fontFamily: F.body, fontSize: 14, lineHeight: 20, color: C.ink },
  small: { fontFamily: F.body, fontSize: 12.5, lineHeight: 17, color: C.muted, marginTop: 2 },
  prog: { height: 8, borderRadius: 9, backgroundColor: C.grey, marginTop: 12, overflow: 'hidden' },
  progIn: { height: '100%', borderRadius: 9, backgroundColor: '#1F6E4E' },
  road: { marginTop: 16, paddingLeft: 46 },
  line: { position: 'absolute', left: 16, top: 10, bottom: 10, width: 8, borderRadius: 9, backgroundColor: isDarkLook(look) ? '#4A4F58' : '#3A3F48' },
  stopWrap: { marginBottom: 12 },
  pin: { position: 'absolute', left: -42, top: 10, width: 30, height: 30, borderRadius: 15, backgroundColor: '#86652B', alignItems: 'center', justifyContent: 'center', borderWidth: 3, borderColor: C.bg, zIndex: 2 },
  pinDone: { backgroundColor: '#1F6E4E' },
  pinT: { fontFamily: F.bodyBold, fontSize: 12.5, color: '#fff' },
  stop: { backgroundColor: C.card, borderRadius: 16, padding: 12, borderWidth: 1, borderColor: C.line },
  stopNow: { borderWidth: 2, borderColor: isDarkLook(look) ? '#9CC0F7' : '#1F5FBF' },
  stopT: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  link: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent, marginTop: 6 },
  math: { marginTop: 10, paddingTop: 10, borderTopWidth: 1, borderTopColor: C.line, gap: 4 },
  row: { flexDirection: 'row', gap: 8 },
}));
