// Things we keep on the phone between visits: saved cars and the user's own car.
// Kept on the phone; a free account also keeps a copy (state/alerts.tsx).
import type { LogEntry } from '@/data/car-log';
import type { CarReminder } from '@/data/car-reminders';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { countCar } from '@/data/popular';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import type { Dealer } from '@/data/dealers';
import type { Loan, Service } from '@/data/car-plan';
import type { ThemeName } from '@/theme';
import { activeOf, addTo, fromStored, type Garage, removeAt, replaceActive } from '@/data/my-cars';

export type SavedCar = { id: string; year: number; at: number };
// seenLogin: the user got past the login screen once, so the opening goes straight Home next time.
export type Prefs = { readAloud: boolean; seenLogin?: boolean; sound?: boolean; theme?: ThemeName; lang?: 'en' | 'es'; lookV?: number; sky?: 'time' | 'sunset'; autoNight?: boolean; forYouSeen?: string; skyWeather?: boolean; avatar?: string; zipAsked?: boolean }; // avatar: 'photo', 'letter' or a picture id (data/avatars.ts) // forYouSeen: the day For you was last opened (its red dot)
// nick: 'Mom's car'; milesAt: when the miles were last typed (for 'Update your miles').
// My car plan (picture 167, Oct 30, 2026): loan = what they typed about their loan (never an account number);
// services = their service history; daily = usual miles a day for the miles estimate; checkMiles = the monthly
// 'Is your mileage about …?' alert; insurer + insured = the insurance step (their own company, we send nothing).
export type MyCar = { year: number; make: string; model: string; miles?: number; milesAt?: number; regDue?: string; lastOil?: number; dealer?: Dealer; color?: string; nick?: string;
  loan?: Loan; services?: Service[]; daily?: number; checkMiles?: boolean; insurer?: string; roadside?: string; insured?: boolean; vin?: string; boughtOn?: string; valueTips?: boolean; insureRemind?: boolean; owned?: boolean; dailyMin?: number; workdays?: boolean; reminders?: CarReminder[]; log?: LogEntry[] }; // owned: no loan, the car is paid off (a lease is a loan with kind 'lease'). dailyMin: their drive in minutes a day (daily = miles). workdays: drives 5 days a week

type Ctx = {
  saved: SavedCar[];
  isSaved: (id: string, year: number) => boolean;
  toggleSaved: (id: string, year: number) => void;
  addSaved: (list: { id: string; year: number }[]) => void; // brings back a member's saved cars on a new phone
  recent: SavedCar[]; // "You looked at" on Home: the last car pages opened, newest first
  addRecent: (id: string, year: number) => void;
  clearRecent: () => void;
  myCar: MyCar | null; // the car open in My Garage
  setMyCar: (c: MyCar | null) => void; // changes the open car (null deletes it)
  myCars: MyCar[]; // every car the user owns (picture 128 A), up to 5
  activeCar: number;
  pickCar: (i: number) => void;
  addCar: (c: MyCar) => void;
  removeCar: (i: number) => void;
  setMyCars: (cars: MyCar[]) => void; // brings back a member's cars on a new phone
  setCarMiles: (i: number, miles: number) => void; // the miles of any car in My Garage (the VIN scanner's miles box)
  comparing: { id: string; year: number }[]; // "Compare" on the big cards (picture 129), up to 3, this visit only
  toggleCompare: (id: string, year: number) => void;
  clearCompare: () => void;
  prefs: Prefs;
  setPrefs: (p: Prefs) => void;
  ready: boolean;
};
const SavedCtx = createContext<Ctx | null>(null);
const KEY = 'carvessa:v1';

export function SavedProvider({ children }: { children: React.ReactNode }) {
  const [saved, setSaved] = useState<SavedCar[]>([]);
  const [garage, setGarage] = useState<Garage>({ cars: [], active: 0 });
  const [prefs, setPrefs] = useState<Prefs>({ readAloud: false });
  const [recent, setRecent] = useState<SavedCar[]>([]);
  const [ready, setReady] = useState(false);
  const [comparing, setComparing] = useState<{ id: string; year: number }[]>([]);

  useEffect(() => {
    AsyncStorage.getItem(KEY)
      .then((raw) => {
        if (!raw) return;
        const d = JSON.parse(raw);
        if (Array.isArray(d.saved)) setSaved(d.saved);
        setGarage(fromStored(d));
        if (d.prefs) setPrefs(d.prefs);
        if (Array.isArray(d.recent)) setRecent(d.recent);
      })
      .catch(() => {})
      .finally(() => setReady(true));
  }, []);
  useEffect(() => {
    if (ready) AsyncStorage.setItem(KEY, JSON.stringify({ saved, myCars: garage.cars, activeCar: garage.active, prefs, recent })).catch(() => {});
  }, [saved, garage, prefs, recent, ready]);

  const isSaved = useCallback((id: string, year: number) => saved.some((x) => x.id === id && x.year === year), [saved]);
  const toggleSaved = useCallback((id: string, year: number) => {
    setSaved((cur) => {
      if (cur.some((x) => x.id === id && x.year === year)) return cur.filter((x) => !(x.id === id && x.year === year));
      countCar(id, 'save'); // Popular in your area (data/popular.ts)
      return [{ id, year, at: Date.now() }, ...cur];
    });
  }, []);
  const addSaved = useCallback((list: { id: string; year: number }[]) => {
    setSaved((cur) => [...cur, ...list.filter((n) => !cur.some((x) => x.id === n.id && x.year === n.year)).map((n) => ({ ...n, at: Date.now() }))]);
  }, []);
  // One entry per car (the last year looked at), at most 10.
  const addRecent = useCallback((id: string, year: number) => {
    countCar(id, 'view');
    setRecent((cur) => (cur[0]?.id === id && cur[0]?.year === year ? cur : [{ id, year, at: Date.now() }, ...cur.filter((x) => x.id !== id)].slice(0, 10)));
  }, []);
  const clearRecent = useCallback(() => setRecent([]), []);
  const myCar = activeOf(garage);
  // When the miles change, remember the day (for "Update your miles · Last updated …").
  const stamp = (c: MyCar, was: MyCar | null): MyCar => (c.miles && c.miles !== was?.miles ? { ...c, milesAt: Date.now() } : c);
  const setMyCar = useCallback((c: MyCar | null) => setGarage((g) => (c ? replaceActive(g, stamp(c, activeOf(g))) : removeAt(g, g.active))), []);
  const pickCar = useCallback((i: number) => setGarage((g) => (i >= 0 && i < g.cars.length ? { ...g, active: i } : g)), []);
  const addCar = useCallback((c: MyCar) => setGarage((g) => addTo(g, stamp(c, null))), []);
  const removeCar = useCallback((i: number) => setGarage((g) => removeAt(g, i)), []);
  const setCarMiles = useCallback((i: number, miles: number) => setGarage((g) => (g.cars[i] && g.cars[i].miles !== miles
    ? { ...g, cars: g.cars.map((c, k) => (k === i ? stamp({ ...c, miles }, c) : c)) } : g)), []);
  // A 4th car pushes out the first one picked.
  const toggleCompare = useCallback((id: string, year: number) => {
    setComparing((cur) => {
      if (cur.some((x) => x.id === id)) return cur.filter((x) => x.id !== id);
      countCar(id, 'compare');
      return [...cur, { id, year }].slice(-3);
    });
  }, []);
  const clearCompare = useCallback(() => setComparing([]), []);
  const setMyCars = useCallback((cars: MyCar[]) => setGarage(fromStored({ myCars: cars })), []);
  const value = useMemo(() => ({ saved, isSaved, toggleSaved, addSaved, recent, addRecent, clearRecent, myCar, setMyCar, myCars: garage.cars, activeCar: garage.active, pickCar, addCar, removeCar, setMyCars, setCarMiles, comparing, toggleCompare, clearCompare, prefs, setPrefs, ready }),
    [saved, isSaved, toggleSaved, addSaved, recent, addRecent, clearRecent, myCar, setMyCar, garage, pickCar, addCar, removeCar, setMyCars, setCarMiles, comparing, toggleCompare, clearCompare, prefs, ready]);
  return <SavedCtx.Provider value={value}>{children}</SavedCtx.Provider>;
}

export function useSaved() {
  const c = useContext(SavedCtx);
  if (!c) throw new Error('useSaved must be inside SavedProvider');
  return c;
}
