// Fair price, in motion (picture 138, approved Nov 1, 2026: "build it like the demo").
// FairBar: Low / Fair price / High zones, the fair range numbers where green starts and ends, and a price
// flag that slides in. VerdictChip: "✓ Looks fair" style chip that pops in. PriceGauge: the half-circle
// gauge on Check a car. Each plays once per price per app visit; Reduce Motion shows the finished picture.
import { useEffect, useRef, useState } from 'react';
import { AccessibilityInfo, Animated, Dimensions, Easing, StyleSheet, View, type LayoutChangeEvent } from 'react-native';
import Svg, { Path, Text as SvgText } from 'react-native-svg';

import { Text } from '@/components/t';
import { tap } from '@/components/ui';
import type { Verdict } from '@/data/fair-price';
import { money } from '@/data/prices';
import { tr } from '@/i18n';
import { C, F, theme, themed } from '@/theme';

/** Amber for "Looks low" (readable on white and on the night cards). */
export const amber = () => (theme === 'midnight' ? '#F2B45A' : '#A15F00');
export const verdictColor = (v: Verdict) => (v === 'low' ? amber() : v === 'high' ? C.red : C.green);

const CHIP: Record<Verdict, [string, string]> = { low: ['!', 'Looks low · ask why'], fair: ['✓', 'Looks fair'], high: ['↑', 'Looks high'] };

// Played once per key this visit (scrolling back or re-rendering doesn't replay it).
const played = new Set<string>();

function useStill() {
  const [still, setStill] = useState<boolean | null>(null);
  useEffect(() => {
    let on = true;
    AccessibilityInfo.isReduceMotionEnabled().then((r) => on && setStill(r)).catch(() => on && setStill(false));
    return () => { on = false; };
  }, []);
  return still;
}

/** Waits until the view is on screen (checks a few times a second; stops once it's seen). */
function useOnScreen(ref: React.RefObject<View | null>) {
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    if (seen) return;
    const id = setInterval(() => {
      ref.current?.measureInWindow((_x, y, _w, h) => {
        const H = Dimensions.get('window').height;
        if (h > 0 && y < H - 90 && y + h > 60) setSeen(true);
      });
    }, 200);
    return () => clearInterval(id);
  }, [ref, seen]);
  return seen;
}

/** Plays only the first time this key shows up on screen; null = not yet (still deciding or not on screen). */
function usePlay(key: string, ref: React.RefObject<View | null>) {
  const still = useStill();
  const seen = useOnScreen(ref);
  const [first] = useState(() => !played.has(key));
  useEffect(() => { if (still !== null && (seen || still)) played.add(key); }, [key, still, seen]);
  if (still === null) return null;
  if (still || !first) return false;
  return seen ? true : null;
}

const springBack = (t: number) => { const c1 = 1.70158, c3 = c1 + 1; return 1 + c3 * (t - 1) ** 3 + c1 * (t - 1) ** 2; };
const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);

export function VerdictChip({ tag, playKey }: { tag: Verdict; playKey?: string }) {
  const box = useRef<View>(null);
  const play = usePlay(`chip:${playKey ?? tag}`, box);
  const [s] = useState(() => new Animated.Value(1));
  const [o] = useState(() => new Animated.Value(1));
  useEffect(() => {
    if (play === null) { s.setValue(0.6); o.setValue(0); return; }
    if (!play) { s.setValue(1); o.setValue(1); return; }
    s.setValue(0.6); o.setValue(0);
    Animated.parallel([
      Animated.timing(s, { toValue: 1, duration: 420, delay: 1150, easing: BACK, useNativeDriver: true }),
      Animated.timing(o, { toValue: 1, duration: 200, delay: 1150, useNativeDriver: true }),
    ]).start();
  }, [play, s, o]);
  const c = verdictColor(tag);
  const [icon, words] = CHIP[tag];
  return (
    <View ref={box} collapsable={false} style={{ alignSelf: 'flex-start' }}><Animated.View style={[st.chip, { backgroundColor: c + '22', opacity: o, transform: [{ scale: s }] }]} accessible accessibilityLabel={tr(words)}>
      <Text style={[st.chipText, { color: c }]}>{icon}</Text>
      <Text style={[st.chipText, { color: c }]}>{words}</Text>
    </Animated.View></View>
  );
}

/** The bar: amber Low, green Fair price, red High. `at` is the price on the flag. */
export function FairBar({ range: [lo, hi], at, playKey }: { range: [number, number]; at: number; playKey?: string }) {
  const min = lo * 0.8, max = hi * 1.2;
  const pct = (n: number) => Math.max(1.5, Math.min(98.5, ((n - min) / (max - min)) * 100));
  const a = pct(lo), b = pct(hi), p = pct(at);
  const box = useRef<View>(null);
  const play = usePlay(`bar:${playKey ?? `${lo}-${hi}-${at}`}`, box);
  const [w, setW] = useState(0);
  const [cover] = useState(() => new Animated.Value(0)); // 0 = hidden bar, 1 = full bar
  const [flag] = useState(() => new Animated.Value(1)); // 0 = left edge, 1 = at the price
  const [ring] = useState(() => new Animated.Value(1)); // the "light tap" ring
  const [glow] = useState(() => new Animated.Value(0));
  const fair = at >= lo * 0.95 && at <= hi * 1.05;

  useEffect(() => {
    if (!w) return;
    if (play === null) { cover.setValue(0); flag.setValue(0); ring.setValue(1); glow.setValue(0); return; }
    if (!play) { cover.setValue(1); flag.setValue(1); ring.setValue(1); glow.setValue(fair ? 0.18 : 0); return; }
    cover.setValue(0); flag.setValue(0); ring.setValue(1); glow.setValue(0);
    Animated.timing(cover, { toValue: 1, duration: 650, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start();
    Animated.timing(flag, { toValue: 1, duration: 800, delay: 350, easing: (t) => springBack(t), useNativeDriver: true }).start(({ finished }) => {
      if (!finished) return;
      tap();
      ring.setValue(0);
      Animated.timing(ring, { toValue: 1, duration: 520, useNativeDriver: true }).start();
      if (fair) Animated.sequence([
        Animated.timing(glow, { toValue: 0.4, duration: 360, useNativeDriver: true }),
        Animated.timing(glow, { toValue: 0.18, duration: 540, useNativeDriver: true }),
      ]).start();
    });
  }, [play, w, cover, flag, ring, glow, fair]);

  const onLayout = (e: LayoutChangeEvent) => setW(e.nativeEvent.layout.width);
  const x = (w * p) / 100;
  return (
    <View ref={box} collapsable={false} style={st.meter} onLayout={onLayout} accessible accessibilityLabel={`${tr('Fair price for this car:')} ${money(lo)} – ${money(hi)}. ${money(at)}.`}>
      {w > 0 && (
        <Animated.View pointerEvents="none" style={[st.glow, { left: (w * a) / 100, width: (w * (b - a)) / 100, backgroundColor: C.green, opacity: glow }]} />
      )}
      <View style={st.track}>
        <View style={[st.zone, { width: `${a}%`, backgroundColor: amber(), borderTopLeftRadius: 99, borderBottomLeftRadius: 99 }]} />
        <View style={[st.zone, { width: `${b - a}%`, backgroundColor: C.green, marginHorizontal: 3 }]} />
        <View style={[st.zone, { flex: 1, backgroundColor: C.red, borderTopRightRadius: 99, borderBottomRightRadius: 99 }]} />
        {/* A cover in the card color slides right to "fill" the bar from left to right. */}
        {w > 0 && <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { backgroundColor: C.card, transform: [{ translateX: cover.interpolate({ inputRange: [0, 1], outputRange: [0, w] }) }] }]} />}
      </View>
      {w > 0 && (
        <>
          <Animated.View pointerEvents="none" style={[st.ring, { borderColor: C.ink, left: x - 5, opacity: ring.interpolate({ inputRange: [0, 1], outputRange: [0.7, 0] }), transform: [{ scale: ring.interpolate({ inputRange: [0, 1], outputRange: [1, 4.2] }) }] }]} />
          <Animated.View pointerEvents="none" style={[st.flag, { opacity: flag.interpolate({ inputRange: [0, 0.25, 1], outputRange: [0, 1, 1], extrapolate: 'clamp' }), transform: [{ translateX: flag.interpolate({ inputRange: [0, 1], outputRange: [-40, x - 40] }) }] }]}>
            <View style={[st.flagBox, { backgroundColor: C.ink }]}><Text style={[st.flagText, { color: C.card }]}>{money(at)}</Text></View>
            <View style={[st.flagTip, { borderTopColor: C.ink }]} />
            <View style={[st.flagPole, { backgroundColor: C.ink }]} />
          </Animated.View>
        </>
      )}
      <View style={st.zones}>
        <Text style={[st.zoneText, { width: `${a}%`, color: amber() }]} numberOfLines={1}>Low</Text>
        <Text style={[st.zoneText, { width: `${b - a}%`, color: C.green }]} numberOfLines={1}>Fair price</Text>
        <Text style={[st.zoneText, { flex: 1, color: C.red }]} numberOfLines={1}>High</Text>
      </View>
      {w > 0 && (
        <View style={st.ends}>
          <Text style={[st.end, { left: (w * a) / 100 - 40 }]}>{money(lo)}</Text>
          <Text style={[st.end, { left: (w * b) / 100 - 40 }]}>{money(hi)}</Text>
        </View>
      )}
    </View>
  );
}

// ---------- Check a car gauge ----------
const R = 80, CX = 100, CY = 100;
const pt = (deg: number, r = R) => { const t = ((deg - 90) * Math.PI) / 180; return [CX + r * Math.cos(t), CY + r * Math.sin(t)]; };
const arc = (d1: number, d2: number) => { const [x1, y1] = pt(d1), [x2, y2] = pt(d2); return `M${x1.toFixed(1)} ${y1.toFixed(1)} A${R} ${R} 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}`; };
const len = (d1: number, d2: number) => (R * Math.abs(d2 - d1) * Math.PI) / 180;
const AnimatedPath = Animated.createAnimatedComponent(Path);

/** Half-circle gauge: amber low, green fair, red high; the needle points at the asking price. */
export function PriceGauge({ range: [lo, hi], at, tag, playKey }: { range: [number, number]; at: number; tag: Verdict; playKey?: string }) {
  const min = lo * 0.8, max = hi * 1.2;
  const ang = (n: number) => -90 + Math.max(0, Math.min(1, (n - min) / (max - min))) * 180;
  const A = ang(lo), B = ang(hi), to = ang(at), gap = 2.2;
  const segs: [number, number, string, boolean][] = [[-90, A - gap, amber(), true], [A + gap, B - gap, C.green, false], [B + gap, 90, C.red, true]];
  const box = useRef<View>(null);
  const play = usePlay(`gauge:${playKey ?? `${lo}-${hi}-${at}`}`, box);
  const [draw] = useState(() => new Animated.Value(1));
  const [needle] = useState(() => new Animated.Value(to));
  const [word] = useState(() => new Animated.Value(1));
  const [shown, setShown] = useState(0); // counts up while the needle moves

  useEffect(() => {
    if (play === null) { draw.setValue(0); needle.setValue(-90); word.setValue(0); return; }
    if (!play) { draw.setValue(1); needle.setValue(to); word.setValue(1); return; }
    draw.setValue(0); needle.setValue(-90); word.setValue(0);
    Animated.timing(draw, { toValue: 1, duration: 700, easing: Easing.out(Easing.cubic), useNativeDriver: false }).start();
    // Needle: a spring that goes a little past the price and settles, like a real gauge.
    const sweep = new Animated.Value(0);
    const id = sweep.addListener(({ value }) => setShown(Math.round(at * Math.min(1, value * 1.4))));
    Animated.timing(sweep, { toValue: 1, duration: 1200, delay: 500, easing: Easing.linear, useNativeDriver: true }).start(() => { sweep.removeListener(id); setShown(at); });
    needle.setValue(-90);
    Animated.spring(needle, { toValue: to, delay: 500, friction: 5, tension: 38, useNativeDriver: true }).start();
    Animated.timing(word, { toValue: 1, duration: 380, delay: 1500, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start();
    return () => sweep.removeListener(id);
  }, [play, draw, needle, word, to, at]);

  const c = verdictColor(tag);
  const words = tag === 'low' ? 'Looks low' : tag === 'high' ? 'Looks high' : 'Looks fair';
  const [lx, ly] = pt(A, R + 24), [hx, hy] = pt(B, R + 24);
  return (
    <View ref={box} collapsable={false} style={st.gauge} accessible accessibilityLabel={`${tr(words)}. ${tr('Fair price for this car:')} ${money(lo)} – ${money(hi)}. ${money(at)}.`}>
      <View style={st.dial}>
        <Svg width="100%" height="100%" viewBox="-14 -10 228 128">
          {segs.map(([d1, d2, color, round], i) => {
            const L = len(d1, d2);
            const k = draw.interpolate({ inputRange: [i / 3, (i + 1) / 3], outputRange: [L, 0], extrapolate: 'clamp' });
            return <AnimatedPath key={i} d={arc(d1, d2)} stroke={color} strokeWidth={16} fill="none" strokeLinecap={round ? 'round' : 'butt'} strokeDasharray={`${L} ${L}`} strokeDashoffset={k} />;
          })}
          <SvgText x={lx} y={ly} fontSize={10} fontFamily={F.bodyBold} textAnchor="middle" fill={C.muted}>{money(lo)}</SvgText>
          <SvgText x={hx} y={hy} fontSize={10} fontFamily={F.bodyBold} textAnchor="middle" fill={C.muted}>{money(hi)}</SvgText>
        </Svg>
        {/* Needle: a box centered on the pivot, so rotating it turns the needle around the pivot. */}
        <Animated.View pointerEvents="none" style={[st.needleBox, { transform: [{ rotate: needle.interpolate({ inputRange: [-180, 180], outputRange: ['-180deg', '180deg'] }) }] }]}>
          <View style={[st.needle, { backgroundColor: C.ink }]} />
        </Animated.View>
        <View style={[st.hub, { backgroundColor: C.ink }]}><View style={[st.hubDot, { backgroundColor: C.card }]} /></View>
      </View>
      <Animated.View style={{ opacity: word, transform: [{ translateY: word.interpolate({ inputRange: [0, 1], outputRange: [6, 0] }) }], alignItems: 'center' }}>
        <Text style={[st.verdict, { color: c }]}>{words}</Text>
      </Animated.View>
      <View style={st.rangeRow}>
        <Text style={st.small}>Fair price for this car:</Text>
        <Text style={[st.small, { fontFamily: F.bodyBold, color: C.ink }]}>{`${money(lo)} – ${money(hi)}`}</Text>
      </View>
      <View style={st.asked}>
        <Text style={st.askedK}>Price they’re asking</Text>
        <Text style={st.askedV}>{money(play ? shown : at)}</Text>
      </View>
    </View>
  );
}

// Gauge geometry: the svg viewBox is 228 x 128 with the pivot at (114, 110) of it.
const DIAL_W = 250, DIAL_H = (DIAL_W * 128) / 228;
const PX = (DIAL_W * 114) / 228, PY = (DIAL_H * 110) / 128, NEEDLE = (DIAL_W * 70) / 228;

const st = themed(() => StyleSheet.create({
  chip: { flexDirection: 'row', alignItems: 'center', gap: 6, alignSelf: 'flex-start', borderRadius: 99, paddingHorizontal: 12, paddingVertical: 6, marginTop: 10 },
  chipText: { fontFamily: F.head, fontSize: 13.5 },
  meter: { marginTop: 44 },
  glow: { position: 'absolute', top: -5, height: 22, borderRadius: 99 },
  track: { height: 12, borderRadius: 99, overflow: 'hidden', flexDirection: 'row' },
  zone: { height: '100%' },
  ring: { position: 'absolute', top: 1, width: 10, height: 10, borderRadius: 5, borderWidth: 2 },
  flag: { position: 'absolute', top: -40, left: 0, width: 80, alignItems: 'center' },
  flagBox: { borderRadius: 9, paddingHorizontal: 9, paddingVertical: 3 },
  flagText: { fontFamily: F.head, fontSize: 12, fontVariant: ['tabular-nums'] },
  flagTip: { width: 0, height: 0, borderLeftWidth: 5, borderRightWidth: 5, borderTopWidth: 5, borderLeftColor: 'transparent', borderRightColor: 'transparent' },
  flagPole: { width: 3, height: 24, borderRadius: 2, marginTop: -1 },
  zones: { flexDirection: 'row', marginTop: 7 },
  zoneText: { fontFamily: F.head, fontSize: 11.5, textAlign: 'center' },
  ends: { height: 16, marginTop: 1 },
  end: { position: 'absolute', width: 80, textAlign: 'center', fontSize: 11, color: C.muted, fontFamily: F.body, fontVariant: ['tabular-nums'] },
  gauge: { alignItems: 'center', marginTop: 6 },
  dial: { width: DIAL_W, height: DIAL_H },
  needleBox: { position: 'absolute', left: PX - NEEDLE, top: PY - NEEDLE, width: NEEDLE * 2, height: NEEDLE * 2, alignItems: 'center' },
  needle: { width: 5, height: NEEDLE, borderRadius: 3 },
  hub: { position: 'absolute', left: PX - 9, top: PY - 9, width: 18, height: 18, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },
  hubDot: { width: 7, height: 7, borderRadius: 4 },
  verdict: { fontFamily: F.head, fontSize: 24, marginTop: -2 },
  rangeRow: { flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', gap: 4, marginTop: 2 },
  small: { fontSize: 12, color: C.muted, fontFamily: F.body },
  asked: { alignSelf: 'stretch', flexDirection: 'row', justifyContent: 'space-between', borderTopWidth: 1, borderTopColor: C.line, marginTop: 12, paddingTop: 10 },
  askedK: { fontSize: 13, color: C.ink, fontFamily: F.body },
  askedV: { fontSize: 13, color: C.ink, fontFamily: F.bodyBold, fontVariant: ['tabular-nums'] },
}));
