// One price rule for the whole app (picture 72 A, picked Oct 16, 2026).
// Our price estimate is the "fair price" guide. Any real asking price (a car for sale near you, or a
// car someone checks) gets the same tag: Looks low, Looks fair or Looks high. Same math as "Check a car".
// Out-the-door = price + the shopper's state car tax + about the state's dealer and title fees. All ESTIMATES.
import { estimateRange, verdictFor, type Verdict } from '@/data/check';
import { CARS, type Car } from '@/data/cars';
import { outTheDoor } from '@/data/afford';
import { carFees, carTax, costsFor, homeState, STATES } from '@/data/state-costs';
import type { Listing } from '@/data/listings';

export type { Verdict };

export const fairRange = estimateRange;
export const priceTag = verdictFor;

/** The out-the-door estimate, line by line, for the shopper's state (or typical U.S. numbers). */
export function otdLines(price: number, st: string | null = homeState()) {
  const c = costsFor(st);
  const tax = carTax(price, st), fees = carFees(st);
  return { price, tax, fees, total: outTheDoor(price, st), state: st && STATES[st] ? c.name : null, taxName: c.taxName, rate: c.tax, cap: c.cap };
}

const norm = (s: string) => s.toLowerCase().replace(/chevrolet/, 'chevy').replace(/[^a-z0-9]/g, '');
/** Our car for a dealer listing ("Chevrolet Equinox" → our Chevy Equinox), if we have it. */
export function carForListing(l: Pick<Listing, 'make' | 'model'>): Car | undefined {
  const make = norm(l.make), model = norm(l.model);
  return CARS.find((c) => norm(c.make) === make && model.startsWith(norm(c.model)));
}

/** The fair range and tag for a car for sale, or nothing when we have no estimate for it. */
export function listingTag(l: Pick<Listing, 'make' | 'model' | 'year' | 'price' | 'miles'>): { range: [number, number]; tag: Verdict } | undefined {
  const car = carForListing(l);
  const range = car ? fairRange(car, l.year, l.miles ?? undefined) : undefined;
  return range ? { range, tag: priceTag(l.price, range) } : undefined;
}
