import { Alert, Platform } from 'react-native';

import { tr } from '@/i18n';

type Listener = (title: string, msg: string) => void;
let listener: Listener | null = null;
export const onNotify = (l: Listener | null) => { listener = l; };

// Phones show a normal pop-up. The web version shows an in-app message instead.
export function notify(title: string, msg: string) {
  title = tr(title);
  msg = tr(msg);
  if (Platform.OS === 'web' && listener) listener(title, msg);
  else Alert.alert(title, msg);
}

export const soon = (what: string) => notify('Coming soon', `${what} is coming in the next build.`);
