// Pull down to refresh (Oct 26, 2026, Loudjier: 'add a refresh when the user pull the page down … that will get new info').
// One app-wide "refresh tick": pulling down on a screen clears the saved answers (recalls, owner reports, weather, the car
// you scanned) and bumps the tick; anything that loads data lists the tick in its effect, so it loads again.
import { useSyncExternalStore } from 'react';

let tick = 0;
const subs = new Set<() => void>();
const clearers = new Set<() => void>();

/** Data files register how to forget what they saved, so a pull gets fresh answers. */
export function onPullClear(fn: () => void) { clearers.add(fn); }

export function pullRefresh() {
  clearers.forEach((f) => { try { f(); } catch { /* keep going */ } });
  tick++;
  subs.forEach((f) => f());
}

const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };
/** Changes every time someone pulls down to refresh. */
export const useRefreshTick = () => useSyncExternalStore(subscribe, () => tick, () => tick);
