// Weather for the Home scene. Uses the ZIP the user gave the coach.
// No ZIP yet (or no internet): a clear sky that follows the phone's clock.
import { useEffect, useState } from 'react';

import { zipToPlace } from '@/data/dealers';
import { fallbackWeather, getWeather, type Weather } from '@/data/weather';

type Live = { zip: string; w: Weather; place: string };

export function useWeather(zip: string) {
  const [live, setLive] = useState<Live | null>(null);
  const [fallback] = useState(() => fallbackWeather());
  useEffect(() => {
    if (!/^\d{5}$/.test(zip)) return;
    let on = true;
    zipToPlace(zip)
      .then((p) => getWeather(p.lat, p.lon).then((w) => ({ zip, w, place: p.place })))
      .then((r) => { if (on) setLive(r); })
      .catch(() => {});
    return () => { on = false; };
  }, [zip]);
  const ok = live && live.zip === zip ? live : null;
  return { weather: ok?.w ?? fallback, place: ok?.place ?? '', live: !!ok };
}
