// What your car is worth (picture 167 screens 6–7, Oct 30, 2026): a trade-in range for their car's year and miles,
// what they still owe (from My loan), the difference, and upgrade ideas of the same kind of car.
// All ESTIMATES. "No rush" is a fine answer: honest advice builds trust. Our picks, not ads.
import { router } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BigBtn, Card, ToggleRow } from '@/components/account-ui';
import { CarThumb } from '@/components/car-photo';
import { BellIcon } from '@/components/icons';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { Body, Label, tap } from '@/components/ui';
import { balanceLeft, estMiles, tradeRange, upgradeIdeas } from '@/data/car-plan';
import { carForMine } from '@/data/cars';
import { carName } from '@/data/my-cars';
import { monthlyCap, useAnswers } from '@/state/answers';
import { useAuth } from '@/state/auth';
import { useSaved } from '@/state/saved';
import { C, calm, F, PAD, themed } from '@/theme';

const usd = (n: number) => `${n < 0 ? '−' : ''}$${Math.abs(Math.round(n)).toLocaleString('en-US')}`;
const signed = (n: number) => (n > 0 ? `+${usd(n)}` : usd(n));

export default function ValueScreen() {
  const { myCar, setMyCar } = useSaved();
  const { answers } = useAnswers();
  const { session, askAccount } = useAuth();
  const [now] = useState(() => Date.now());
  const back = () => router.navigate('/garage');
  const mine = myCar ? carForMine(myCar.make, myCar.model) : undefined;
  const miles = myCar ? estMiles(myCar, now) ?? undefined : undefined;
  const range = mine && myCar ? tradeRange(mine, myCar.year, miles) : null;
  const leased = myCar?.loan?.kind === 'lease';
  const owed = myCar?.loan?.left && !leased ? balanceLeft(myCar.loan) : 0;
  const lo = range ? range[0] - owed : 0;
  const hi = range ? range[1] - owed : 0;
  const mid = (lo + hi) / 2;
  const plan = monthlyCap(answers) ?? myCar?.loan?.payment;
  const ideas = mine && myCar && range ? upgradeIdeas(mine, myCar.year, mid, myCar.loan?.apr, plan) : [];
  const meaning = !range ? '' : leased ? 'Leased: the leasing company owns the car. At the end you can usually return it, buy it for the price in your lease, or trade up. If this value is higher than your lease’s buy price, buying it can be a good deal.'
    : myCar?.owned ? 'Your car is paid off, so its value is all yours. That’s a strong spot whenever you decide to upgrade.'
    : !owed ? 'Add your loan (or tell us your car is paid off) to see what you’d have left after the loan.'
    : mid < -1000 ? 'You owe more than it’s worth right now (estimate). Keeping it and paying down the loan usually fixes that. No rush.'
    : mid < 2000 ? 'You’re about even. Waiting 6–12 more months usually grows what you’d have left. No rush.'
    : 'You’d likely have money left after paying off the loan. That can be your money down on the next car.';

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      <SkyHeader title="Your car’s value" sub={myCar ? `${carName(myCar)}${miles ? ` · ${miles.toLocaleString('en-US')} mi` : ''}` : undefined} back={back} />
      <View style={calm ? sheet.page : { flex: 1 }}>
        <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, paddingTop: 6 }}>
          {!myCar ? (
            <Card style={{ paddingVertical: 16 }}>
              <Body bold>Add your car first</Body>
              <View style={{ marginTop: 12 }}><BigBtn label="Go to My Garage" onPress={back} /></View>
            </Card>
          ) : !range ? (
            <Card style={{ paddingVertical: 16 }}>
              <Body bold>We don’t have prices for this car yet</Body>
              <Body style={s.small}>We give estimates for the 35 cars in our guide. Ask 2–3 dealers or car buying sites for a trade-in offer to know its value.</Body>
            </Card>
          ) : (<>
            <Card style={{ paddingVertical: 14 }}>
              <Text style={s.tag}>ESTIMATE</Text>
              <Text style={s.big}>{`${usd(range[0])}–${usd(range[1])}`}</Text>
              <Body style={s.small}>What dealers often pay on trade-in for a car like yours{miles ? '' : ' (add your miles to make it closer)'}.</Body>
              {owed > 0 && (<>
                <View style={[s.row, s.line, { marginTop: 8 }]}><Text style={s.k}>You still owe</Text><Text style={s.v}>{`≈ ${usd(owed)}`}</Text></View>
                <View style={s.row}><Text style={s.k}>Value − loan</Text>
                  <Text style={[s.v, { color: mid >= 0 ? C.green : C.red }]}>{`≈ ${signed(lo)} to ${signed(hi)}`}</Text></View>
              </>)}
              {!myCar.loan && !myCar.owned && !leased && (
                <Pressable onPress={() => { tap(); router.push('/loan'); }} accessibilityRole="button" style={{ marginTop: 8 }}>
                  <Text style={s.link}>Have a car loan, or is it paid off? Tell us ›</Text>
                </Pressable>
              )}
            </Card>
            <View style={s.info}><Text style={s.infoT}>A real offer depends on the car’s condition and the dealer. Get 2–3 offers before you decide.</Text></View>
            <Card style={{ marginTop: 10, paddingVertical: 12 }}>
              <Body bold>What it means</Body>
              <Body style={[s.small, { fontSize: 13.5, color: C.ink }]}>{meaning}</Body>
            </Card>

            {ideas.length > 0 && (<>
              <Label style={s.sec}>{`Upgrade ideas · same kind of car${plan ? ` · your plan about $${plan}/mo` : ''}`}</Label>
              {ideas.map((x) => {
                const fits = plan ? x.pay <= plan : undefined;
                return (
                  <Pressable key={x.car.id} onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: x.car.id, year: String(x.year) } }); }}
                    accessibilityRole="button" style={s.idea}>
                    <CarThumb id={x.car.id} year={x.year} width={80} height={54} />
                    <View style={{ flex: 1 }}>
                      <Text style={s.ideaT}>{`${x.year} ${x.car.make} ${x.car.model}`}</Text>
                      <Text style={s.small}>{x.same ? 'A newer version of your car' : `${x.car.body} · ${x.car.tag}`}</Text>
                      <Text style={[s.small, { color: C.ink, marginTop: 2 }]}>
                        {`≈ $${x.pay.toLocaleString('en-US')} a month with your trade-in, est.`}
                        {fits === undefined ? '' : fits ? '  ✓ Fits' : `  $${(x.pay - plan!).toLocaleString('en-US')} over`}
                      </Text>
                    </View>
                  </Pressable>
                );
              })}
            </>)}
            <View style={{ marginTop: 12 }}><BigBtn label="Keep my car for now" kind="plain" onPress={back} /></View>
            <Card style={{ marginTop: 12 }}>
              <ToggleRow last icon={(c) => <BellIcon size={18} color={c} />} label="Value check every 3 months" sub="A quick note on what it’s worth. Turn it off any time."
                on={!!session && myCar.valueTips !== false}
                onChange={(v) => (session ? setMyCar({ ...myCar, valueTips: v }) : askAccount('Get value checks', 'Free account. Every 3 months, what your car is worth now. No spam, never sold.'))} />
            </Card>
            <Body style={[s.small, { marginTop: 12 }]}>Our picks, not ads. Payments use your loan rate (or a typical used-car rate), 72 months and your state’s tax. Estimates, not a loan offer.</Body>
          </>)}
        </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  tag: { alignSelf: 'flex-start', fontFamily: F.bodyBold, fontSize: 10, letterSpacing: 1, color: C.onAccent, backgroundColor: C.fill, borderRadius: 6, paddingHorizontal: 6, paddingVertical: 2, overflow: 'hidden' },
  big: { fontFamily: F.head, fontSize: 26, color: C.ink, marginTop: 6 },
  small: { fontSize: 12, color: C.muted, marginTop: 4, lineHeight: 17, fontFamily: F.body },
  row: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 8 },
  line: { borderBottomWidth: 1, borderBottomColor: C.line },
  k: { fontFamily: F.body, fontSize: 13.5, color: C.muted },
  v: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.ink },
  link: { fontFamily: F.bodyBold, fontSize: 13, color: C.yellow },
  info: { backgroundColor: C.fill, borderRadius: 14, padding: 12, marginTop: 10 },
  infoT: { fontFamily: F.body, fontSize: 12.5, color: C.onAccent, lineHeight: 18 },
  sec: { marginTop: 20, marginBottom: 6 },
  idea: { flexDirection: 'row', gap: 12, alignItems: 'center', backgroundColor: C.card, borderRadius: 16, padding: 10, marginTop: 8, borderWidth: 1, borderColor: C.line },
  ideaT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
}));
