// "The car you scanned" on top of Check a car (picture 151 panels 1 + 4, Oct 26, 2026). We look up that exact VIN in the
// cars-for-sale feed: found = the dealer's real photo and color, price, miles, history, where it is, and the fee check.
// Not online (a new arrival or a private seller) = say so, and offer "Use my location" when we don't know where they are.
// The feed is tester-only until Auto.dev says yes in writing; everyone else simply doesn't see this card.
import * as WebBrowser from 'expo-web-browser';
import { useEffect, useState } from 'react';
import { Image, StyleSheet, View } from 'react-native';

import { FeeCheck } from '@/components/fee-check';
import { tap } from '@/components/ui';
import { UseMyLocation } from '@/components/use-location';
import { colorFamily, hexOf } from '@/data/colors';
import { findByVin, openDealerInMaps, type Listing, type OneCar } from '@/data/listings';
import { money } from '@/data/prices';
import { lastSpot, type Spot } from '@/lib/location';
import { useAnswers } from '@/state/answers';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';
import { useRefreshTick } from '@/lib/refresh';

export function ScannedCar({ vin, scanned, onCar }: { vin: string; scanned: boolean; onCar?: (c: Listing) => void }) {
  const { answers, setAnswers } = useAnswers();
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const [spot, setSpot] = useState<Spot | null>(lastSpot());
  const where = spot ? { lat: spot.lat, lon: spot.lon } : zip ? { zip } : null;
  const key = where ? `${vin}|${JSON.stringify(where)}` : '';
  const [got, setGot] = useState<{ key: string; r: OneCar } | null>(null);
  const tick = useRefreshTick();
  useEffect(() => {
    if (!key || !where) return;
    let on = true;
    findByVin(vin, where).then((r) => {
      if (!on) return;
      setGot({ key, r });
      if (r.kind === 'car') onCar?.(r.car);
    }).catch(() => on && setGot({ key, r: { kind: 'offline' } }));
    return () => { on = false; };
  }, [key, tick]); // eslint-disable-line react-hooks/exhaustive-deps
  const r = got?.key === key ? got.r : null;

  if (!where) {
    return (
      <View style={[s.box, s.dashed]}>
        <Text style={s.title}>Is this car at a dealer near you?</Text>
        <Text style={s.small}>Share where you are and we’ll look for this exact car, then compare it with others nearby.</Text>
        <UseMyLocation needZip style={{ marginTop: 10 }} onSpot={(sp) => { setSpot(sp); if (sp.zip) setAnswers({ ...answers, zip: sp.zip }); }} />
      </View>
    );
  }
  if (!r) return <Text style={[s.small, { marginTop: 10 }]} accessibilityLiveRegion="polite">Looking for this exact car online…</Text>;
  if (r.kind === 'soon' || r.kind === 'offline') return null;
  if (r.kind === 'none') {
    return (
      <View style={[s.box, s.dashed]} accessibilityLiveRegion="polite">
        <Text style={s.title}>We couldn’t find this exact car online</Text>
        <Text style={s.small}>{r.gone ? `It was listed until ${new Date(r.gone).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}. It may be sold, or new on the lot again.` : 'It may be new on the lot, or sold by a person. You can still check it: add the price and fees below.'}</Text>
      </View>
    );
  }

  const c = r.car;
  const fam = colorFamily(c.color);
  const facts = [c.miles != null ? `${c.miles.toLocaleString('en-US')} mi` : null, c.used ? (c.cpo ? 'Certified used' : 'Used') : 'New'].filter((x): x is string => !!x);
  const history = [c.accidents != null ? (c.accidents ? `${c.accidents} accident${c.accidents > 1 ? 's' : ''} reported` : 'No accidents reported') : null,
    c.owners != null ? `${c.owners} owner${c.owners > 1 ? 's' : ''}` : null].filter((x): x is string => !!x);
  // Each piece is its own Text so it's translated on its own.
  const dots = (parts: string[]) => parts.map((p, i) => <Text key={p}>{i ? ' · ' : ''}<Text>{p}</Text></Text>);
  return (
    <View style={[s.box, s.found]} accessibilityLiveRegion="polite">
      <Text style={s.kicker}>{scanned ? 'THE CAR YOU SCANNED' : 'THIS CAR IS FOR SALE'}</Text>
      {c.photo ? (
        <View>
          <Image source={{ uri: c.photo }} style={s.photo} resizeMode="cover" accessibilityLabel={`Dealer photo of the ${c.year} ${c.make} ${c.model}`} />
          {c.color ? <View style={s.badge}><View style={[s.dot, { backgroundColor: hexOf(fam) }]} /><Text style={s.badgeText}>{c.color}</Text></View> : null}
        </View>
      ) : null}
      <Text style={s.name}>{`${c.year} ${c.make} ${c.model}${c.trim ? ` ${c.trim}` : ''}`}</Text>
      <Text style={s.small}>{`${c.dealer}${c.city ? ` · ${c.city}` : ''} · about ${c.min} min away`}</Text>
      <Text style={s.price}>{money(c.price)}<Text style={s.small}>{'  '}{dots(facts)}</Text></Text>
      {history.length ? <Text style={[s.small, { color: c.accidents ? '#B7791F' : C.green, fontFamily: F.bodyBold }]}>{dots(history)}</Text> : null}
      <FeeCheck price={c.price} />
      <View style={s.btns}>
        <Pressable onPress={() => { tap(); openDealerInMaps(c); }} accessibilityRole="button" style={s.btn}><Text style={s.btnText}>Open in Maps</Text></Pressable>
        <Pressable onPress={() => { tap(); WebBrowser.openBrowserAsync(c.link).catch(() => {}); }} accessibilityRole="link" style={s.btn}><Text style={s.btnText}>Dealer’s page ↗</Text></Pressable>
      </View>
      <Text style={[s.small, { fontSize: 11 }]}>From the dealer’s listing. Photo by the dealer.</Text>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 18, padding: 12, marginTop: 12 },
  dashed: { borderStyle: 'dashed' },
  found: { borderWidth: 2, borderColor: C.yellow },
  kicker: { fontFamily: F.bodyBold, fontSize: 11, letterSpacing: 1.3, color: C.yellow },
  photo: { width: '100%', height: 180, borderRadius: 12, marginTop: 8, backgroundColor: C.line },
  badge: { position: 'absolute', right: 8, top: 16, flexDirection: 'row', alignItems: 'center', gap: 5, backgroundColor: 'rgba(255,255,255,0.94)', borderRadius: 999, paddingHorizontal: 9, paddingVertical: 3 },
  dot: { width: 10, height: 10, borderRadius: 5, borderWidth: 1, borderColor: 'rgba(0,0,0,0.15)' },
  badgeText: { fontFamily: F.bodyBold, fontSize: 11, color: '#0F1A2A' },
  name: { fontFamily: F.bodyBold, fontSize: 17, color: C.ink, marginTop: 8 },
  title: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  small: { fontFamily: F.body, fontSize: 12.5, lineHeight: 17, color: C.muted, marginTop: 2 },
  price: { fontFamily: F.head, fontSize: 22, color: C.ink, marginTop: 4 },
  btns: { flexDirection: 'row', gap: 8, marginTop: 10, marginBottom: 6 },
  btn: { flex: 1, backgroundColor: C.fill, borderRadius: 999, paddingVertical: 9, alignItems: 'center' },
  btnText: { fontFamily: F.bodyBold, fontSize: 13, color: C.onAccent },
}));
