// A scroll wheel like setting an alarm (picture 185, Nov 4, 2026): the item in the middle band is picked.
// Scroll it, or tap an item to bring it to the middle.
import { useEffect, useRef } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';

import { tap } from '@/components/ui';
import { C, F, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

const ITEM = 38;
const SHOW = 5;

export function Wheel({ items, value, onChange, label }: { items: string[]; value: string | null; onChange: (v: string) => void; label: string }) {
  const ref = useRef<ScrollView>(null);
  const settle = useRef<ReturnType<typeof setTimeout> | null>(null);
  const index = Math.max(0, items.indexOf(value ?? ''));
  const key = items.join('|');

  // Bring the picked item to the middle when the list or the value changes from outside.
  useEffect(() => {
    const t = setTimeout(() => ref.current?.scrollTo({ y: index * ITEM, animated: false }), 30);
    return () => clearTimeout(t);
  }, [key]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => { if (settle.current) clearTimeout(settle.current); }, []);

  const pickAt = (y: number) => {
    const i = Math.min(items.length - 1, Math.max(0, Math.round(y / ITEM)));
    if (items[i] !== undefined && items[i] !== value) onChange(items[i]);
  };

  return (
    <View style={s.box} accessibilityLabel={label}>
      <View pointerEvents="none" style={s.band} />
      <ScrollView ref={ref} nestedScrollEnabled showsVerticalScrollIndicator={false} snapToInterval={ITEM} decelerationRate="fast"
        scrollEventThrottle={16} contentContainerStyle={{ paddingVertical: ITEM * ((SHOW - 1) / 2) }}
        onScroll={(e) => { const y = e.nativeEvent.contentOffset.y; if (settle.current) clearTimeout(settle.current); settle.current = setTimeout(() => pickAt(y), 140); }}>
        {items.map((it, i) => {
          const on = i === index && value !== null;
          return (
            <Pressable key={it} onPress={() => { tap(); onChange(it); ref.current?.scrollTo({ y: i * ITEM, animated: true }); }}
              accessibilityRole="button" accessibilityState={{ selected: on }} accessibilityLabel={`${label}: ${it}`} style={s.item}>
              <Text numberOfLines={1} style={[s.text, on && s.on]}>{it}</Text>
            </Pressable>
          );
        })}
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  box: { flex: 1, height: ITEM * SHOW, overflow: 'hidden' },
  band: { position: 'absolute', left: 2, right: 2, top: ITEM * ((SHOW - 1) / 2), height: ITEM, borderRadius: 10, backgroundColor: C.card, borderWidth: 1, borderColor: C.line },
  item: { height: ITEM, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 4 },
  text: { fontFamily: F.body, fontSize: 14, color: C.muted },
  on: { fontFamily: F.bodyBold, fontSize: 15.5, color: C.ink },
}));
