// Feedback that pops up sometimes · style A "Small card" (picture 42, picked Oct 13, 2026;
// replaces the gold side tab from picture 39). A small card slides up above the tab bar:
// "How's Carvessa so far?" Tap a face and it's sent; then they can add a note in the full sheet.
// When: never on the first visit; first on the 3rd app open (friends
// testing see it), after 45 seconds of use; then at most once a month; after an answer or ✕, 3 months.
// Never on the opening, Login or Premium screens, or while the keyboard is up.
// Anyone can send an idea any time from Me › Send us an idea (IdeaSheet, picture 118 A, Oct 21, 2026), and the
// help chat's "I don't know that one yet" answer has "Tell us what you needed" (sendIdea).
// Saved to the Supabase table `feedback` (migration 010; insert-only, nobody can read it with the app's key).
import AsyncStorage from '@react-native-async-storage/async-storage';
import { usePathname } from 'expo-router';
import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Animated, Keyboard, Modal, Platform, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { notify } from '@/components/notify';
import { Body, Btn, H, tap } from '@/components/ui';
import { supabase } from '@/lib/supabase';
import { C, F, themed } from '@/theme';
import { KeyboardSheet } from '@/components/keyboard-sheet';
import { Pressable, Text, TextInput } from '@/components/t';
import { BulbIcon, HeartIcon, InfoIcon, WrenchIcon } from '@/components/icons';

type Mood = 'love' | 'ok' | 'confused';
const MOODS: { key: Mood; face: string; label: string }[] = [
  { key: 'love', face: '😀', label: 'Love it' },
  { key: 'ok', face: '😐', label: 'It’s OK' },
  { key: 'confused', face: '😕', label: 'Confused' },
];
// No pop-up on the opening, Login and Premium screens (they are full-screen moments).
const HIDE = ['/', '/login'];
const KEY = 'carvessa:feedback-ask:v1';
const DAY = 86400000;
const stamp = () => Date.now();
const FIRST_OPEN = 3;
const WAIT_MS = 45000;
type Ask = { opens: number; lastAsk?: number; done?: number };
const platform = () => (Platform.OS === 'ios' || Platform.OS === 'android' || Platform.OS === 'web' ? Platform.OS : '');
const saveFeedback = (mood: Mood, message: string, screen: string) =>
  supabase.from('feedback').insert({ mood, message: message.trim().slice(0, 2000), screen: screen.slice(0, 120), platform: platform() });

// Ideas (picture 118 A) go in the same private feedback list. The table only takes the three moods, so the
// kind of idea starts the message ("[Idea: new] …") and no new table or migration is needed.
export type IdeaKind = 'new' | 'broken' | 'confusing';
const KINDS: { key: IdeaKind; icon: typeof BulbIcon; label: string; mood: Mood }[] = [
  { key: 'new', icon: BulbIcon, label: 'Add something new', mood: 'ok' },
  { key: 'broken', icon: WrenchIcon, label: 'Something isn’t working', mood: 'confused' },
  { key: 'confusing', icon: InfoIcon, label: 'Something is confusing', mood: 'confused' },
];
export const ideaMessage = (kind: IdeaKind, message: string) => `[Idea: ${kind}] ${message.trim()}`.slice(0, 2000);
export const sendIdea = (kind: IdeaKind, message: string, screen: string) =>
  saveFeedback(KINDS.find((k) => k.key === kind)!.mood, ideaMessage(kind, message), screen);

export function FeedbackPrompt() {
  const path = usePathname();
  const insets = useSafeAreaInsets();
  const [ask, setAsk] = useState<Ask | null>(null);
  const [show, setShow] = useState(false);
  const [sent, setSent] = useState<Mood | null>(null);
  const [sheet, setSheet] = useState(false);
  const [slide] = useState(() => new Animated.Value(0));
  const pathRef = useRef(path);
  useEffect(() => { pathRef.current = path; }, [path]);

  // Count this app open (once per start).
  useEffect(() => {
    AsyncStorage.getItem(KEY).then((raw) => {
      const old: Ask = raw ? JSON.parse(raw) : { opens: 0 };
      const next = { ...old, opens: (old.opens ?? 0) + 1 };
      setAsk(next);
      AsyncStorage.setItem(KEY, JSON.stringify(next)).catch(() => {});
    }).catch(() => setAsk({ opens: 1 }));
  }, []);

  const save = (patch: Partial<Ask>) => setAsk((old) => {
    const next = { ...(old ?? { opens: 1 }), ...patch };
    AsyncStorage.setItem(KEY, JSON.stringify(next)).catch(() => {});
    return next;
  });

  // Decide once, after 45 seconds of use, whether to ask this time.
  useEffect(() => {
    if (!ask) return;
    const now = Date.now();
    const due = ask.opens >= FIRST_OPEN
      && (!ask.lastAsk || now - ask.lastAsk > 30 * DAY)
      && (!ask.done || now - ask.done > 90 * DAY);
    if (!due) return;
    let timer: ReturnType<typeof setTimeout>;
    const tryShow = () => {
      // Not over full-screen moments or while typing: try again a bit later.
      if (HIDE.includes(pathRef.current) || Keyboard.isVisible()) { timer = setTimeout(tryShow, 15000); return; }
      setShow(true);
      save({ lastAsk: Date.now() });
      Animated.spring(slide, { toValue: 1, useNativeDriver: Platform.OS !== 'web', friction: 8 }).start();
    };
    timer = setTimeout(tryShow, WAIT_MS);
    return () => clearTimeout(timer);
  }, [ask?.opens]); // eslint-disable-line react-hooks/exhaustive-deps

  const close = () => {
    Animated.timing(slide, { toValue: 0, duration: 200, useNativeDriver: Platform.OS !== 'web' }).start(() => setShow(false));
  };
  const pick = (m: Mood) => {
    tap();
    setSent(m);
    save({ done: stamp() });
    saveFeedback(m, '', path).then(() => {}, () => {});
  };

  if (!show && !sheet) return null;
  return (
    <>
      {show && !HIDE.includes(path) && (
        <Animated.View style={[s.card, { bottom: Math.max(insets.bottom, 8) + 66, opacity: slide, transform: [{ translateY: slide.interpolate({ inputRange: [0, 1], outputRange: [40, 0] }) }] }]}
          accessibilityViewIsModal={false} accessibilityLiveRegion="polite">
          <Pressable onPress={() => { tap(); if (!sent) save({ done: stamp() }); close(); }} accessibilityRole="button" accessibilityLabel="Close" hitSlop={10} style={s.x}>
            <Text style={s.xText}>✕</Text>
          </Pressable>
          {!sent ? (
            <>
              <Text style={s.cardTitle}>How’s Carvessa so far?</Text>
              <Text style={s.fine2}>Tap a face. It takes 5 seconds.</Text>
              <View style={{ flexDirection: 'row', gap: 6, marginTop: 8 }}>
                {MOODS.map((m) => (
                  <Pressable key={m.key} onPress={() => pick(m.key)} style={s.smallFace} accessibilityRole="button" accessibilityLabel={m.label}>
                    <Text style={{ fontSize: 24 }}>{m.face}</Text>
                    <Text style={s.smallLabel}>{m.label}</Text>
                  </Pressable>
                ))}
              </View>
            </>
          ) : (
            <>
              <Text style={s.cardTitle}>Thank you!</Text>
              <Text style={s.fine2}>Want to tell us more? It really helps.</Text>
              <View style={{ flexDirection: 'row', gap: 8, marginTop: 10 }}>
                <Pressable onPress={() => { tap(); setSheet(true); close(); }} style={s.noteBtn} accessibilityRole="button"><Text style={s.noteText}>Add a note</Text></Pressable>
                <Pressable onPress={() => { tap(); close(); }} style={s.doneBtn} accessibilityRole="button"><Text style={s.doneText}>Done</Text></Pressable>
              </View>
            </>
          )}
        </Animated.View>
      )}
      {sheet && <FeedbackSheet screen={path} startMood={sent ?? undefined} onClose={() => setSheet(false)} />}
    </>
  );
}

export function FeedbackSheet({ screen, startMood, onClose }: { screen: string; startMood?: Mood; onClose: () => void }) {
  const [mood, setMood] = useState<Mood | null>(startMood ?? null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const send = async () => {
    setError(null);
    if (!mood) return setError('Pick a face first.');
    setBusy(true);
    const { error: err } = await saveFeedback(mood, message, screen);
    setBusy(false);
    if (err) return setError('Couldn’t send. Check your internet and try again.');
    notify('Thank you!', 'We got your feedback. It really helps.');
    onClose();
  };

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
          <View style={s.grab} />
          <H size={28}>How’s Carvessa?</H>
          <Body style={{ color: C.muted, fontSize: 14 }}>It takes 30 seconds. It really helps.</Body>
          <View style={{ flexDirection: 'row', gap: 8, marginTop: 4 }}>
            {MOODS.map((m) => {
              const on = mood === m.key;
              return (
                <Pressable key={m.key} onPress={() => { tap(); setMood(m.key); setError(null); }} style={[s.face, on && s.faceOn]}
                  accessibilityRole="radio" accessibilityState={{ selected: on }} accessibilityLabel={m.label}>
                  <Text style={{ fontSize: 30 }}>{m.face}</Text>
                  <Text style={s.faceLabel}>{m.label}</Text>
                </Pressable>
              );
            })}
          </View>
          <Text style={s.q}>Tell us more (optional)</Text>
          <TextInput value={message} onChangeText={setMessage} multiline maxLength={2000} style={s.input}
            placeholder="What did you like? What was confusing?" placeholderTextColor={C.muted}
            accessibilityLabel="Tell us more (optional)" textAlignVertical="top" />
          {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
          {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Send" onPress={send} />}
          <Text style={s.fine}>We read every message. Don’t share private info.</Text>
          <Pressable onPress={() => { tap(); onClose(); }} accessibilityRole="button" style={{ alignSelf: 'center', padding: 6 }}><Text style={s.notNow}>Not now</Text></Pressable>
        </KeyboardSheet>
    </Modal>
  );
}

// Me › Send us an idea: pick a kind, write it, Send, then a short thank-you (no promise we'll build it).
export function IdeaSheet({ screen, onClose }: { screen: string; onClose: () => void }) {
  const [kind, setKind] = useState<IdeaKind>('new');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);

  const send = async () => {
    setError(null);
    if (!message.trim()) return setError('Write a few words first.');
    setBusy(true);
    const { error: err } = await sendIdea(kind, message, screen);
    setBusy(false);
    if (err) return setError('Couldn’t send. Check your internet and try again.');
    setDone(true);
  };

  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <KeyboardSheet onClose={onClose} backStyle={s.back} sheetStyle={s.sheet}>
          <View style={s.grab} />
          {done ? (
            <View style={{ alignItems: 'center', gap: 8, paddingVertical: 10 }} accessibilityLiveRegion="polite">
              <View style={s.thanksIcon}><HeartIcon size={30} color={C.onAccent} /></View>
              <H size={26}>Thank you!</H>
              <Body style={{ color: C.muted, fontSize: 14, textAlign: 'center' }}>We got your idea. A real person reads every one. Ideas like yours decide what we build next.</Body>
              <Btn kind="yellow" label="Done" style={{ alignSelf: 'stretch', marginTop: 6 }} onPress={() => { tap(); onClose(); }} />
              <Pressable onPress={() => { tap(); setDone(false); setMessage(''); }} accessibilityRole="button" style={{ padding: 6 }}>
                <Text style={s.another}>Send another idea</Text>
              </Pressable>
            </View>
          ) : (
            <>
              <H size={26}>Send us an idea</H>
              <Body style={{ color: C.muted, fontSize: 14 }}>We read every one. English or Spanish is fine.</Body>
              {KINDS.map((k) => {
                const on = kind === k.key;
                return (
                  <Pressable key={k.key} onPress={() => { tap(); setKind(k.key); }} style={[s.kind, on && s.kindOn]}
                    accessibilityRole="radio" accessibilityState={{ selected: on }} accessibilityLabel={k.label}>
                    <k.icon size={18} color={on ? C.onAccent : C.ink} />
                    <Text style={[s.kindText, on && { color: C.onAccent }]}>{k.label}</Text>
                  </Pressable>
                );
              })}
              <TextInput value={message} onChangeText={(v) => { setMessage(v); setError(null); }} multiline maxLength={1900} style={s.input}
                placeholder={kind === 'broken' ? 'What happened? Which screen?' : kind === 'confusing' ? 'What was hard to understand?' : 'What should Carvessa do for you?'}
                placeholderTextColor={C.muted} accessibilityLabel="Your idea" textAlignVertical="top" />
              {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
              {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56 }} /> : <Btn kind="yellow" label="Send" onPress={send} />}
              <Text style={s.fine}>Please don’t write passwords or card numbers.</Text>
            </>
          )}
        </KeyboardSheet>
    </Modal>
  );
}

