// Cost to own · Set D · Coach chat: 5-year cost, payment calculator, compare and save.
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon, CoachIcon } from '@/components/icons';
import { Body, Chip, H, Label, SquareBtn } from '@/components/ui';
import { CARS, Car, carName } from '@/data/cars';
import { CREDIT, TERMS, fiveYearCost, round } from '@/data/costs';
import { costsFor } from '@/data/state-costs';
import { money, priceFor, tradeInFor } from '@/data/prices';
import { useFacts } from '@/data/use-facts';
import { topMatches, useAnswers } from '@/state/answers';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Text, TextInput } from '@/components/t';
import { LATEST_MODEL_YEAR, ageOf } from '@/data/year';

const COLORS = () => [C.ink, C.yellow, '#8A8F96', '#C9CED6', '#2F4A6B', C.red];
const MILES = [8000, 12000, 15000, 25000];

function Bubble({ me, children }: { me?: boolean; children: React.ReactNode }) {
  return (
    <View style={[s.bub, me ? s.me : s.them]}>
      <Text style={me ? s.meText : s.themText}>{children}</Text>
    </View>
  );
}
function Num({ label, value, onChange, prefix, suffix }: { label: string; value: string; onChange: (v: string) => void; prefix?: string; suffix?: string }) {
  return (
    <View style={{ flex: 1 }}>
      <Label style={{ fontSize: 10.5, color: C.muted, marginBottom: 4 }}>{label}</Label>
      <View style={s.numBox}>
        {!!prefix && <Body bold>{prefix}</Body>}
        <TextInput value={value} onChangeText={(t) => onChange(t.replace(/[^\d.]/g, ''))} keyboardType="decimal-pad" accessibilityLabel={label} style={s.num} />
        {!!suffix && <Body bold>{suffix}</Body>}
      </View>
    </View>
  );
}

// Inputs for one car: its price, real MPG and how old it is.
function useCarCost(car: Car | undefined, year: number, opts: { miles: number; gas: number; down: number; credit: { apr: number; used: number }; months: number; tax: number }, priceOverride?: number) {
  const { facts } = useFacts(car?.id, year);
  const base = car ? priceFor(car, year) : null;
  if (!car || !base) return null;
  const p = priceOverride ? { ...base, amount: priceOverride } : base;
  const electric = facts?.mpg?.fuel === 'EV';
  const apr = p.isNew ? opts.credit.apr : opts.credit.used;
  return {
    price: p, apr, mpg: facts?.mpg?.combined,
    r: fiveYearCost({ price: p.amount, isNew: p.isNew, ageYears: ageOf(year), mpg: facts?.mpg?.combined, electric,
      milesPerYear: opts.miles, gasPrice: opts.gas, kwhPrice: 0.17, down: opts.down, apr, months: opts.months, taxPct: opts.tax }),
  };
}

function CompareLine({ car, year, opts, max, me }: { car: Car; year: number; opts: Parameters<typeof useCarCost>[2]; max: number; me?: boolean }) {
  const c = useCarCost(car, year, opts);
  if (!c) return null;
  return (
    <View style={{ marginBottom: 10 }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
        <Body bold style={{ flex: 1, fontSize: 14 }}>{carName(car, year)}</Body>
        <H size={18}>{money(round(c.r.perMonth))}/mo</H>
      </View>
      <View style={{ height: 12, backgroundColor: C.grey, marginTop: 4 }}>
        <View style={{ height: '100%', width: `${Math.min(100, (c.r.total5 / max) * 100)}%`, backgroundColor: me ? C.yellow : C.ink }} />
      </View>
    </View>
  );
}

export default function CostToOwn() {
  const { id, year: y } = useLocalSearchParams<{ id: string; year?: string }>();
  const year = Number(y) || LATEST_MODEL_YEAR;
  const car = CARS.find((c) => c.id === id);
  const { answers } = useAnswers();
  const [miles, setMiles] = useState(answers.goal === 'Drive for apps' ? 25000 : 12000);
  const [gas, setGas] = useState('3.30');
  const [down, setDown] = useState('2000');
  const [priceText, setPriceText] = useState('');
  const trade = (answers.current ?? '').startsWith('Yes') ? tradeInFor(answers.myCar, CARS) : null;
  const [tradeText, setTradeText] = useState(trade ? String(trade.amount) : '0');
  const [tax, setTax] = useState(String(costsFor().tax));
  const [credit, setCredit] = useState(1);
  const [months, setMonths] = useState(60);
  const opts = { miles, gas: Number(gas) || 0, down: (Number(down) || 0) + (Number(tradeText) || 0), credit: CREDIT[credit], months, tax: Number(tax) || 0 };
  const me = useCarCost(car, year, opts, Number(priceText) || undefined);
  const others = useMemo(() => topMatches(answers, 4).filter((m) => m.car.id !== id).slice(0, 2), [answers, id]);
  if (!car || !me) return null;
  const name = carName(car, year);
  const maxTotal = me.r.total5 * 1.6;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Your coach" back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}><CoachIcon size={18} /><Label>Your coach</Label></View>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 8 }} keyboardShouldPersistTaps="handled">
        {/* D1 · 5-year cost */}
        <Bubble me>What will the {name} really cost me?</Bubble>
        <Bubble>Here’s everything over 5 years: the price you lose, gas, insurance, upkeep and more.</Bubble>
        <>
        <View style={s.total}>
          <Label style={{ color: C.yellow }}>5 years, all in · estimate</Label>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline', marginTop: 4 }}>
            <H size={44} style={{ color: C.ink }}>{money(round(me.r.total5, 100))}</H>
            <H size={22} style={{ color: C.yellow }}>{money(round(me.r.perMonth))}/mo</H>
          </View>
          <View style={s.bar}>
            {me.r.parts.map((p, i) => <View key={p.label} style={{ flex: Math.max(0.01, p.amount), backgroundColor: COLORS()[i], borderRightWidth: 2, borderRightColor: C.ink }} />)}
          </View>
        </View>
        {me.r.parts.map((p, i) => (
          <View key={p.label} style={s.legend}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
              <View style={{ width: 12, height: 12, backgroundColor: COLORS()[i], borderWidth: 1, borderColor: C.ink }} />
              <Body bold>{p.label}</Body>
            </View>
            <H size={18}>{money(round(p.amount, 10))}</H>
          </View>
        ))}
        <Label style={{ marginTop: 8 }}>Miles you drive a year</Label>
        <View style={s.chips}>{MILES.map((m) => <Chip key={m} label={`${m / 1000}K`} on={miles === m} onPress={() => setMiles(m)} />)}</View>
        <View style={s.formRow}>
          <Num label={me.mpg && me.r.parts[1].label === 'Charging' ? 'Gas price (not used)' : 'Gas price per gallon'} value={gas} onChange={setGas} prefix="$" />
          <View style={{ flex: 1, justifyContent: 'flex-end' }}>
            <Body style={{ fontSize: 12, color: C.muted }}>{me.mpg ? `Uses the EPA ${me.r.parts[1].label === 'Charging' ? 'rating of ' + me.mpg + ' MPGe' : me.mpg + ' MPG'}.` : 'No EPA rating, so we guess.'}</Body>
          </View>
        </View>
        </>

        {/* D2 · Financing */}
        <View style={{ height: 10 }} />
        <Bubble me>What would my payment be?</Bubble>
        <Bubble>Tap your credit and loan length. I’ll do the math.</Bubble>
        <View style={s.formRow}>
          <Num label="Price (type a quote)" value={priceText || String(me.price.amount)} onChange={setPriceText} prefix="$" />
          <Num label="Down payment" value={down} onChange={setDown} prefix="$" />
          <Num label="Sales tax" value={tax} onChange={setTax} suffix="%" />
        </View>
        <View style={s.formRow}>
          <Num label={trade ? `Trade-in: your ${answers.myCar}` : 'Trade-in value'} value={tradeText} onChange={setTradeText} prefix="$" />
          <View style={{ flex: 1, justifyContent: 'flex-end' }}>
            <Body style={{ fontSize: 12, color: C.muted }}>{trade ? 'Our estimate. Dealers check miles and condition.' : 'Type it if you have a car to trade.'}</Body>
          </View>
        </View>
        <Label style={{ marginTop: 6 }}>Credit</Label>
        <View style={s.chips}>{CREDIT.map((c, i) => <Chip key={c.label} label={c.label} on={credit === i} onPress={() => setCredit(i)} />)}</View>
        <Label style={{ marginTop: 6 }}>Loan length</Label>
        <View style={s.chips}>{TERMS.map((t) => <Chip key={t} label={`${t} mo`} on={months === t} onPress={() => setMonths(t)} />)}</View>
        <View style={s.pay}>
          <Label>Your payment · estimate</Label>
          <View style={{ flexDirection: 'row', alignItems: 'baseline', gap: 6 }}>
            <H size={52}>{money(round(me.r.payment, 1))}</H><H size={22}>/ month</H>
          </View>
          <Body style={{ fontSize: 12.5 }}>About {me.apr}% APR{me.price.isNew ? '' : ' (used cars cost a bit more)'} · interest about {money(round(me.r.interest, 10))} total</Body>
        </View>
        <Body style={{ fontSize: 11.5, color: C.muted }}>Rates are rough averages. A credit union or bank pre-approval shows your real rate.</Body>

        {/* D3 · Compare + save */}
        {others.length > 0 && (
          <>
            <View style={{ height: 10 }} />
            <Bubble me>Which of my picks costs least?</Bubble>
            <Bubble>Here’s the monthly cost to own each one, all in, with the same choices.</Bubble>
            <>
              <View style={{ gap: 8 }}>
                <CompareLine car={car} year={year} opts={opts} max={maxTotal} me />
                {others.map((m) => <CompareLine key={m.car.id} car={m.car} year={m.year} opts={opts} max={maxTotal} />)}
              </View>
            </>
          </>
        )}
        <Label style={{ marginTop: 8 }}>Ways to save</Label>
        {['Get a pre-approved loan from a credit union first', 'Keep the loan at 60 months or less', 'Get insurance quotes from 3 companies', 'Skip add-ons you won’t use at the dealer'].map((t, i) => (
          <View key={t} style={s.tip}>
            <View style={s.tipN}><H size={15} style={{ color: C.onAccent }}>{i + 1}</H></View>
            <Body bold style={{ flex: 1, fontSize: 14 }}>{t}</Body>
          </View>
        ))}
        <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>
          All numbers are estimates to help you plan, not a quote. Insurance, upkeep and value lost are rough averages. Gas uses the real EPA mileage.
        </Body>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 8 },
  bub: { maxWidth: '86%', paddingHorizontal: 13, paddingVertical: 10 },
  them: { alignSelf: 'flex-start', backgroundColor: C.grey },
  me: { alignSelf: 'flex-end', backgroundColor: C.hero },
  themText: { fontFamily: F.body, fontSize: 15, lineHeight: 21, color: C.ink },
  meText: { fontFamily: F.bodyBold, fontSize: 15, lineHeight: 21, color: C.yellow },
  total: { backgroundColor: C.hero, padding: 14 },
  bar: { flexDirection: 'row', height: 16, marginTop: 12, borderWidth: 1, borderColor: C.line, borderRadius: 4, overflow: 'hidden' },
  legend: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingVertical: 6, borderBottomWidth: 2, borderBottomColor: C.grey },
  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6 },
  formRow: { flexDirection: 'row', gap: 8 },
  numBox: { flexDirection: 'row', alignItems: 'center', gap: 2, borderWidth: 1, borderColor: C.line, borderRadius: 12, height: 48, paddingHorizontal: 10 },
  num: { flex: 1, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, minWidth: 0 },
  pay: { backgroundColor: C.accentSoft, borderWidth: 1, borderColor: C.yellow, borderRadius: 14, padding: 14, marginTop: 6 },
  tip: { flexDirection: 'row', gap: 10, alignItems: 'center', paddingVertical: 8, borderBottomWidth: 2, borderBottomColor: C.grey },
  tipN: { width: 26, height: 26, backgroundColor: C.fill, alignItems: 'center', justifyContent: 'center' },
}));
