// Home "You can afford" card (Design 5, pictures 200 → 209, Nov 6, 2026). A white card (dark at night) with the
// car centered on a soft floor. A thin line at the top follows the time where they are (morning, day, sunset,
// night): Loudjier's "what you can afford follows the day". The gold ring shows how many of our cars fit the
// monthly payment on the gold slider, then the next 3 cars that fit and 'See all N cars that fit ›' (Search › Monthly).
// Every number is an estimate.
import { LinearGradient } from 'expo-linear-gradient';
import { router } from 'expo-router';
import { useEffect, useMemo, useState } from 'react';
import { PanResponder, StyleSheet, useWindowDimensions, View } from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';

import { CarCutout } from '@/components/car-photo';
import { useSky } from '@/components/sky';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { affordCard, clampMonthly, SLIDER_HI, SLIDER_LO, SLIDER_STEP } from '@/data/afford-card';
import { carName } from '@/data/cars';
import { money } from '@/data/prices';
import type { SkyPhase } from '@/data/sun';
import { tr } from '@/i18n';
import { monthlyCap, type Answers } from '@/state/answers';
import { C, F, isDarkLook, isShowroomColors, look, themed } from '@/theme';

// Ring and slider: the showroom gold (3:1 or more on white, Nov 6 readability check); every other look uses its own
// main color (Nov 12, 2026: Design 5 in every look).
const gold = () => (isShowroomColors() ? '#B08A45' : C.yellow);
// The thin line at the top of the card, by time of day (picture 209).
const LINE: Record<SkyPhase, [string, string]> = {
  morning: ['#8CC9D9', '#FFD9B0'], day: ['#6FB8E0', '#BFE2F0'], evening: ['#6F4BA8', '#FFC896'], night: ['#0B1026', '#3A2F4F'],
};

function GoldSlider({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  const [w, setW] = useState(1);
  const [touch, setTouch] = useState<{ base: number; dx: number } | null>(null);
  const [pan] = useState(() => PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponder: () => true,
    onPanResponderTerminationRequest: () => false,
    onPanResponderGrant: (e) => setTouch({ base: e.nativeEvent.locationX, dx: 0 }),
    onPanResponderMove: (_e, g) => setTouch((t) => (t ? { ...t, dx: g.dx } : t)),
  }));
  useEffect(() => {
    if (!touch) return;
    const next = clampMonthly(SLIDER_LO + ((touch.base + touch.dx) / w) * (SLIDER_HI - SLIDER_LO));
    if (next !== value) { tap(); onChange(next); }
  }, [touch]); // eslint-disable-line react-hooks/exhaustive-deps
  const pct = (value - SLIDER_LO) / (SLIDER_HI - SLIDER_LO);
  return (
    <View accessible accessibilityRole="adjustable" accessibilityLabel={tr('Monthly payment')}
      accessibilityValue={{ min: SLIDER_LO, max: SLIDER_HI, now: value, text: `$${value} ${tr('a month')}` }}
      accessibilityActions={[{ name: 'increment' }, { name: 'decrement' }]}
      onAccessibilityAction={(e) => onChange(clampMonthly(value + (e.nativeEvent.actionName === 'increment' ? SLIDER_STEP : -SLIDER_STEP)))}
      onLayout={(e) => setW(Math.max(1, e.nativeEvent.layout.width))} style={s.hit} {...pan.panHandlers}>
      <View pointerEvents="none" style={s.track} />
      <View pointerEvents="none" style={[s.fill, { width: `${pct * 100}%` }]} />
      <View pointerEvents="none" style={[s.thumb, { left: pct * w - 12 }]} />
    </View>
  );
}

export function AffordSky({ answers }: { answers: Answers }) {
  const { phase } = useSky();
  const width = useWindowDimensions().width;
  const [monthly, setMonthly] = useState(() => clampMonthly(monthlyCap(answers) ?? 400));
  const card = useMemo(() => affordCard(answers, monthly), [answers, monthly]);
  const best = card.best;
  const ring = 56;
  const r = ring / 2 - 4;
  const c = 2 * Math.PI * r;
  const pct = card.total ? card.count / card.total : 0;
  const moon = phase === 'night' || phase === 'evening';
  const open = () => { tap(); router.navigate({ pathname: '/search', params: { monthly: String(monthly) } }); };
  return (
    <Pressable onPress={open} accessibilityRole="button"
      accessibilityLabel={`${tr('You can afford')} ${tr('about')} $${monthly} ${tr('a month')}. ${card.count} ${tr('cars fit')}. ${tr('Estimate')}.`}
      style={s.card}>
      <LinearGradient colors={LINE[phase]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }} style={s.line} />
      <View style={s.kickRow}>
        <Svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke={gold()} strokeWidth={2} strokeLinecap="round">
          {moon ? <Path d="M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5z" />
            : <><Circle cx="12" cy="12" r="4" /><Path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5" /></>}
        </Svg>
        <Text style={s.kicker}>YOU CAN AFFORD</Text>
      </View>
      <Text style={s.big}>{`≈ $${monthly}`}<Text style={s.mo}>/mo</Text></Text>
      {best && (
        <LinearGradient colors={[C.card, C.hero, C.card]} locations={[0, 0.78, 1]} style={s.floor} pointerEvents="none">
          <CarCutout id={best.car.id} year={best.year} height={width < 360 ? 70 : 86} label={carName(best.car, best.year)} style={{ width: '78%' }} />
        </LinearGradient>
      )}
      <View style={s.fitRow}>
        <View style={{ width: ring, height: ring, alignItems: 'center', justifyContent: 'center' }}>
          <Svg width={ring} height={ring} style={StyleSheet.absoluteFill}>
            <Circle cx={ring / 2} cy={ring / 2} r={r} stroke={C.line} strokeWidth={6} fill="none" />
            <Circle cx={ring / 2} cy={ring / 2} r={r} stroke={gold()} strokeWidth={6} fill="none" strokeLinecap="round"
              strokeDasharray={`${c * Math.max(0.03, pct)} ${c}`} transform={`rotate(-90 ${ring / 2} ${ring / 2})`} />
          </Svg>
          <Text style={s.ringN}>{String(card.count)}</Text>
          <Text style={s.ringS}>cars fit</Text>
        </View>
        {best ? (
          <View style={{ flex: 1 }}>
            <Text style={s.bestK}>Best fit</Text>
            <Text style={s.best} numberOfLines={2}>{`${carName(best.car, best.year)} ≈ ${money(best.pay)}/mo`}</Text>
          </View>
        ) : <Text style={[s.bestK, { flex: 1 }]}>Slide up to see cars that fit</Text>}
      </View>
      {card.more.length > 0 && (
        <View style={s.moreRow}>
          {card.more.map((m) => (
            <Pressable key={m.car.id} style={s.mini} accessibilityRole="button"
              accessibilityLabel={`${carName(m.car, m.year)}, ${tr('about')} ${money(m.pay)} ${tr('a month')}, ${tr('Estimate')}`}
              onPress={() => { tap(); router.push({ pathname: '/car/[id]', params: { id: m.car.id, year: String(m.year) } }); }}>
              <CarCutout id={m.car.id} year={m.year} height={40} label={carName(m.car, m.year)} style={{ width: '100%' }} />
              <Text style={s.miniN} numberOfLines={1}>{`${m.year} ${m.car.model}`}</Text>
              <Text style={s.miniP}>{`≈ ${money(m.pay)}/mo`}</Text>
            </Pressable>
          ))}
        </View>
      )}
      {card.count > 0 && (
        <Pressable onPress={open} accessibilityRole="button" style={s.seeAll}>
          <Text style={s.seeAllT}>{card.count === 1 ? 'See the car that fits ›' : `See all ${card.count} cars that fit ›`}</Text>
        </Pressable>
      )}
      <GoldSlider value={monthly} onChange={setMonthly} />
      <View style={s.marks}>
        <Text style={s.mark}>$200</Text>
        <Text style={s.mark}>$800</Text>
      </View>
      <Text style={[s.mark, { textAlign: 'center', marginTop: 4, fontSize: 11.5 }]}>{`Up to ~${money(card.maxOtd)} out the door · est.`}</Text>
    </Pressable>
  );
}

/** No plan yet (picture 210): invite them to find their monthly number with the coach. */
export function AffordStart() {
  const { phase } = useSky();
  const width = useWindowDimensions().width;
  return (
    <Pressable onPress={() => { tap(); router.push('/coach'); }} accessibilityRole="button" style={s.card}>
      <LinearGradient colors={LINE[phase]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }} style={s.line} />
      <Text style={[s.kicker, { textAlign: 'center' }]}>WHAT CAN YOU AFFORD?</Text>
      <Text style={s.startH}>Find your monthly number in 2 minutes</Text>
      <LinearGradient colors={[C.card, C.hero, C.card]} locations={[0, 0.78, 1]} style={s.floor} pointerEvents="none">
        <CarCutout id="camry" height={width < 360 ? 64 : 80} label="Toyota Camry" style={{ width: '70%' }} />
      </LinearGradient>
      <LinearGradient colors={isShowroomColors() ? ['#946F30', '#6E5020'] : [C.yellow, C.yellow]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={s.startBtn}>
        <Text style={[s.startBtnT, !isShowroomColors() && isDarkLook(look) && { color: '#111318' }]}>Start →</Text>
      </LinearGradient>
      <Text style={[s.mark, { textAlign: 'center', marginTop: 8, fontSize: 12 }]}>No account needed. Free. Any budget.</Text>
    </Pressable>
  );
}

