// Pick features (Features A: icon grid, picked Oct 9, 2026). The grid itself is in
// components/feature-grid.tsx (the coach uses it too).
import { router, useLocalSearchParams } from 'expo-router';
import { useState } from 'react';
import { ScrollView, StyleSheet, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { FeatureGrid, mustTiles, picksFrom, picksToAnswers, wantTiles, type Picks } from '@/components/feature-grid';
import { BackIcon } from '@/components/icons';
import { Body, Btn, H, SquareBtn } from '@/components/ui';
import { useAnswers } from '@/state/answers';
import { calm, C, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';

export default function Features() {
  const { from, at } = useLocalSearchParams<{ from?: string; at?: string }>();
  const { answers, setAnswers } = useAnswers();
  const { width } = useWindowDimensions();
  const [picks, setPicks] = useState<Picks>(() => picksFrom(answers));
  const musts = mustTiles(picks);
  const wants = wantTiles(picks);

  const next = () => {
    setAnswers({ ...answers, ...picksToAnswers(picks) });
    router.push({ pathname: '/color', params: from ? { from, ...(at ? { at } : {}) } : {} });
  };

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Must-haves" back={() => router.back()} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.back()}><BackIcon /></SquareBtn>
          <Body bold style={{ color: C.muted, fontSize: 13 }}>{musts.length + wants.length} picked · {musts.length} must-have{musts.length === 1 ? '' : 's'}</Body>
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40, gap: 10 }}>
        <View>
          <H size={30} style={{ lineHeight: 30 }}>What do you want in your car?</H>
          <Body style={{ color: C.muted, fontSize: 13.5, marginTop: 4 }}>Tap to pick. Tap again for a gold star = must have.</Body>
        </View>
        <FeatureGrid picks={picks} onChange={setPicks} width={Math.min(width, 520) - PAD * 2} />
        <Btn kind="yellow" label="Next: pick a color" onPress={next} style={{ marginTop: 6 }} />
        <Body style={{ fontSize: 11.5, color: C.muted, textAlign: 'center' }}>“Top pick” = most wanted by car buyers in 2026 surveys. We check each car for your must-haves when we have the data.</Body>
      </ScrollView>
      </View>
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10, paddingBottom: 10 },
}));
