// Upgrading (pictures 204–206, Nov 6, 2026; Loudjier: "even if they say they are looking for a sedan, if their car is an
// SUV or a truck, show them the sedan in the bottom, and the upgrade on top"). When someone with a car picks a different
// kind, results show "Step up from your <car>" (newer cars of THEIR kind that fit the plan) first, then the kind they asked for.
import { ALL_KINDS, hasCar } from '@/data/coach';
import { carIsKind, type Car } from '@/data/cars';
import { priceFor } from '@/data/prices';
import { KIND_LABEL, monthlyCap, paymentFor, topMatches, type Answers, type Match } from '@/state/answers';

/** Their car from the coach answer ("2018 Chevrolet Trax · 61,200 mi" → year, make, model). */
export function myCarParts(a: Answers): { year?: number; make: string; model: string } | null {
  const raw = (a.myCar ?? '').split(' · ')[0].trim();
  if (!raw) return null;
  const year = Number(raw.match(/^(19|20)\d\d\b/)?.[0]) || undefined;
  const words = raw.replace(/^(19|20)\d\d\s+/, '').split(/\s+/).filter(Boolean);
  if (!words.length) return null;
  return { year, make: words[0], model: words.slice(1).join(' ') };
}

/** Upgrading and they picked a different kind than the car they drive (an SUV owner who picked Sedan). */
export function splitUpgrade(a: Answers): boolean {
  const mine = a.myCarKind;
  const want = a.kind;
  return hasCar(a) && !!a.myCar && !!mine && !!KIND_LABEL[mine] && !!want && want !== ALL_KINDS && !!KIND_LABEL[want] && KIND_LABEL[want] !== KIND_LABEL[mine];
}

const isMine = (a: Answers, car: Car) => {
  const k = a.myCarKind ?? '';
  return !!KIND_LABEL[k] && carIsKind(car, KIND_LABEL[k]) && (k !== 'SUV (3 rows)' || car.seats >= 7);
};

/** Newer cars of their own kind that fit their plan, best match first (only ones that fit; may be fewer than n). */
export function stepUps(a: Answers, n = 3): Match[] {
  if (!splitUpgrade(a)) return [];
  const mineYear = myCarParts(a)?.year ?? 0;
  const cap = monthlyCap(a);
  const list = topMatches({ ...a, kind: a.myCarKind, kindCheck: undefined }, 30);
  return list.filter((m) => {
    if (!isMine(a, m.car) || m.year <= mineYear) return false;
    if (!cap) return true;
    const p = priceFor(m.car, m.year);
    return !!p && paymentFor(a, p.amount, p.isNew) <= cap;
  }).slice(0, n);
}

/** "Same car, newer" when a step-up is the same model they drive. */
export function sameModel(a: Answers, car: Car) {
  const parts = myCarParts(a);
  return !!parts && parts.model.toLowerCase().startsWith(car.model.toLowerCase());
}

/** Plural words for a coach kind ("SUV (3 rows)" → "SUVs with 3 rows"). */
export const kindPlural = (k: string) => (k === 'SUV (3 rows)' ? 'SUVs with 3 rows' : k === 'Sports car' ? 'sports cars' : k === 'SUV' ? 'SUVs' : `${k.toLowerCase()}s`);

/** Upgrade in one tap (Nov 17, 2026, Loudjier: "Since my car is already saved. If I hit upgrade it should go automatically to
 * similar newer SUV like mine, show the top recommendation, and the rest at the bottom"): newer cars of THEIR kind, best
 * match first. Fits their monthly plan when they have one. Empty when we don't know what kind their car is. */
export function upgradeList(a: Answers, n = 9): Match[] {
  if (!a.myCar || !a.myCarKind || !KIND_LABEL[a.myCarKind]) return [];
  const mineYear = myCarParts(a)?.year ?? 0;
  const cap = monthlyCap(a);
  return topMatches({ ...a, kind: a.myCarKind, kindCheck: undefined }, 60).filter((m) => {
    if (!isMine(a, m.car) || m.year <= mineYear) return false;
    if (!cap) return true;
    const p = priceFor(m.car, m.year);
    return !!p && paymentFor(a, p.amount, p.isNew) <= cap;
  }).slice(0, n);
}
