const hello = () => {
  const h = new Date().getHours();
  return h < 5 ? 'Good evening' : h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening';
};

// Quick actions (picture 54 · A5 "Icon + name only", picked Oct 14, 2026): each tile has its own
// color (blue Coach, gold Upgrade, green Hustle, red Saved), a new line icon and a one-line name.
type Tint = 'coach' | 'upgrade' | 'hustle' | 'saved';
const TINTS: Record<'light' | 'midnight', Record<Tint, [string, string]>> = {
  light: { coach: ['#E3ECFA', '#2D5DB3'], upgrade: ['#F4ECDD', '#9A7535'], hustle: ['#E3F1E8', '#1C7C4A'], saved: ['#FBE6E3', '#B3412F'] },
  midnight: { coach: ['#1E2A40', '#8FB4F2'], upgrade: ['#33291A', '#CDB38B'], hustle: ['#16301F', '#5FD38C'], saved: ['#3A1E1B', '#F08A7A'] },
};
// Sunset Calm: one calm mint square with a green icon for every tile.
const calmTint = (): [string, string] => [C.hero, C.yellow];
function Quick({ label, help, tint, onPress }: { label: string; help: string; tint: Tint; onPress: () => void }) {
  const [soft, strong] = calm ? calmTint() : TINTS[theme === 'midnight' ? 'midnight' : 'light'][tint];
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" accessibilityLabel={`${label}. ${help}`}
      style={({ pressed }) => [s.quick, pressed && { transform: [{ scale: 0.97 }], opacity: 0.9 }]}>
      <View style={[s.badge, { backgroundColor: soft }]}><QuickIcon tint={tint} color={strong} /></View>
      {/* Longer names (like "Guardados" in Spanish) get a smaller size so they fit on one line. */}
      <Text style={[s.quickLabel, tr(label).length > 8 && { fontSize: 15 }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{label}</Text>
    </Pressable>
  );
}
function QuickIcon({ tint, color }: { tint: Tint; color: string }) {
  const p = { width: 30, height: 30, viewBox: '0 0 24 24', fill: 'none', stroke: color, strokeWidth: 2, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  if (tint === 'coach') return <Svg {...p}><Path d="M4 5.5h16v10H10l-4.5 3.5V15.5H4z" /><Path d="M12 7.6l.8 1.8 1.8.8-1.8.8-.8 1.8-.8-1.8-1.8-.8 1.8-.8z" fill={color} strokeWidth={0} /></Svg>;
  if (tint === 'upgrade') return <Svg {...p}><Path d="M3 16.5v-3l2-4.5h9l3 4.5h2.5a1.5 1.5 0 0 1 1.5 1.5v1.5" /><Circle cx="7" cy="17" r="1.8" /><Circle cx="16.5" cy="17" r="1.8" /><Path d="M18 2.5v6M15.5 5L18 2.5 20.5 5" /></Svg>;
  if (tint === 'hustle') return <Svg {...p}><Circle cx="12" cy="12" r="8.5" /><Path d="M14.6 9.2c-.4-.9-1.4-1.4-2.6-1.4-1.6 0-2.6.8-2.6 1.9 0 2.6 5.4 1.4 5.4 4.3 0 1.1-1.1 2-2.8 2-1.3 0-2.4-.6-2.8-1.6M12 6.3v1.5M12 16.3v1.5" strokeWidth={1.9} /></Svg>;
  return <Svg {...p}><Path d="M12 20s-7.5-4.6-7.5-10.1A4.2 4.2 0 0 1 12 7.3a4.2 4.2 0 0 1 7.5 2.6C19.5 15.4 12 20 12 20z" /></Svg>;
}
const SAGE = require('../../../assets/car/drawn-sage.png');

// Design C · Sunset Calm top of Home (Oct 17–18, 2026): the sky (follows the time of day) with the skyline,
// a hello, the promise, and our drawn green car parked where the sky meets the page. No V sun here.
function CalmTop({ right, name }: { right: (light: boolean) => React.ReactNode; name: string }) {
  const sky = useSky();
  const insets = useSafeAreaInsets();
  const width = useWindowDimensions().width;
  const narrow = width < 380;
  const h = 250 + insets.top;
  return (
    <View>
      <Sky height={h} phase={sky.phase} skyline={90}>
        <View style={[s.calmTop, { paddingTop: insets.top + 8 }]}>
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: 10 }}>
            <Logo size={narrow ? 13.5 : 15} sky={sky.light ? 'light' : 'dark'} />
            {right(sky.light)}
          </View>
          <Text style={[s.calmHello, { color: sky.ink }]}>{`${name ? `¡Hola, ${name}!` : '¡Hola!'} · ${tr(hello())}`}</Text>
          <Text style={[s.calmH1, { color: sky.ink }]} accessibilityRole="header">A car that fits your life</Text>
          <Text style={[s.calmH1, { color: sky.soft }]}>and your wallet.</Text>
        </View>
      </Sky>
    </View>
  );
}

// The car parked where the sky meets the page (drawn inside the page so it sits on top): your top match
// floating (design C), or our drawn green car before the coach.
function CalmCar({ id, label }: { id?: string; label?: string }) {
  const width = useWindowDimensions().width;
  if (id && hasCutout(id)) {
    const w = Math.min(width * 0.56, 300);
    return <CarCutout id={id} label={label} height={w * 0.5} style={{ position: 'absolute', top: 28 - w * 0.5 * 0.8, left: (width - w) / 2, width: w }} />;
  }
  const carW = Math.min(width * 0.5, 260);
  const carH = (carW * 179) / 600;
  return <Image source={SAGE} accessible accessibilityLabel="A green car" resizeMode="contain"
    style={{ position: 'absolute', top: 28 - carH * 0.78, left: (width - carW) / 2, width: carW, height: carH }} />;
}

// Clean look (picture 82, Oct 18, 2026): a hello and the promise on the white page, your initial or the
// log-in buttons on the right.
function CleanTop({ right, name }: { right: (light: boolean) => React.ReactNode; name: string }) {
  const insets = useSafeAreaInsets();
  const width = useWindowDimensions().width;
  const [h, setH] = useState(0);
  // Picture 133: the sky shows the real weather, with a small chip that says it plainly ("72° · Sunny").
  const weather = useSkyWeather();
  // The weather service calls 6 AM 'daytime'; our word follows the real sunrise and sunset where they are.
  const darkOut = useSunDark();
  return (
    <View style={[s.cleanTop, { paddingTop: insets.top + 8 }, hasSkyTop() && { paddingBottom: CITY_H - 4 }]} onLayout={(e) => setH(e.nativeEvent.layout.height)}>
      {hasSkyTop() && <SkyTop height={h} width={width} inset={insets.top} weather={weather} />}
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', gap: 10 }}>
        <Logo size={width < 380 ? 13.5 : 15} />
        {right(true)}
      </View>
      <View style={{ flexDirection: 'row', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
        <Text style={s.cleanHello}>{`${name ? `${tr(hello())}, ${name}` : tr(hello())}`}</Text>
        {weather && (
          <View style={[s.wxChip, { backgroundColor: isDarkLook(look) ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.7)' }]}
            accessible accessibilityLabel={`${Number.isFinite(weather.tempF) ? `${weather.tempF}°, ` : ''}${tr(skyWord(weather.sky, darkOut))}`}>
            <Text style={s.wxText}>{Number.isFinite(weather.tempF) ? `${weather.tempF}° · ${skyWord(weather.sky, darkOut)}` : skyWord(weather.sky, darkOut)}</Text>
          </View>
        )}
      </View>
      {!isShowroom() && <Text style={[s.cleanH1, width < 360 && { fontSize: 20, lineHeight: 25 }]} accessibilityRole="header">Find a car you can really afford</Text>}
    </View>
  );
}

