// Your plan in chips, then your top match with a budget ring (payment next to your monthly plan).
function PlanCard({ answers }: { answers: Answers }) {
  const top = topMatches(answers, 1)[0];
  const cap = monthlyCap(answers);
  const kind = answers.kind && !answers.kind.startsWith('Not sure') ? answers.kind : '';
  const nu = answers.newUsed === 'New only' ? 'New' : answers.newUsed === 'Used only' ? 'Used' : '';
  const zip = answers.zip && /^\d{5}$/.test(answers.zip) ? answers.zip : '';
  const chips: [React.ReactNode, string][] = [];
  if (kind || nu) chips.push([<CarIcon key="c" size={15} color={C.yellow} />, [nu, kind].filter(Boolean).join(' ')]);
  if (cap) chips.push([<CashIcon key="m" size={15} color={C.yellow} />, `$${cap}/mo`]);
  else if (answers.budget) chips.push([<CashIcon key="m" size={15} color={C.yellow} />, answers.budget]);
  if (zip) chips.push([<PinIcon key="z" size={15} color={C.yellow} />, zip]);
  const { facts } = useFacts(top?.car.id, top?.year);
  if (!top) return null;
  const p = priceFor(top.car, top.year);
  const range = p && !p.isNew ? fairRange(top.car, top.year) : null;
  const k = (n: number) => `$${Math.round(n / 1000)}K`;
  const recalls = facts?.recalls?.length;
  const peace: [React.ReactNode, string][] = [];
  if (facts?.stars) peace.push([<ShieldCheckIcon key="s" size={15} color={C.yellow} />, `${facts.stars}★ safety`]);
  if (recalls != null) peace.push([<WrenchIcon key="r" size={15} color={C.yellow} />, recalls ? `${recalls} recalls · fixed free` : 'No recalls']);
  if (facts?.mpg) peace.push([<CarIcon key="m" size={15} color={C.yellow} />, `${facts.mpg.combined} ${facts.mpg.fuel === 'EV' ? 'MPGe' : 'MPG'}`]);
  const pay = p ? paymentFor(answers, p.amount, p.isNew) : 0;
  const ring = cap && p
    ? { pct: pay / cap, big: money(pay), small: `of $${cap}/mo`, over: pay > cap }
    : { pct: top.fit / 100, big: `${top.fit}%`, small: 'match', over: false };
  const room = cap && p ? (pay <= cap ? `${money(cap - pay)} a month to spare` : `${money(pay - cap)} over your plan`) : '';
  return (
    <View>
      {chips.length > 0 && (
        <View style={s.chipRow}>
          {chips.map(([icon, text]) => (
            <View key={text} style={s.planChip}>{icon}<Text style={s.planChipText} numberOfLines={1}>{text}</Text></View>
          ))}
        </View>
      )}
      <Pressable onPress={() => { tap(); router.push({ pathname: '/results', params: { upgrade: '0' } }); }} accessibilityRole="button" style={({ pressed }) => [s.matchCard, pressed && { opacity: 0.9 }]}>
        <Ring pct={ring.pct} big={ring.big} small={ring.small} over={ring.over} size={92} />
        <View style={{ flex: 1 }}>
          <Text style={s.k}>Your top match · {top.fit}%</Text>
          <Text style={s.matchName} numberOfLines={2}>{carName(top.car, top.year)}</Text>
          <Text style={s.k}>{p ? (p.isNew ? `From ${money(p.amount)}` : `${money(p.amount)} est.`) : 'Ask dealer'}{room ? ` · ${room}` : ''}</Text>
          {range ? <View style={[s.planChip, { alignSelf: 'flex-start', marginTop: 6, paddingVertical: 4 }]}><Text style={s.planChipText}>{`Fair price ${k(range[0])}–${k(range[1])}`}</Text></View> : null}
          <Text style={[s.seeTop, { marginTop: 6 }]}>See your top 3 ›</Text>
        </View>
      </Pressable>
      {peace.length > 0 && (
        <View style={[s.chipRow, { marginTop: 10 }]}>
          {peace.map(([icon, text]) => (
            <View key={text} style={s.planChip}>{icon}<Text style={s.planChipText} numberOfLines={1}>{text}</Text></View>
          ))}
        </View>
      )}
    </View>
  );
}

