// Create free account (picture 106, set 2): what you get, then Google or email. Searching and safety stay open without it.
import { router } from 'expo-router';
import { useState } from 'react';
import { Platform, ScrollView, StyleSheet, View } from 'react-native';

import { AccountTop, BigBtn, Card, IconBox, type Tint } from '@/components/account-ui';
import { BellIcon, CarIcon, TagIcon, WrenchIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { tap } from '@/components/ui';
import { supabase } from '@/lib/supabase';
import { ConfirmCode } from '@/components/confirm-code';
import { NEED_CODE, useAuth } from '@/state/auth';
import { C, F, PAD, themed } from '@/theme';
import { Pressable, Text, TextInput } from '@/components/t';

const PERKS: [string, Tint, typeof BellIcon][] = [['Recall alerts for your car', 'blue', BellIcon], ['Oil and registration reminders', 'green', WrenchIcon], ['Price drops on saved cars', 'red', TagIcon], ['Your car, dealer and saves on any phone', 'amber', CarIcon]];

export default function Join() {
  const { signUp, signInWithGoogle, openSignIn } = useAuth();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [pw, setPw] = useState('');
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [needCode, setNeedCode] = useState(false); // picture 184 A: the email code step
  const done = () => { notify('Welcome to Carvessa!', 'Your free account is ready.'); router.navigate('/me'); };
  const submit = async () => {
    setErr(null);
    if (!name.trim()) return setErr('Type your first name.');
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) return setErr('Type your email.');
    if (pw.length < 8) return setErr('Use a password with at least 8 characters.');
    setBusy(true);
    const e = await signUp(name, email, pw);
    setBusy(false);
    if (e === NEED_CODE) return setNeedCode(true);
    if (e) return setErr(e);
    done();
  };
  const google = async () => {
    const e = await signInWithGoogle();
    if (e) return setErr(e);
    const { data } = await supabase.auth.getSession();
    if (data.session) done();
  };
  return (
    <View style={{ flex: 1, backgroundColor: C.bg }}>
      <AccountTop title="Create free account" />
      <ScrollView contentContainerStyle={{ paddingHorizontal: PAD - 6, paddingBottom: 30 }} keyboardShouldPersistTaps="handled">
        {needCode ? <View style={{ marginTop: 8, marginHorizontal: 4 }}><ConfirmCode email={email} onDone={done} onBack={() => setNeedCode(false)} /></View> : (<>
        <Text style={s.h}>Make Carvessa yours.</Text>
        <Text style={s.sub}>Free. 30 seconds. Searching and safety info stay open without an account.</Text>
        <Card style={{ paddingVertical: 4 }}>
          {PERKS.map(([t, tn, Icon]) => (
            <View key={t} style={s.perk}><IconBox t={tn}>{(c) => <Icon size={17} color={c} />}</IconBox><Text style={s.perkT}>{t}</Text></View>
          ))}
        </Card>
        {Platform.OS !== 'web' && <><BigBtn kind="plain" label="Continue with Google" onPress={google} /><Text style={s.or}>or with email</Text></>}
        <TextInput value={name} onChangeText={setName} placeholder="First name" placeholderTextColor={C.muted} style={s.in} maxLength={40} accessibilityLabel="First name" autoComplete="given-name" />
        <TextInput value={email} onChangeText={setEmail} placeholder="you@email.com" placeholderTextColor={C.muted} style={s.in} keyboardType="email-address" autoCapitalize="none" accessibilityLabel="Email" autoComplete="email" />
        <TextInput value={pw} onChangeText={setPw} placeholder="Password · 8+ letters" placeholderTextColor={C.muted} style={s.in} secureTextEntry accessibilityLabel="Password" autoComplete="new-password" />
        {!!err && <Text style={s.err}>{err}</Text>}
        <BigBtn label={busy ? 'Creating…' : 'Create free account'} onPress={submit} />
        <Pressable onPress={() => { tap(); openSignIn(undefined, 'login'); }} accessibilityRole="button" style={{ alignItems: 'center', paddingTop: 12 }}>
          <Text style={s.login}>I have an account · Log in</Text>
        </Pressable>
        <Text style={s.fine}>By joining you agree to the Terms and Privacy.</Text>
        </>)}
      </ScrollView>
    </View>
  );
}

const s = themed(() => StyleSheet.create({
  h: { fontFamily: F.head, fontSize: 25, color: C.ink, marginHorizontal: 4, marginTop: 4 },
  sub: { fontFamily: F.body, fontSize: 14, color: C.muted, marginHorizontal: 4, marginTop: 4, marginBottom: 12 },
  perk: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 8 },
  perkT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink, flex: 1 },
  or: { fontFamily: F.body, fontSize: 12.5, color: C.muted, textAlign: 'center', marginTop: 12 },
  in: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink, marginTop: 10 },
  err: { fontFamily: F.bodyBold, fontSize: 14, color: C.red, marginTop: 10 },
  login: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.onAccent },
  fine: { fontFamily: F.body, fontSize: 11.5, color: C.muted, textAlign: 'center', marginTop: 10 },
}));
