import { useQuickUpgrade } from '@/state/quick-upgrade';
// My Garage · your own car: real recalls, a maintenance guide, and a registration countdown.
import { router } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Linking, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon, BellIcon, WrenchIcon } from '@/components/icons';
import { Body, Btn, H, Label, SquareBtn, tap } from '@/components/ui';
import { Recall, recallsForMyCar } from '@/data/gov';
import { RecallDealer } from '@/components/recall-dealer';
import { CarSheet } from '@/components/car-sheet';
import { Card, ToggleRow } from '@/components/account-ui';
import { notify } from '@/components/notify';
import { useAlerts } from '@/state/alerts';
import { useAuth } from '@/state/auth';

import { milesUntil, UPKEEP } from '@/data/upkeep';
import { useAnswers } from '@/state/answers';
import { MyCar, useSaved } from '@/state/saved';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, TextInput } from '@/components/t';
import { OwnerProblems, RecallCard } from '@/components/owner-problems';
import { useRefreshTick } from '@/lib/refresh';
import { usePullRefresh } from '@/components/pull-refresh';

function Field({ label, value, onChange, placeholder, numeric }: { label: string; value: string; onChange: (v: string) => void; placeholder: string; numeric?: boolean }) {
  return (
    <View style={{ flex: 1 }}>
      <Label style={{ fontSize: 10.5, color: C.muted, marginBottom: 4 }}>{label}</Label>
      <TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor="#999" accessibilityLabel={label}
        keyboardType={numeric ? 'number-pad' : 'default'} style={s.input} autoCorrect={false} />
    </View>
  );
}

const parseDate = (t?: string) => {
  const m = t?.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const d = new Date(Number(m[3]), Number(m[1]) - 1, Number(m[2]));
  return isNaN(d.getTime()) ? null : d;
};

function AddCar({ onSave }: { onSave: (c: MyCar) => void }) {
  const { answers } = useAnswers();
  const fromChat = answers.myCar?.match(/^(\d{4})\s+(\S+)\s+(.+)$/);
  const [year, setYear] = useState(fromChat?.[1] ?? '');
  const [make, setMake] = useState(fromChat?.[2] ?? '');
  const [model, setModel] = useState(fromChat?.[3] ?? '');
  const [miles, setMiles] = useState('');
  const ok = /^(19|20)\d\d$/.test(year) && make.trim() && model.trim();
  return (
    <View>
      <H size={34} style={{ marginTop: 14 }}>Add your car</H>
      <Body style={{ marginTop: 6 }}>Free. We check for recalls and show what’s due.</Body>
      <View style={s.formRow}>
        <Field label="Year" value={year} onChange={setYear} placeholder="2020" numeric />
        <Field label="Make" value={make} onChange={setMake} placeholder="Chevy" />
      </View>
      <View style={s.formRow}>
        <Field label="Model" value={model} onChange={setModel} placeholder="Trax" />
        <Field label="Miles (about)" value={miles} onChange={setMiles} placeholder="45000" numeric />
      </View>
      <Btn label="Save my car" style={{ marginTop: 16, opacity: ok ? 1 : 0.5 }}
        onPress={() => ok && onSave({ year: Number(year), make: make.trim(), model: model.trim(), miles: Number(miles) || undefined })} />
    </View>
  );
}

// Alerts for your car (free account, Oct 18, 2026): guests see the switches; turning one on asks for a free account.
function CarAlerts() {
  const { session, prefs, setPref, askAccount } = useAuth();
  const { alertsOn, busy, setAlertsOn } = useAlerts();
  const ask = () => askAccount('Get alerts for your car', 'Free account. We tell you the day a new recall comes out, and when it’s time for an oil change. No spam, never sold.');
  return (
    <Card style={{ marginTop: 14 }}>
      <ToggleRow icon={(c) => <BellIcon size={18} color={c} />} label="Recall alerts" sub="The day a new recall comes out" on={!!session && alertsOn} disabled={busy}
        onChange={async (v) => { if (!session) return ask(); const msg = await setAlertsOn(v); if (msg) notify('Recall alerts', msg); }} />
      <ToggleRow last t="green" icon={(c) => <WrenchIcon size={18} color={c} />} label="Maintenance reminders" sub="Oil, tires and registration" on={!!session && prefs.upkeep}
        onChange={(v) => (session ? setPref('upkeep', v) : ask())} />
    </Card>
  );
}

export default function MyCarScreen() {
  const pull = usePullRefresh();
  const { myCar, setMyCar, addCar, removeCar, activeCar } = useSaved();
  const [editing, setEditing] = useState(false);
  const quickUpgrade = useQuickUpgrade();
  const [recalls, setRecalls] = useState<{ key: string; list: Recall[] | null; error: boolean }>({ key: '', list: null, error: false });
  const [reg, setReg] = useState(myCar?.regDue ?? '');
  const [now] = useState(() => Date.now());
  const key = myCar ? `${myCar.year}-${myCar.make}-${myCar.model}` : '';
  const tick = useRefreshTick();

  useEffect(() => {
    if (!myCar) return;
    let live = true;
    recallsForMyCar(myCar.make, myCar.model, myCar.year)
      .then((list) => live && setRecalls({ key, list, error: false }))
      .catch(() => live && setRecalls({ key, list: null, error: true }));
    return () => { live = false; };
  }, [key, tick]); // eslint-disable-line react-hooks/exhaustive-deps

  const fresh = recalls.key === key;
  const due = parseDate(myCar?.regDue);
  const daysLeft = due ? Math.ceil((due.getTime() - now) / 86400000) : null;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="My car" back={() => router.navigate('/garage')} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => router.navigate('/garage')}><BackIcon /></SquareBtn>
          <Label>My car</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <ScrollView refreshControl={pull} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 30 }} keyboardShouldPersistTaps="handled">
        {!myCar ? (
          <AddCar onSave={(c) => addCar(c)} />
        ) : (
          <>
            <View style={s.card}>
              <Label style={{ color: C.yellow }}>{myCar.nick ? `“${myCar.nick}”` : 'Your car'}</Label>
              <H size={30} style={{ color: C.ink, marginTop: 2 }}>{myCar.year} {myCar.make} {myCar.model}</H>
              {!!myCar.miles && <Body style={{ color: C.muted }}>About {myCar.miles.toLocaleString('en-US')} miles</Body>}
            </View>

            <CarAlerts />
            {fresh && <RecallCard recalls={recalls.list} make={myCar.make} mode="own" good={false} />}

            <Label style={s.sec}>Recalls · from NHTSA</Label>
            {!fresh ? (
              <View style={s.box}><ActivityIndicator color={C.ink} /><Body>Checking for recalls…</Body></View>
            ) : recalls.error ? (
              <View style={s.box}><Body style={{ flex: 1 }}>Can’t check recalls right now. Check your internet, or the make and model spelling.</Body></View>
            ) : recalls.list && recalls.list.length ? (
              recalls.list.map((r) => (
                <View key={r.id} style={s.recall}>
                  <Label style={{ fontSize: 11 }}>{r.part.split(/[:/]/)[0]}</Label>
                  <Body style={{ fontSize: 13.5, marginTop: 4 }}>{r.summary}</Body>
                  {!!r.fix && <Body style={{ fontSize: 13, marginTop: 6 }}><Body bold style={{ fontSize: 13 }}>The fix: </Body>{r.fix}</Body>}
                  <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>Recall #{r.id} · Fixed free at a dealer</Body>
                </View>
              ))
            ) : (
              <View style={[s.box, { borderColor: C.green }]}><Body style={{ flex: 1 }}>No recalls found for the {myCar.year} {myCar.make} {myCar.model}.</Body></View>
            )}
            <Pressable onPress={() => Linking.openURL('https://www.nhtsa.gov/recalls')} accessibilityRole="link">
              <Body style={{ fontSize: 12.5, color: C.muted, marginTop: 8, textDecorationLine: 'underline' }}>Check your exact car by VIN at nhtsa.gov/recalls</Body>
            </Pressable>
            <RecallDealer myCar={myCar} setMyCar={setMyCar} />
            <OwnerProblems make={myCar.make} model={myCar.model} year={myCar.year} recalls={fresh ? recalls.list : null} mode="own" />

            <Label style={s.sec}>What’s due · general guide</Label>
            <>
            <View>
            {UPKEEP.map((u) => {
              const soonBy = milesUntil(myCar.miles, u.every);
              const soon = soonBy !== null && soonBy < 1000;
              return (
                <View key={u.what} style={s.row}>
                  <View style={{ flex: 1 }}>
                    <Body bold>{u.what}</Body>
                    <Body style={{ fontSize: 12.5, color: C.muted }}>{u.note}</Body>
                  </View>
                  {soonBy !== null && (
                    <View style={[s.pill, soon && { backgroundColor: C.accentSoft, borderColor: C.yellow }]}>
                      <Label style={{ fontSize: 10.5 }}>{soon ? 'Soon' : `in ~${Math.round(soonBy / 100) * 100} mi`}</Label>
                    </View>
                  )}
                </View>
              );
            })}
            <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>Your owner’s manual has the exact schedule for your car.</Body>
            </View>
            </>

            <Label style={s.sec}>Registration</Label>
            {daysLeft !== null && (
              <View style={[s.card, { backgroundColor: daysLeft <= 30 ? C.yellow : C.hero }]}>
                <H size={44} style={{ color: daysLeft <= 30 ? C.onAccent : C.yellow }}>{daysLeft < 0 ? 'Past due' : `${daysLeft} days`}</H>
                <Body style={{ color: daysLeft <= 30 ? C.onAccent : C.ink }}>{daysLeft < 0 ? 'Renew as soon as you can.' : `until your registration is due (${myCar.regDue}).`}</Body>
              </View>
            )}
            <View style={[s.formRow, { alignItems: 'flex-end' }]}>
              <Field label="Due date (MM/DD/YYYY)" value={reg} onChange={setReg} placeholder="11/06/2026" />
              <Btn small label="Save" style={{ width: 90 }} onPress={() => { if (parseDate(reg)) { tap(); setMyCar({ ...myCar, regDue: reg }); } }} />
            </View>
            <Body style={{ fontSize: 11.5, color: C.muted, marginTop: 6 }}>It’s on your registration card or renewal letter. Reminders by notification come with the next build.</Body>

            <Btn label="Upgrade this car" style={{ marginTop: 22 }} onPress={quickUpgrade} />
            <Pressable onPress={() => { tap(); setEditing(true); }} accessibilityRole="button" style={{ marginTop: 14, alignSelf: 'center' }}>
              <Body bold style={{ textDecorationLine: 'underline' }}>Edit or delete this car</Body>
            </Pressable>
          </>
        )}
      </ScrollView>
      </View>
      {editing && myCar && (
        <CarSheet car={myCar} onClose={() => setEditing(false)}
          onSave={(c) => { setMyCar(c); setReg(c.regDue ?? ''); setEditing(false); }}
          onDelete={() => { removeCar(activeCar); setEditing(false); router.navigate('/garage'); }} />
      )}
    </SafeAreaView>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: PAD, paddingTop: 10 },
  formRow: { flexDirection: 'row', gap: 8, marginTop: 12 },
  input: { height: 50, borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 16, color: C.ink },
  card: { backgroundColor: C.hero, padding: 14, marginTop: 14 },
  sec: { marginTop: 22, marginBottom: 6 },
  box: { flexDirection: 'row', gap: 10, alignItems: 'center', borderWidth: 2, borderColor: C.line, padding: 12 },
  recall: { backgroundColor: C.grey, padding: 12, marginTop: 6 },
  row: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 10, borderBottomWidth: 2, borderBottomColor: C.grey },
  pill: { borderWidth: 1, borderColor: C.line, borderRadius: 12, paddingHorizontal: 8, paddingVertical: 3 },
}));
