// Your profile picture (picture 131, Oct 24, 2026, Loudjier: "the user can add a profile pic too… default pictures
// they can choose… normal and fun"). Shows on Me, Edit profile and the bottom bar, only to you.
// Order: your choice (your own photo on this phone, one of our 24 pictures, or your letter), else your Google
// photo, else your first letter.
import { useState } from 'react';
import { Image, Modal, ScrollView, StyleSheet, View } from 'react-native';
import { SvgXml } from 'react-native-svg';

import { tint } from '@/components/account-ui';
import { notify } from '@/components/notify';
import { Pressable, Text } from '@/components/t';
import { tap } from '@/components/ui';
import { AVATARS, avatarById } from '@/data/avatars';
import { supabase } from '@/lib/supabase';
import { canPhoto, pickPhoto } from '@/lib/photo';
import { useAuth } from '@/state/auth';
import { setProfilePhoto, useProfilePhoto } from '@/state/profile-photo';
import { useSaved } from '@/state/saved';
import { C, F, themed } from '@/theme';

type Meta = { avatar?: string; avatar_url?: string; picture?: string } | undefined;

/** What they picked: on this phone first, else what their free account remembers. */
export function useAvatarChoice() {
  const { prefs } = useSaved();
  const { session } = useAuth();
  const meta = session?.user.user_metadata as Meta;
  return { choice: prefs.avatar ?? meta?.avatar, google: meta?.avatar_url ?? meta?.picture };
}

export function Letter({ name, size }: { name: string; size: number }) {
  const c = tint('blue');
  return (
    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: c.bg, alignItems: 'center', justifyContent: 'center' }}>
      <Text style={{ fontFamily: F.head, fontSize: size * 0.42, color: c.fg }}>{(name.trim()[0] ?? '?').toUpperCase()}</Text>
    </View>
  );
}

export function ProfilePic({ size, name }: { size: number; name: string }) {
  const { choice, google } = useAvatarChoice();
  const photo = useProfilePhoto();
  const [bad, setBad] = useState('');
  const round = { width: size, height: size, borderRadius: size / 2 };
  const art = avatarById(choice);
  let body: React.ReactNode;
  if (choice === 'photo' && photo) body = <Image source={{ uri: photo }} style={round} accessibilityIgnoresInvertColors />;
  else if (art) body = <SvgXml xml={art.xml} width={size} height={size} />;
  else if (choice !== 'letter' && google && bad !== google) body = <Image source={{ uri: google }} onError={() => setBad(google)} style={round} accessibilityIgnoresInvertColors />;
  else body = <Letter name={name || '?'} size={size} />;
  return <View style={round} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">{body}</View>;
}

/** Saves the choice on this phone and, for members, in the free account (never the photo itself). */
function useSaveChoice() {
  const { prefs, setPrefs } = useSaved();
  const { session } = useAuth();
  return (avatar: string) => {
    setPrefs({ ...prefs, avatar });
    if (session) supabase.auth.updateUser({ data: { avatar: avatar === 'photo' ? 'letter' : avatar } }).catch(() => {});
  };
}

/** "Your picture" sheet: your own photo, our Normal or Fun pictures, or your first letter. */
export function PicturePicker({ name, onClose }: { name: string; onClose: () => void }) {
  const { choice } = useAvatarChoice();
  const save = useSaveChoice();
  const [set, setSet] = useState<'normal' | 'fun'>(avatarById(choice)?.set ?? 'normal');
  const pick = (id: string) => { tap(); save(id); onClose(); };
  const own = async (from: 'camera' | 'library') => {
    const p = await pickPhoto(from, true);
    if (!p?.base64) return;
    if (!setProfilePhoto(`data:${p.mime ?? 'image/jpeg'};base64,${p.base64}`)) return notify('Your picture', 'That photo is too big. Try a closer one, or another photo.');
    save('photo');
    onClose();
  };
  return (
    <Modal transparent animationType="slide" visible onRequestClose={onClose}>
      <Pressable style={s.back} onPress={onClose} accessibilityLabel="Close" />
      <View style={s.sheet} accessibilityViewIsModal>
        <View style={s.grab} />
        <ScrollView style={{ maxHeight: 600 }}>
          <Text style={s.h} accessibilityRole="header">Your picture</Text>
          {canPhoto && (<>
            <Text style={s.k}>Your own photo</Text>
            <View style={{ flexDirection: 'row', gap: 8 }}>
              <Pressable onPress={() => own('camera')} accessibilityRole="button" style={s.btn}><Text style={s.btnT}>Take a photo</Text></Pressable>
              <Pressable onPress={() => own('library')} accessibilityRole="button" style={s.btn}><Text style={s.btnT}>Choose a photo</Text></Pressable>
            </View>
            <Text style={s.note}>Your photo stays on this phone. Only you see it.</Text>
          </>)}
          <Text style={s.k}>Or pick one of ours</Text>
          <View style={s.seg} accessibilityRole="tablist">
            {(['normal', 'fun'] as const).map((x) => (
              <Pressable key={x} onPress={() => { tap(); setSet(x); }} accessibilityRole="tab" accessibilityState={{ selected: set === x }} style={[s.segB, set === x && s.segOn]}>
                <Text style={[s.segT, set === x && { color: C.onAccent }]}>{x === 'normal' ? 'Normal' : 'Fun'}</Text>
              </Pressable>
            ))}
          </View>
          <View style={s.grid}>
            {AVATARS.filter((a) => a.set === set).map((a) => {
              const on = choice === a.id;
              return (
                <Pressable key={a.id} onPress={() => pick(a.id)} accessibilityRole="radio" accessibilityState={{ checked: on }} accessibilityLabel={a.name} style={s.cell}>
                  <View style={[s.ring, on && { borderColor: C.yellow }]}><SvgXml xml={a.xml} width={54} height={54} /></View>
                  <Text style={[s.cellT, on && { color: C.yellow, fontFamily: F.bodyBold }]} numberOfLines={1}>{a.name}</Text>
                </Pressable>
              );
            })}
          </View>
          <Pressable onPress={() => pick('letter')} accessibilityRole="button" style={s.letter}>
            <Letter name={name || '?'} size={34} />
            <Text style={s.letterT}>Just use my first letter</Text>
          </Pressable>
        </ScrollView>
      </View>
    </Modal>
  );
}

const s = themed(() => StyleSheet.create({
  back: { flex: 1, backgroundColor: 'rgba(15,26,42,0.45)' },
  sheet: { backgroundColor: C.card, borderTopLeftRadius: 26, borderTopRightRadius: 26, padding: 18, paddingBottom: 28 },
  grab: { alignSelf: 'center', width: 40, height: 5, borderRadius: 3, backgroundColor: C.line, marginBottom: 12 },
  h: { fontFamily: F.head, fontSize: 20, color: C.ink },
  k: { fontFamily: F.bodyBold, fontSize: 11.5, letterSpacing: 1, textTransform: 'uppercase', color: C.muted, marginTop: 16, marginBottom: 8 },
  btn: { flex: 1, backgroundColor: C.fill, borderRadius: 14, paddingVertical: 12, alignItems: 'center' },
  btnT: { fontFamily: F.bodyBold, fontSize: 14, color: C.onAccent },
  note: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 6 },
  seg: { flexDirection: 'row', backgroundColor: C.line, borderRadius: 12, padding: 3, marginBottom: 12 },
  segB: { flex: 1, alignItems: 'center', paddingVertical: 8, borderRadius: 10 },
  segOn: { backgroundColor: C.fill },
  segT: { fontFamily: F.bodyBold, fontSize: 14, color: C.muted },
  grid: { flexDirection: 'row', flexWrap: 'wrap', rowGap: 12 },
  cell: { width: '25%', alignItems: 'center', gap: 4 },
  ring: { borderRadius: 32, borderWidth: 3, borderColor: 'transparent', padding: 2 },
  cellT: { fontFamily: F.body, fontSize: 11.5, color: C.muted, maxWidth: 80 },
  letter: { flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 16, paddingVertical: 6 },
  letterT: { fontFamily: F.bodyBold, fontSize: 14.5, color: C.ink },
}));
