// Shared pieces for the free account screens (picture 106, set 2 "soft rainbow", day and night; Oct 18, 2026).
import { router } from 'expo-router';
import { StyleSheet, Switch, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { tap } from '@/components/ui';
import { C, F, isDarkLook, look, themed } from '@/theme';
import { Pressable, Text } from '@/components/t';

// One soft color per kind of thing: blue alerts, green car, red saved, amber dealer, purple reviews.
export type Tint = 'blue' | 'green' | 'red' | 'amber' | 'purple';
export function tint(t: Tint) {
  const night = isDarkLook(look);
  const day = { blue: ['#E3ECFA', '#1F5FBF'], green: ['#E3F1E8', '#1C6B40'], red: ['#FBE6E3', '#A3382A'], amber: ['#FFF1D6', '#7A5000'], purple: ['#EEE6FA', '#6A3FB5'] };
  const dark = { blue: ['#1E3150', '#9CC0F7'], green: ['rgba(95,211,140,0.16)', '#8FE0B0'], red: ['rgba(240,138,122,0.16)', '#F2A39A'], amber: ['rgba(242,196,107,0.16)', '#F2C46B'], purple: ['rgba(178,150,240,0.18)', '#C6B2F5'] };
  const [bg, fg] = (night ? dark : day)[t];
  return { bg, fg };
}

export function IconBox({ t, children }: { t: Tint; children: (color: string) => React.ReactNode }) {
  const c = tint(t);
  return <View style={[s.ic, { backgroundColor: c.bg }]}>{children(c.fg)}</View>;
}

/** Screen top with a round back button (account screens open from Me). */
export function AccountTop({ title, back = () => router.navigate('/me') }: { title: string; back?: () => void }) {
  const insets = useSafeAreaInsets();
  const c = tint('blue');
  return (
    <View style={[s.top, { paddingTop: insets.top + 10 }]}>
      <Pressable onPress={() => { tap(); back(); }} accessibilityRole="button" accessibilityLabel="Back" style={[s.back, { backgroundColor: c.bg }]}>
        <Text style={{ color: c.fg, fontSize: 22, lineHeight: 24, fontFamily: F.bodyBold }}>‹</Text>
      </Pressable>
      <Text style={s.title} accessibilityRole="header">{title}</Text>
      <View style={{ width: 38 }} />
    </View>
  );
}

export const Sec = ({ children }: { children: string }) => <Text style={s.sec}>{children}</Text>;
export const Card = ({ children, style }: { children: React.ReactNode; style?: object }) => <View style={[s.card, style]}>{children}</View>;

export function Row({ icon, t = 'blue', label, sub, value, onPress, last, danger }: { icon: (c: string) => React.ReactNode; t?: Tint; label: string; sub?: string; value?: string; onPress?: () => void; last?: boolean; danger?: boolean }) {
  const inner = (
    <>
      <IconBox t={danger ? 'red' : t}>{icon}</IconBox>
      <View style={{ flex: 1 }}>
        <Text style={[s.label, danger && { color: tint('red').fg }]}>{label}</Text>
        {!!sub && <Text style={s.sub}>{sub}</Text>}
      </View>
      {!!value && <Text style={s.value} numberOfLines={1}>{value}</Text>}
      {!!onPress && <Text style={s.chev}>›</Text>}
    </>
  );
  return onPress ? (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" style={[s.row, !last && s.line]}>{inner}</Pressable>
  ) : <View style={[s.row, !last && s.line]}>{inner}</View>;
}

export function ToggleRow({ icon, t = 'blue', label, sub, on, onChange, last, disabled }: { icon: (c: string) => React.ReactNode; t?: Tint; label: string; sub?: string; on: boolean; onChange: (v: boolean) => void; last?: boolean; disabled?: boolean }) {
  return (
    <View style={[s.row, !last && s.line]}>
      <IconBox t={t}>{icon}</IconBox>
      <View style={{ flex: 1 }}>
        <Text style={s.label}>{label}</Text>
        {!!sub && <Text style={s.sub}>{sub}</Text>}
      </View>
      <Switch value={on} disabled={disabled} onValueChange={onChange} accessibilityLabel={label}
        trackColor={{ true: C.yellow, false: C.line }} thumbColor="#FFFFFF" {...{ activeThumbColor: '#FFFFFF' }} />
    </View>
  );
}

export function Avatar({ name, size = 56 }: { name: string; size?: number }) {
  const c = tint('blue');
  return (
    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: c.bg, alignItems: 'center', justifyContent: 'center' }} accessibilityElementsHidden>
      <Text style={{ fontFamily: F.head, fontSize: size * 0.4, color: c.fg }}>{(name.trim()[0] ?? '?').toUpperCase()}</Text>
    </View>
  );
}

export function BigBtn({ label, onPress, kind = 'solid' }: { label: string; onPress: () => void; kind?: 'solid' | 'soft' | 'danger' | 'plain' }) {
  const night = isDarkLook(look);
  const bg = kind === 'solid' ? C.yellow : kind === 'soft' ? C.fill : kind === 'danger' ? tint('red').bg : C.card;
  const fg = kind === 'solid' ? (night ? '#0B1220' : '#FFFFFF') : kind === 'soft' ? C.onAccent : kind === 'danger' ? tint('red').fg : C.ink;
  return (
    <Pressable onPress={() => { tap(); onPress(); }} accessibilityRole="button" style={({ pressed }) => [s.big, { backgroundColor: bg }, kind === 'plain' && { borderWidth: 1, borderColor: C.line }, pressed && { opacity: 0.8 }]}>
      <Text style={[s.bigT, { color: fg }]}>{label}</Text>
    </Pressable>
  );
}

const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 16, paddingBottom: 10, backgroundColor: C.bg },
  back: { width: 38, height: 38, borderRadius: 19, alignItems: 'center', justifyContent: 'center' },
  title: { fontFamily: F.bodyBold, fontSize: 17, color: C.ink },
  sec: { fontFamily: F.bodyBold, fontSize: 11.5, letterSpacing: 1.4, color: C.muted, marginTop: 18, marginBottom: 8, marginLeft: 4, textTransform: 'uppercase' },
  card: { backgroundColor: C.card, borderRadius: 18, paddingHorizontal: 14, borderWidth: 1, borderColor: C.line },
  row: { flexDirection: 'row', alignItems: 'center', gap: 12, paddingVertical: 12 },
  line: { borderBottomWidth: 1, borderBottomColor: C.line },
  ic: { width: 34, height: 34, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },
  label: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  sub: { fontFamily: F.body, fontSize: 12.5, color: C.muted, marginTop: 1 },
  value: { fontFamily: F.bodyBold, fontSize: 13, color: C.muted, maxWidth: '45%' },
  chev: { fontFamily: F.bodyBold, fontSize: 20, color: C.muted },
  big: { borderRadius: 14, paddingVertical: 14, alignItems: 'center', marginTop: 10 },
  bigT: { fontFamily: F.bodyBold, fontSize: 16 },
}));
