// Words without dashes or dots: "CX-5" → ["cx5"], "Grand Cherokee L" → ["grand", "cherokee", "l"].
const words = (s: string) => s.toLowerCase().replace(/[-.]/g, '').split(/[^a-z0-9]+/).filter(Boolean);
const MAKES: Record<string, string> = { chevy: 'chevrolet', vw: 'volkswagen' };
const brand = (s: string) => { const n = words(s).join(''); return MAKES[n] ?? n; };

/** The cut-out for a scanned car, or undefined. The model's words must start with ours: "Grand Cherokee L" → Grand Cherokee. */
export function scanLook(make: string, model: string, year: number): ScanLook | undefined {
  const mk = brand(make), md = words(model);
  return SCAN_LOOKS.find((l) => brand(l.make) === mk && year >= l.from && year <= l.to
    && [l.model, ...l.aliases].some((m) => { const w = words(m); return w.length > 0 && w.every((x, i) => md[i] === x); }));
}
