// "Check a car you found" · style A "Check screen + report card" (picture 45, picked Oct 14, 2026).
// Opens from the card on Search. Scan the VIN (picture 51 C, /scan) or type a VIN (or year, brand, model), the asking price and miles;
// see a report card: price check (our estimate), recalls, safety, gas mileage, budget fit.
import { router, useLocalSearchParams } from 'expo-router';
import { useState } from 'react';
import { ActivityIndicator, KeyboardAvoidingView, Platform, ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BackIcon, CameraIcon, CheckIcon, GasIcon, WrenchIcon } from '@/components/icons';
import { Body, Btn, H, Label, SquareBtn, tap } from '@/components/ui';
import { OtdLine, VERDICT } from '@/components/price-box';
import { PriceGauge } from '@/components/fair-motion';
import { MONTHS, TIERS, payFor } from '@/data/afford';
import { BUDGETS } from '@/data/cars';
import { SELLER_QUESTIONS, checkCar, decodeVin, estimateRange, isVin, parseTyped, verdictFor, type Report } from '@/data/check';
import type { Listing } from '@/data/listings';
import { bandOf, money } from '@/data/prices';
import { canScan } from '@/lib/scan';
import { SameCar } from '@/components/same-car';
import { FeeCheck } from '@/components/fee-check';
import { PowerQuestions } from '@/components/power-questions';
import { ScannedCar } from '@/components/scanned-car';
import { OwnerProblems, RecallCard } from '@/components/owner-problems';
import { useAnswers } from '@/state/answers';
import { useSaved } from '@/state/saved';
import { useSaveToggle } from '@/state/save-gate';
import { calm, C, F, PAD, themed } from '@/theme';
import { sheet, SkyHeader } from '@/components/sky';
import { Pressable, Text, TextInput } from '@/components/t';
import { usePullRefresh } from '@/components/pull-refresh';

const num = (s: string) => Number(s.replace(/[^\d]/g, '')) || undefined;

export default function Check() {
  const { answers } = useAnswers();
  const { isSaved } = useSaved();
  const saveToggle = useSaveToggle();
  const [report, setReport] = useState<Report | null>(null);
  const [error, setError] = useState<string | null>(null);
  // A scanned VIN comes back from /scan (with `at`, so the same VIN can be scanned twice).
  // The miles can come from the scanner's found card too (picture 146).
  const { vin: scanned, at, miles: scannedMiles, price: sentPrice } = useLocalSearchParams<{ vin?: string; at?: string; miles?: string; price?: string }>();
  const [vin, setVin] = useState(scanned ?? '');
  const [gotScan, setGotScan] = useState(at);
  const [fromScan, setFromScan] = useState(!!scanned);
  const [price, setPrice] = useState(sentPrice && num(sentPrice) ? num(sentPrice)!.toLocaleString('en-US') : '');
  const [miles, setMiles] = useState(scannedMiles && num(scannedMiles) ? num(scannedMiles)!.toLocaleString('en-US') : '');
  if (at !== gotScan) {
    setGotScan(at);
    if (scanned) { setVin(scanned); setFromScan(true); setReport(null); setError(null); setMiles(scannedMiles && num(scannedMiles) ? num(scannedMiles)!.toLocaleString('en-US') : ''); setPrice(sentPrice && num(sentPrice) ? num(sentPrice)!.toLocaleString('en-US') : ''); }
  }
  const [typed, setTyped] = useState('');
  const [busy, setBusy] = useState(false);
  const [showRecalls, setShowRecalls] = useState(false);
  const [showQs, setShowQs] = useState(false);
  // Picture 151: the exact car found for sale (by its VIN), and the VIN we checked.
  const [checked, setChecked] = useState({ vin: '', scanned: false, run: 0 });
  const [dealerCar, setDealerCar] = useState<Listing | null>(null);
  // No price or miles typed? Use the dealer's, so the price check works.
  const useDealerCar = (c: Listing) => {
    setDealerCar(c);
    setReport((rep) => {
      if (!rep || rep.asking) return rep;
      const m = rep.miles ?? c.miles ?? undefined;
      const range = rep.found.car ? estimateRange(rep.found.car, rep.found.year, m) : undefined;
      return { ...rep, asking: c.price, miles: m, range, verdict: range ? verdictFor(c.price, range) : undefined };
    });
  };

  const run = async () => {
    tap(); setError(null); setReport(null); setShowRecalls(false); setShowQs(false); setDealerCar(null);
    const v = vin.trim().toUpperCase();
    if (!v && !typed.trim()) return setError('Type the VIN, or the year, brand and model (like 2018 Honda CR-V).');
    if (v && !isVin(v)) return setError('A VIN has 17 letters and numbers (never I, O or Q). Check it, or type the year, brand and model instead.');
    setBusy(true);
    try {
      const found = v ? await decodeVin(v) : parseTyped(typed);
      if (!found) { setBusy(false); return setError(v ? 'We couldn’t read that VIN. Check it, or type the year, brand and model.' : 'Type it like this: 2018 Honda CR-V'); }
      setReport(await checkCar(found, num(price), num(miles)));
      setChecked((c) => ({ vin: v, scanned: fromScan, run: c.run + 1 }));
    } catch {
      setError('Can’t reach the government car data right now. Check your internet and try again.');
    }
    setBusy(false);
  };

  // Pull down: check this car again with fresh government data (picture-free change, Oct 26, 2026).
  const pull = usePullRefresh(async () => {
    if (!report) return;
    const fresh = await checkCar(report.found, report.asking, report.miles).catch(() => null);
    if (fresh) { setReport(fresh); setChecked((c) => ({ ...c, run: c.run + 1 })); }
  });
  const r = report;
  const name = r ? `${r.found.year} ${r.found.make} ${r.found.model}${r.found.trim ? ` ${r.found.trim}` : ''}` : '';
  const apr = (TIERS.find((t) => t.tier === answers.credit) ?? TIERS[2]).used; // the car being checked is used
  const budget = BUDGETS.indexOf(answers.budget ?? '');
  const monthly = r?.asking ? payFor(r.asking, apr) : 0;
  const fits = r?.asking && budget >= 0 ? bandOf(r.asking) <= budget : null;
  const verdict = r?.verdict ? VERDICT[r.verdict] : null;
  const saved = r?.found.car ? isSaved(r.found.car.id, r.found.year) : false;

  return (
    <SafeAreaView edges={calm ? [] : ['top']} style={{ flex: 1, backgroundColor: C.bg }}>
      {calm ? <SkyHeader title="Check a car" back={() => (router.canGoBack() ? router.back() : router.navigate('/search'))} /> : (
        <View style={s.top}>
          <SquareBtn label="Back" onPress={() => (router.canGoBack() ? router.back() : router.navigate('/search'))}><BackIcon /></SquareBtn>
          <Label>Check a car</Label>
          <View style={{ width: 44 }} />
        </View>
      )}
      <View style={calm ? sheet.page : { flex: 1 }}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <ScrollView refreshControl={pull} contentContainerStyle={{ paddingHorizontal: PAD, paddingBottom: 40 }} keyboardShouldPersistTaps="handled">
          {!calm && <H size={32}>Check a car</H>}
          <Body style={{ color: C.muted, fontSize: 14 }}>From a dealer, a friend, or any website. We check it before you buy.</Body>

          {canScan && (
            <>
              <Btn kind="yellow" label="Scan the VIN" icon={<CameraIcon size={20} color={C.onAccent} />} onPress={() => { tap(); router.push('/scan'); }} style={{ marginTop: 16, height: 60 }} />
              <Text style={[s.hint, { textAlign: 'center' }]}>Point at the barcode on the driver’s door frame.</Text>
              <Text style={s.or}>or type it</Text>
            </>
          )}
          <Text style={s.label}>VIN (17 letters and numbers)</Text>
          <TextInput value={vin} onChangeText={(t) => { setVin(t.toUpperCase()); setFromScan(false); }} placeholder="Like 2HKRW2H54JH612345" placeholderTextColor={C.muted}
            autoCapitalize="characters" autoCorrect={false} maxLength={17} style={s.input} accessibilityLabel="VIN, 17 letters and numbers" />
          {fromScan && vin ? (
            <Text style={[s.hint, { color: C.green, fontFamily: F.bodyBold }]} accessibilityLiveRegion="polite">{price && miles ? '✓ Ready. Tap Check this car.' : miles ? '✓ Scanned. Add the price, then tap Check this car.' : '✓ Scanned. Add the price and miles, then tap Check this car.'}</Text>
          ) : (
            <Text style={s.hint}>On the window sticker, the listing, or the driver-side door.</Text>
          )}
          <Text style={s.or}>{canScan ? 'or' : 'or type it'}</Text>
          <Text style={s.label}>{canScan ? 'Or year, brand, model' : 'Year, brand, model'}</Text>
          <TextInput value={typed} onChangeText={setTyped} placeholder="Like 2018 Honda CR-V" placeholderTextColor={C.muted} style={s.input} accessibilityLabel="Year, brand and model" />
          <View style={{ flexDirection: 'row', gap: 10 }}>
            <View style={{ flex: 1 }}>
              <Text style={s.label}>Asking price</Text>
              <TextInput value={price} onChangeText={setPrice} placeholder="$19,500" placeholderTextColor={C.muted} keyboardType="number-pad" style={s.input} accessibilityLabel="Asking price in dollars" />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={s.label}>Miles</Text>
              <TextInput value={miles} onChangeText={setMiles} placeholder="61,000" placeholderTextColor={C.muted} keyboardType="number-pad" style={s.input} accessibilityLabel="Miles on the car" />
            </View>
          </View>
          {!!error && <Text style={s.error} accessibilityLiveRegion="polite">{error}</Text>}
          {busy ? <ActivityIndicator color={C.yellow} style={{ height: 56, marginTop: 14 }} /> : <Btn kind="yellow" label="Check this car" onPress={run} style={{ marginTop: 14 }} />}
          <Text style={[s.hint, { textAlign: 'center' }]}>We read the VIN with the U.S. government (NHTSA). Free.</Text>

          {r && (
            <View style={{ marginTop: 22 }} accessibilityLiveRegion="polite">
              <Label style={{ color: C.yellow }}>Car check</Label>
              <H size={26}>{name}</H>
              <Body style={{ color: C.muted, fontSize: 13 }}>
                {[r.miles ? `${r.miles.toLocaleString('en-US')} miles` : null, r.asking ? `asking ${money(r.asking)}` : null].filter(Boolean).join(' · ') || 'Add the price and miles for a price check.'}
              </Body>

              <RecallCard recalls={r.recalls} vin={checked.vin || undefined} make={r.found.make} />
              {checked.vin ? <ScannedCar key={`${checked.vin}-${checked.run}`} vin={checked.vin} scanned={checked.scanned} onCar={useDealerCar} /> : null}

              <View style={s.card}>
                <Text style={s.cardLabel}>Price check · estimate</Text>
                {r.range && r.asking && verdict ? (
                  <>
                    <PriceGauge range={r.range} at={r.asking} tag={r.verdict!} playKey={`check:${checked.run}:${r.asking}`} />
                    <Text style={[s.small, { textAlign: 'center', marginTop: 8 }]}>{verdict.line}</Text>
                    <OtdLine price={r.asking} />
                  </>
                ) : r.range ? (
                  <Text style={s.small}>Our estimate for this car: <Text style={{ fontFamily: F.bodyBold, color: C.ink }}>{money(r.range[0])}–{money(r.range[1])}</Text>. Add the asking price to compare.</Text>
                ) : (
                  <Text style={s.small}>We don’t have a price estimate for this car yet. Recalls below are from NHTSA.</Text>
                )}
              </View>

              {!dealerCar && <FeeCheck key={r.asking ?? 0} price={r.asking} />}

              <SameCar found={r.found} vin={checked.vin || undefined} asking={r.asking} miles={r.miles} here={dealerCar?.dealer} />

              <View style={s.card}>
                {r.recalls?.length !== 0 && <Pressable onPress={() => { if (r.recalls?.length) { tap(); setShowRecalls(!showRecalls); } }} accessibilityRole={r.recalls?.length ? 'button' : undefined} style={s.row}>
                  <View style={[s.icon, { backgroundColor: (r.recalls?.length ? '#B7791F' : C.green) + '22' }]}>{r.recalls?.length ? <WrenchIcon size={16} color="#B7791F" /> : <CheckIcon size={16} color={C.green} />}</View>
                  <View style={{ flex: 1 }}>
                    <Text style={s.rowTitle}>{r.recalls === null ? 'Couldn’t check recalls' : r.recalls.length ? `${r.recalls.length} recall${r.recalls.length === 1 ? '' : 's'} for this model year` : 'No recalls for this model year'}</Text>
                    <Text style={s.small}>{r.recalls?.length ? (showRecalls ? 'Tap to hide them.' : 'Ask the seller if they were fixed. Fixes are free at the dealer. Tap to see them.') : r.recalls === null ? 'Try again later, or check nhtsa.gov/recalls.' : 'From NHTSA.'}</Text>
                  </View>
                </Pressable>}
                {showRecalls && r.recalls?.map((x) => (
                  <View key={x.id} style={s.recall}><Text style={s.rowTitle}>{x.part.split(':')[0]}</Text><Text style={s.small}>{x.summary}</Text></View>
                ))}
                {r.stars !== undefined && (
                  <View style={s.row}>
                    <View style={[s.icon, { backgroundColor: C.yellow + '22' }]}><Text style={[s.iconText, { color: C.yellow }]}>★</Text></View>
                    <View style={{ flex: 1 }}><Text style={s.rowTitle}>{r.stars ? `${r.stars}★ safety rating` : 'Not crash-rated for this year'}</Text><Text style={s.small}>From NHTSA crash tests</Text></View>
                  </View>
                )}
                {!!r.mpg && (
                  <View style={s.row}>
                    <View style={[s.icon, { backgroundColor: C.green + '22' }]}><GasIcon size={16} color={C.green} /></View>
                    <View style={{ flex: 1 }}><Text style={s.rowTitle}>{r.mpg} MPG combined</Text><Text style={s.small}>From the EPA</Text></View>
                  </View>
                )}
                {!!r.asking && (
                  <View style={s.row}>
                    <View style={[s.icon, { backgroundColor: (fits === false ? C.red : C.green) + '22' }]}><Text style={[s.iconText, { color: fits === false ? C.red : C.green }]}>$</Text></View>
                    <View style={{ flex: 1 }}>
                      <Text style={s.rowTitle}>{fits === null ? `About ${money(monthly)} a month` : fits ? `Fits your budget (${answers.budget})` : `Over your budget (${answers.budget})`}</Text>
                      <Text style={s.small}>{fits === null ? '' : `About ${money(monthly)} a month · `}Estimate: {MONTHS / 12} years, {apr}% rate, with tax and fees, no money down</Text>
                    </View>
                  </View>
                )}
              </View>

              <OwnerProblems make={r.found.make} model={r.found.model} year={r.found.year} carId={r.found.car?.id} recalls={r.recalls} vin={checked.vin || undefined} />

              {r.found.power && <PowerQuestions power={r.found.power} year={r.found.year} />}

              <View style={{ flexDirection: 'row', gap: 10, marginTop: 12 }}>
                {r.found.car && (
                  <Btn kind="outline" label={saved ? '♥ Saved' : '♡ Save'} style={{ flex: 1 }} onPress={() => { tap(); saveToggle(r.found.car!.id, r.found.year); }} />
                )}
                <Btn kind="yellow" label="Questions to ask" style={{ flex: 2 }} onPress={() => { tap(); setShowQs(!showQs); }} />
              </View>
              {showQs && (
                <View style={s.card}>
                  <Text style={s.cardLabel}>Ask the seller</Text>
                  {SELLER_QUESTIONS.map((q, i) => <Text key={q} style={s.q}>{i + 1}. {q}</Text>)}
                </View>
              )}
              <Text style={[s.hint, { marginTop: 14 }]}>Prices are Carvessa estimates, not offers. Recalls and safety ratings are from NHTSA; gas mileage from the EPA. Always have a mechanic check a used car.</Text>
            </View>
          )}
        </ScrollView>
      </KeyboardAvoidingView>
      </View>
    </SafeAreaView>
  );
}


const s = themed(() => StyleSheet.create({
  top: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: PAD, paddingVertical: 10 },
  label: { fontFamily: F.bodyBold, fontSize: 14, color: C.ink, marginTop: 14 },
  input: { height: 52, borderRadius: 12, borderWidth: 1, borderColor: C.line, backgroundColor: C.card, paddingHorizontal: 14, fontFamily: F.body, fontSize: 16, color: C.ink, marginTop: 6 },
  hint: { fontFamily: F.body, fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 17 },
  or: { fontFamily: F.bodyBold, fontSize: 13, color: C.muted, textAlign: 'center', marginTop: 14 },
  error: { fontFamily: F.bodyBold, fontSize: 13.5, color: C.red, marginTop: 10 },
  card: { backgroundColor: C.card, borderWidth: 1, borderColor: C.line, borderRadius: 16, padding: 14, marginTop: 10 },
  cardLabel: { fontFamily: F.head, fontSize: 12, letterSpacing: 1.5, textTransform: 'uppercase', color: C.muted, marginBottom: 2 },
  verdict: { fontFamily: F.head, fontSize: 26, textTransform: 'uppercase' },
  range: { fontFamily: F.body, fontSize: 12, color: C.muted, textAlign: 'right' },
  small: { fontFamily: F.body, fontSize: 13, lineHeight: 18, color: C.muted, marginTop: 2 },
  row: { flexDirection: 'row', gap: 10, paddingVertical: 8 },
  icon: { width: 30, height: 30, borderRadius: 9, alignItems: 'center', justifyContent: 'center' },
  iconText: { fontFamily: F.bodyBold, fontSize: 15 },
  rowTitle: { fontFamily: F.bodyBold, fontSize: 15, color: C.ink },
  recall: { marginLeft: 40, paddingVertical: 6, borderTopWidth: 1, borderColor: C.line },
  q: { fontFamily: F.body, fontSize: 14.5, lineHeight: 21, color: C.ink, marginTop: 6 },
}));
