// A general upkeep guide. Every car is different, so the app always points to the owner's manual.
export const UPKEEP = [
  { what: 'Oil change', every: 6000, note: 'About every 5,000–7,500 miles' },
  { what: 'Tire rotation', every: 6000, note: 'About every 5,000–7,500 miles' },
  { what: 'Cabin air filter', every: 20000, note: 'About every 15,000–30,000 miles' },
  { what: 'Engine air filter', every: 30000, note: 'About every 30,000 miles' },
  { what: 'Brake check', every: 12000, note: 'About once a year' },
  { what: 'Wiper blades', every: 0, note: 'About every 6–12 months' },
  { what: 'Battery check', every: 0, note: 'Yearly after 3 years old' },
];

// Miles until each mileage-based item is due again (null when we don't know the miles).
export const milesUntil = (miles: number | undefined, every: number) => (miles && every ? every - (miles % every) : null);

// The next thing due, for the My car card on Garage.
// lastOil: the miles at their last oil change (from the service history), which beats our every-6,000 guess.
export function nextDue(miles?: number, lastOil?: number): { what: string; in: number; every: number } | null {
  let best: { what: string; in: number; every: number } | null = null;
  for (const u of UPKEEP) {
    const n = u.what === 'Oil change' && miles && lastOil && lastOil <= miles ? Math.max(0, lastOil + u.every - miles) : milesUntil(miles, u.every);
    if (n !== null && (!best || n < best.in)) best = { what: u.what, in: n, every: u.every };
  }
  return best;
}
