// My Garage pieces for My car plan (picture 167, Oct 30, 2026):
// MilesCard = the smart miles estimate (screen 16) + the monthly check switch (screen 17);
// PlanCard = one card with My loan, Service history, What it's worth and Insurance.
import { router } from 'expo-router';
import { useState } from 'react';
import { Platform, StyleSheet, View } from 'react-native';

import { Card, Row, ToggleRow } from '@/components/account-ui';
import { BellIcon, CashIcon, ShieldCheckIcon, TagIcon, WrenchIcon } from '@/components/icons';
import { notify } from '@/components/notify';
import { Pressable, Text, TextInput } from '@/components/t';
import { Label, tap } from '@/components/ui';
import { dailyOf, howPaid, monthYear, payoffDate, MINUTE_CHOICES, milesFromMinutes, shortDate, DAILY, DAILY_CHOICES, DEFAULT_DAILY, estMiles, isEstimated, nextDue, tradeRange } from '@/data/car-plan';
import { allEntries, logLabel, monthTotals } from '@/data/car-log';
import { remDue, remName, sortReminders } from '@/data/car-reminders';
import { carForMine } from '@/data/cars';
import { tr } from '@/i18n';
import { canRemind } from '@/lib/reminders';
import { preOf, useAnswers } from '@/state/answers';
import { useAuth } from '@/state/auth';
import { type MyCar } from '@/state/saved';
import { C, F, themed } from '@/theme';

const mi = (n: number) => n.toLocaleString('en-US');
// Picture 221 A rows: what's coming up and what they spent (only what they typed).
function remSub(car: MyCar, now: number) {
  const on = sortReminders(car.reminders ?? [], now).filter((r) => !r.off);
  if (!on.length) return tr('Insurance, tag renewal, oil change… you pick when');
  return `${on.length} ${tr('on')} · ${tr('next')}: ${tr(remName(on[0]))}, ${shortDate(new Date(remDue(on[0], now)))}`;
}
function logSub(car: MyCar, now: number) {
  const all = allEntries(car);
  const t = monthTotals(all, now);
  const month = new Date(now).getMonth();
  if (t.total > 0) return `$${Math.round(t.total).toLocaleString('en-US')} ${tr('this month')} · ${[...new Set(all.filter((e) => new Date(e.at).getMonth() === month).map((e) => tr(logLabel(e.kind)).toLowerCase()))].slice(0, 3).join(', ')}`;
  if (all.length) return `${all.length} ${tr('logged')} · ${tr('last')}: ${tr(all[0].what ?? logLabel(all[0].kind))}`;
  return tr('Gas, car wash, service, receipts');
}
const k = (n: number) => `$${Math.round(n / 100) / 10}K`;

export function MilesCard({ car, now, onUpdate, onChange }: { car: MyCar; now: number; onUpdate: () => void; onChange: (c: MyCar) => void }) {
  const { session, askAccount } = useAuth();
  const { answers } = useAnswers();
  const usual = Math.round(dailyOf({ ...car, daily: car.daily ?? DAILY[answers.more?.daily ?? ''] ?? DEFAULT_DAILY }));
  const est = estMiles({ ...car, daily: car.daily ?? DAILY[answers.more?.daily ?? ''] ?? DEFAULT_DAILY }, now);
  const moving = isEstimated(car, now);
  const since = car.milesAt ? new Date(car.milesAt) : null;
  return (
    <Card style={{ marginTop: 10, paddingVertical: 12 }}>
      {est ? (<>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
          <Label style={s.l}>{moving ? 'Miles · estimate' : 'Miles'}</Label>
        </View>
        <Text style={s.big}>{`${moving ? '≈ ' : ''}${mi(est)} miles`}</Text>
        {moving && since && <Text style={s.small}>{`You typed ${mi(car.miles!)} on ${shortDate(since)}. Since then, about ${usual} miles a day. No tracking.`}</Text>}
      </>) : (<>
        <Label style={s.l}>Miles</Label>
        <Text style={s.small}>Add your miles and we count up a little each day. No tracking.</Text>
      </>)}
      <Pressable onPress={() => { tap(); onUpdate(); }} accessibilityRole="button" style={s.btn}>
        <Text style={s.btnT}>✎ Type my real miles</Text>
      </Pressable>
      {!!est && (<>
        <Driving car={car} onChange={onChange} />
        <ToggleRow last icon={(c) => <BellIcon size={18} color={c} />} label="Monthly mileage check" sub="One quick question a month, on a weekend morning" on={!!session && car.checkMiles !== false}
          onChange={async (v) => {
            if (!session) return askAccount('Keep your miles right', 'Free account. Once a month we ask “Is your mileage about …?” One tap. No spam, never sold.');
            if (v && Platform.OS !== 'web' && !(await canRemind(true))) return notify('Reminders are off', 'Alerts are off for Carvessa in your phone settings. Turn them on there, then try again.');
            onChange({ ...car, checkMiles: v });
          }} />
      </>)}
    </Card>
  );
}

// How much they drive: in minutes (what most people know: "20 minutes to work and back") or miles,
// a chip or their own number, and every day or workdays only. Loudjier, Oct 30, 2026.
function Driving({ car, onChange }: { car: MyCar; onChange: (c: MyCar) => void }) {
  const [mode, setMode] = useState<'min' | 'mi'>(car.daily && !car.dailyMin ? 'mi' : 'min');
  const [typing, setTyping] = useState(false);
  const [text, setText] = useState('');
  const choices = mode === 'min' ? MINUTE_CHOICES : DAILY_CHOICES;
  const picked = mode === 'min' ? car.dailyMin : !car.dailyMin ? car.daily : undefined;
  const set = (n: number) => {
    if (!n || n <= 0) return;
    tap();
    onChange(mode === 'min' ? { ...car, dailyMin: Math.round(n), daily: milesFromMinutes(n) } : { ...car, dailyMin: undefined, daily: Math.round(n) });
    setTyping(false); setText('');
  };
  const label = (n: number) => (mode === 'min' ? (n === 90 ? '90+ min' : `${n} min`) : n === 75 ? '70+ mi' : `${n} mi`);
  const custom = picked !== undefined && !choices.includes(picked);
  return (
    <View style={{ marginTop: 12 }}>
      <Text style={s.l}>HOW MUCH YOU DRIVE IN A DAY</Text>
      <View style={s.seg} accessibilityRole="tablist">
        {(['min', 'mi'] as const).map((m) => (
          <Pressable key={m} onPress={() => { tap(); setMode(m); setTyping(false); }} accessibilityRole="tab" accessibilityState={{ selected: mode === m }} style={[s.segB, mode === m && s.segOn]}>
            <Text style={[s.segT, mode === m && { color: C.onAccent }]}>{m === 'min' ? 'Minutes' : 'Miles'}</Text>
          </Pressable>
        ))}
      </View>
      <View style={s.chips}>
        {choices.map((d) => {
          const on = picked === d;
          return (
            <Pressable key={d} onPress={() => set(d)} accessibilityRole="radio" accessibilityState={{ checked: on }} style={[s.chip, on && s.chipOn]}>
              <Text style={[s.chipT, on && { color: C.onAccent }]}>{label(d)}</Text>
            </Pressable>
          );
        })}
        <Pressable onPress={() => { tap(); setTyping(true); }} accessibilityRole="button" style={[s.chip, custom && s.chipOn]}>
          <Text style={[s.chipT, custom && { color: C.onAccent }]}>{custom ? label(picked!) : 'Type it'}</Text>
        </Pressable>
      </View>
      {typing && (
        <View style={s.typeRow}>
          <TextInput value={text} onChangeText={setText} keyboardType="number-pad" autoFocus placeholder={mode === 'min' ? 'Minutes, like 20' : 'Miles, like 12'} placeholderTextColor={C.muted}
            accessibilityLabel={mode === 'min' ? 'Minutes a day' : 'Miles a day'} style={s.typeIn} onSubmitEditing={() => set(Number(text.replace(/[^\d]/g, '')))} />
          <Pressable onPress={() => set(Number(text.replace(/[^\d]/g, '')))} accessibilityRole="button" style={s.typeOk}><Text style={s.typeOkT}>Save</Text></Pressable>
        </View>
      )}
      <View style={s.chips}>
        {[false, true].map((w) => {
          const on = !!car.workdays === w;
          return (
            <Pressable key={String(w)} onPress={() => { tap(); onChange({ ...car, workdays: w || undefined }); }} accessibilityRole="radio" accessibilityState={{ checked: on }} style={[s.chip, on && s.chipOn]}>
              <Text style={[s.chipT, on && { color: C.onAccent }]}>{w ? 'Workdays only' : 'Every day'}</Text>
            </Pressable>
          );
        })}
      </View>
      <Text style={s.small}>{car.daily === undefined
        ? `Not picked yet: we use about ${DEFAULT_DAILY} miles a day, the U.S. average. Pick yours.`
        : car.dailyMin ? `${car.dailyMin} minutes ≈ ${car.daily} miles a day (at about 30 mph)${car.workdays ? ', on workdays' : ''}.`
        : `${car.daily} miles a day${car.workdays ? ', on workdays' : ''}.`}</Text>
    </View>
  );
}

export function PlanCard({ car, now }: { car: MyCar; now: number }) {
  const L = car.loan;
  const how = howPaid(car);
  const due = L?.left ? nextDue(L, new Date(now)) : null;
  const mine = carForMine(car.make, car.model);
  const r = mine ? tradeRange(mine, car.year, estMiles(car, now) ?? undefined) : null;
  return (<>
    <Label style={{ marginTop: 18, marginBottom: 8 }}>My car plan</Label>
    <Card>
      <Row t="amber" icon={(c) => <BellIcon size={18} color={c} />} label="Reminders" onPress={() => router.push('/reminders')} sub={remSub(car, now)} />
      <Row icon={(c) => <CashIcon size={18} color={c} />} label={how === 'lease' ? 'Leased' : how === 'own' ? 'Own it' : how === 'finance' ? 'Financed' : 'Finance, lease or own'} onPress={() => router.push('/loan')}
        sub={how === 'lease' ? (L!.left ? `Lease ends ${monthYear(payoffDate(L!, new Date(now)))} · next payment ${shortDate(due!)}` : 'Lease ended') : L ? (due ? `Next payment ${shortDate(due)} · $${mi(L.payment)}` : 'Paid off. Nice!') : how === 'own' ? '✓ Paid off · you own it' : 'Tell us how you pay for it: payments, reminders and more'} />
      <Row t="green" icon={(c) => <WrenchIcon size={18} color={c} />} label="Car log" onPress={() => router.push('/car-log')}
        sub={logSub(car, now)} />
      <Row t="amber" icon={(c) => <TagIcon size={18} color={c} />} label="What it’s worth" onPress={() => router.push('/value')}
        sub={r ? `About ${k(r[0])}–${k(r[1])} on trade-in, est.` : 'Trade-in value and upgrade ideas'} />
      <Row last t="purple" icon={(c) => <ShieldCheckIcon size={18} color={c} />} label="Insurance" onPress={() => router.push('/insure')}
        sub={car.insurer ? (car.insured ? `✓ Insured with ${car.insurer}` : `${car.insurer} · add your car before you drive it`) : 'Who’s your insurance? Get your car details ready'} />
    </Card>
  </>);
}

