  chips: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 6, marginBottom: 4 },
  chip: { borderWidth: 1, borderColor: C.line, borderRadius: 999, paddingHorizontal: 10, paddingVertical: 6, backgroundColor: C.card },
  chipOn: { backgroundColor: C.fill, borderColor: C.fill },
  chipT: { fontFamily: F.bodyBold, fontSize: 12, color: C.ink },
  seg: { flexDirection: 'row', backgroundColor: C.bg, borderRadius: 999, padding: 3, marginTop: 6, alignSelf: 'flex-start' },
  segB: { paddingHorizontal: 16, paddingVertical: 6, borderRadius: 999 },
