  segT: { fontFamily: F.bodyBold, fontSize: 12.5, color: C.muted },
  typeRow: { flexDirection: 'row', gap: 8, marginTop: 6 },
  typeIn: { flex: 1, height: 42, borderWidth: 1.5, borderColor: C.yellow, borderRadius: 12, paddingHorizontal: 12, fontFamily: F.bodyBold, fontSize: 15, color: C.ink, backgroundColor: C.card },
  typeOk: { backgroundColor: C.fill, borderRadius: 12, paddingHorizontal: 16, justifyContent: 'center' },
