// "Pre-approved? Add your rate" (picture 167 screen 15), on Search › Monthly and Cars that fit you.
export function PreLink() {
  const { answers } = useAnswers();
  const p = preOf(answers);
  return (
    <Pressable onPress={() => { tap(); router.push('/preapproved'); }} accessibilityRole="button" style={s.pre}>
      <Text style={s.preT}>{p ? `✓ Pre-approved at ${p.apr}% · up to $${p.upTo.toLocaleString('en-US')}` : 'Pre-approved by a lender? Add your rate'}</Text>
      <Text style={[s.preT, { color: C.yellow }]}>{p ? 'Edit ›' : '›'}</Text>
    </Pressable>
  );
}
